function hasTimeRemaining(
  options?: { deadlineAt?: number; minRemainingMs?: number },
  fallbackMinRemainingMs = 2_500,
): boolean {
  if (!options?.deadlineAt) return true;
  const minRemainingMs = options.minRemainingMs ?? fallbackMinRemainingMs;
