      max_slippage_sensitivity: 0.2,
      max_live_vs_backtest_decay: 0.35,
      min_tested_variants: 1,
    },
    retirement_rules: {
      min_expectancy_r: 0,
      min_rolling_expectancy_r: 0,
      min_profit_factor_after_costs: 1,
      max_drawdown: 12,
      max_top_1_profit_dependency: 0.55,
      max_top_3_profit_dependency: 0.8,
      min_result_without_top_1: -1,
      min_result_without_top_3: -2,
      max_slippage_sensitivity: 0.35,
      max_live_vs_backtest_decay: 0.5,
      target_state: "RETIRED",
    },
  });

export class InMemoryModelLifecycleStore implements ModelLifecycleStore {
  private records = new Map<string, ModelLifecycleRecord>();
  private auditEntries: ModelLifecycleAuditLogEntry[] = [];

  register(record: ModelLifecycleRecord): void {
    if (this.records.has(record.model_id)) {
      throw new Error(`Model ${record.model_id} is already registered`);
    }
    this.records.set(record.model_id, freezeRecord(record));
  }

  get(modelId: string): ModelLifecycleRecord | null {
    const record = this.records.get(modelId);
    return record ? freezeRecord(record) : null;
  }

  list(): ModelLifecycleRecord[] {
    return Array.from(this.records.values()).map(freezeRecord);
  }

  replace(record: ModelLifecycleRecord): void {
    if (!this.records.has(record.model_id)) {
      throw new Error(`Model ${record.model_id} is not registered`);
    }
    this.records.set(record.model_id, freezeRecord(record));
  }

  appendAudit(entry: ModelLifecycleAuditLogEntry): void {
    this.auditEntries.push(freezeAuditEntry(entry));
  }

  auditLog(modelId?: string): ModelLifecycleAuditLogEntry[] {
    return this.auditEntries
      .filter((entry) => !modelId || entry.model_id === modelId)
      .map(freezeAuditEntry);
  }
}

export class ModelLifecycleRegistry {
  private auditCounter = 0;

  constructor(
    private readonly config: ModelLifecycleConfig =
      DEFAULT_MODEL_LIFECYCLE_CONFIG,
    private readonly store: ModelLifecycleStore =
      new InMemoryModelLifecycleStore(),
    private readonly clock: () => Date = () => new Date(),
  ) {}

  registerModel(metadata: ModelMetadata): ModelLifecycleRecord {
    assertState(metadata.lifecycle_state);
    if (!metadata.model_id.trim()) {
      throw new Error("model_id is required");
    }
    if (!metadata.feature_hash.trim()) {
      throw new Error("feature_hash is required");
    }
    if (!metadata.parameter_hash.trim()) {
      throw new Error("parameter_hash is required");
    }

    const now = this.nowIso();
    const record = freezeRecord({
      ...metadata,
      parent_model_id: metadata.parent_model_id ?? null,
      registered_at: now,
      updated_at: now,
    });
    this.store.register(record);
    /* node:coverage ignore next */
    return record;
  }

  getModel(modelId: string): ModelLifecycleRecord | null {
    return this.store.get(modelId);
  }

  listModels(): ModelLifecycleRecord[] {
    return this.store.list();
  }

  getAuditLog(modelId?: string): ModelLifecycleAuditLogEntry[] {
    return this.store.auditLog(modelId);
  }

  evaluatePromotionGates(
    metrics: EvaluationMetrics,
    metadata: Pick<ModelMetadata, "number_of_tested_variants">,
  ): PromotionGateResult {
    return evaluatePromotionGates(metrics, metadata, this.config.promotion_rules);
  }

  evaluateRetirementRules(metrics: EvaluationMetrics): RetirementRuleResult {
    return evaluateRetirementRules(metrics, this.config.retirement_rules);
  }

  transitionModel(input: {
    model_id: string;
    new_state: ModelLifecycleState;
    metrics_snapshot: EvaluationMetrics;
    reason: string;
  }): ModelLifecycleRecord {
    const record = this.requireModel(input.model_id);
    assertState(input.new_state);
    if (record.lifecycle_state === "RETIRED") {
      throw new Error("Retired models cannot transition to a new state");
    }
    if (record.lifecycle_state === input.new_state) {
      throw new Error(`Model ${record.model_id} is already ${input.new_state}`);
    }
    if (!isAllowedTransition(record.lifecycle_state, input.new_state, this.config)) {
      throw new Error(
        `Transition ${record.lifecycle_state} -> ${input.new_state} is not allowed`,
      );
    }

    if (PROMOTION_TARGET_STATES.has(input.new_state)) {
      const gates = this.evaluatePromotionGates(input.metrics_snapshot, record);
      if (!gates.passed) {
        throw new Error(formatGateFailure("Promotion blocked", gates.failures));
      }
    }

    return this.commitTransition(record, input.new_state, input.metrics_snapshot, input.reason);
  }

  promoteToProduction(input: {
    candidate_model_id: string;
    metrics_snapshot: EvaluationMetrics;
    reason: string;
  }): ModelLifecycleRecord {
    const candidate = this.requireModel(input.candidate_model_id);
    const gates = this.evaluatePromotionGates(input.metrics_snapshot, candidate);
    if (!gates.passed) {
      throw new Error(formatGateFailure("Production promotion blocked", gates.failures));
    }
    if (!isAllowedTransition(candidate.lifecycle_state, "PRODUCTION", this.config)) {
      throw new Error(
        `Transition ${candidate.lifecycle_state} -> PRODUCTION is not allowed`,
      );
    }

    const existingProduction = this
      .store
      .list()
      .find((model) =>
        model.model_id !== candidate.model_id &&
        model.regime_scope === candidate.regime_scope &&
        model.lifecycle_state === "PRODUCTION"
      );

    if (existingProduction) {
      this.commitTransition(
        existingProduction,
        "WATCHLIST",
        input.metrics_snapshot,
        `Superseded by ${candidate.model_id}: ${input.reason}`,
      );
    }

    return this.commitTransition(
      candidate,
      "PRODUCTION",
      input.metrics_snapshot,
      input.reason,
    );
  }

  applyRetirementRules(input: {
    model_id: string;
    metrics_snapshot: EvaluationMetrics;
    reason: string;
  }): ModelLifecycleRecord | null {
    const record = this.requireModel(input.model_id);
    const result = this.evaluateRetirementRules(input.metrics_snapshot);
    if (!result.should_retire) {
      return null;
    }
    if (!isAllowedTransition(record.lifecycle_state, result.target_state, this.config)) {
      throw new Error(
        `Transition ${record.lifecycle_state} -> ${result.target_state} is not allowed`,
      );
    }
    return this.commitTransition(
      record,
      result.target_state,
      input.metrics_snapshot,
      `${input.reason}: ${result.failures.map((failure) => failure.message).join("; ")}`,
    );
  }

  canOpenNewTrades(modelId: string): boolean {
    const record = this.requireModel(modelId);
    return LIVE_STATES.has(record.lifecycle_state);
  }

  assertCanOpenNewTrades(modelId: string): void {
    const record = this.requireModel(modelId);
    if (!LIVE_STATES.has(record.lifecycle_state)) {
      throw new Error(
        `Model ${record.model_id} in ${record.lifecycle_state} cannot open new trades`,
      );
    }
  }

  async runShadowMode<TInput, TDecision>(input: {
    production_model_id: string;
    shadow_model_id: string;
    payload: TInput;
    production_decide: (payload: TInput) => Promise<TDecision> | TDecision;
    shadow_decide: (payload: TInput) => Promise<TDecision> | TDecision;
    record?: (result: ShadowModeResult<TInput, TDecision>) => Promise<void> | void;
  }): Promise<ShadowModeResult<TInput, TDecision>> {
    this.assertCanOpenNewTrades(input.production_model_id);
    const shadow = this.requireModel(input.shadow_model_id);
    if (shadow.lifecycle_state !== "SHADOW") {
      throw new Error(
        `Model ${shadow.model_id} must be SHADOW to run beside production`,
      );
    }

    const [productionDecision, shadowDecision] = await Promise.all([
      input.production_decide(input.payload),
      input.shadow_decide(input.payload),
    ]);

    const result: ShadowModeResult<TInput, TDecision> = {
      input: input.payload,
      production: {
        model_id: input.production_model_id,
        decision: productionDecision,
        send_orders: true,
      },
      shadow: {
        model_id: input.shadow_model_id,
        decision: shadowDecision,
        send_orders: false,
      },
    };
    await input.record?.(result);
    return result;
  }

  private requireModel(modelId: string): ModelLifecycleRecord {
    const record = this.store.get(modelId);
    if (!record) {
      throw new Error(`Model ${modelId} is not registered`);
    }
    return record;
  }

  private commitTransition(
    record: ModelLifecycleRecord,
    newState: ModelLifecycleState,
    metricsSnapshot: EvaluationMetrics,
    reason: string,
  ): ModelLifecycleRecord {
    const updated = freezeRecord({
      ...record,
      lifecycle_state: newState,
      updated_at: this.nowIso(),
    });
    this.store.replace(updated);
    this.store.appendAudit({
      audit_id: `audit-${++this.auditCounter}`,
      model_id: record.model_id,
      timestamp: this.nowIso(),
      old_state: record.lifecycle_state,
      new_state: newState,
      metrics_snapshot: freezeMetrics(metricsSnapshot),
      reason,
    });
    return updated;
  }

  private nowIso(): string {
    return this.clock().toISOString();
  }
}

export function loadModelLifecycleConfig(
  configPath = process.env.MODEL_LIFECYCLE_CONFIG ??
    path.resolve(process.cwd(), "config.yaml"),
): ModelLifecycleConfig {
  if (!fs.existsSync(configPath)) {
    return DEFAULT_MODEL_LIFECYCLE_CONFIG;
  }

  /* node:coverage ignore next 3 */
  const parsed = parseYaml(fs.readFileSync(configPath, "utf8")) as {
    model_lifecycle?: Partial<ModelLifecycleConfig>;
  } | null;
  return normalizeConfig(parsed?.model_lifecycle ?? {});
}

export function evaluatePromotionGates(
  metrics: EvaluationMetrics,
  metadata: Pick<ModelMetadata, "number_of_tested_variants">,
  rules: PromotionRules = DEFAULT_MODEL_LIFECYCLE_CONFIG.promotion_rules,
): PromotionGateResult {
  const failures: MetricGateFailure[] = [];
  const minExpectancy = Math.max(0, rules.min_expectancy_r);

  minGate(failures, "positive_out_of_sample_expectancy", "expectancy_r", metrics.expectancy_r, minExpectancy);
  minGate(failures, "rolling_expectancy", "rolling_expectancy_r", metrics.rolling_expectancy_r, rules.min_rolling_expectancy_r);
  minGate(failures, "profit_factor_after_costs", "profit_factor_after_costs", metrics.profit_factor_after_costs, rules.min_profit_factor_after_costs);
  maxGate(failures, "max_drawdown", "max_drawdown", metrics.max_drawdown, rules.max_drawdown);
  minGate(failures, "average_winner_r", "average_winner_r", metrics.average_winner_r, rules.min_average_winner_r);
  maxGate(failures, "average_loser_r", "average_loser_r", Math.abs(metrics.average_loser_r), rules.max_average_loser_r);
  maxGate(failures, "top_1_profit_dependency", "top_1_profit_dependency", metrics.top_1_profit_dependency, rules.max_top_1_profit_dependency);
  maxGate(failures, "top_3_profit_dependency", "top_3_profit_dependency", metrics.top_3_profit_dependency, rules.max_top_3_profit_dependency);
  minGate(failures, "result_without_top_1", "result_without_top_1", metrics.result_without_top_1, rules.min_result_without_top_1);
  minGate(failures, "result_without_top_3", "result_without_top_3", metrics.result_without_top_3, rules.min_result_without_top_3);
  maxGate(failures, "slippage_sensitivity", "slippage_sensitivity", metrics.slippage_sensitivity, rules.max_slippage_sensitivity);
  maxGate(failures, "live_vs_backtest_decay", "live_vs_backtest_decay", metrics.live_vs_backtest_decay, rules.max_live_vs_backtest_decay);
  minGate(failures, "tested_variants", "number_of_tested_variants", metadata.number_of_tested_variants, rules.min_tested_variants);

  return {
    passed: failures.length === 0,
    failures,
  };
}

export function evaluateRetirementRules(
  metrics: EvaluationMetrics,
  rules: RetirementRules = DEFAULT_MODEL_LIFECYCLE_CONFIG.retirement_rules,
): RetirementRuleResult {
  const failures: MetricGateFailure[] = [];

  retirementMinTrigger(failures, "expectancy_r", metrics.expectancy_r, rules.min_expectancy_r);
  retirementMinTrigger(failures, "rolling_expectancy_r", metrics.rolling_expectancy_r, rules.min_rolling_expectancy_r);
  retirementMinTrigger(failures, "profit_factor_after_costs", metrics.profit_factor_after_costs, rules.min_profit_factor_after_costs);
  retirementMaxTrigger(failures, "max_drawdown", metrics.max_drawdown, rules.max_drawdown);
  retirementMaxTrigger(failures, "top_1_profit_dependency", metrics.top_1_profit_dependency, rules.max_top_1_profit_dependency);
  retirementMaxTrigger(failures, "top_3_profit_dependency", metrics.top_3_profit_dependency, rules.max_top_3_profit_dependency);
  retirementMinTrigger(failures, "result_without_top_1", metrics.result_without_top_1, rules.min_result_without_top_1);
  retirementMinTrigger(failures, "result_without_top_3", metrics.result_without_top_3, rules.min_result_without_top_3);
  retirementMaxTrigger(failures, "slippage_sensitivity", metrics.slippage_sensitivity, rules.max_slippage_sensitivity);
  retirementMaxTrigger(failures, "live_vs_backtest_decay", metrics.live_vs_backtest_decay, rules.max_live_vs_backtest_decay);

  return {
    should_retire: failures.length > 0,
    target_state: rules.target_state,
    failures,
  };
}

export function calculateEvaluationMetrics(
  input: MetricCalculationInput,
): EvaluationMetrics {
  const costs = input.costs_r_per_trade ?? 0;
  const baseTrades = input.trade_results_r
    .map((value) => Number(value) - costs)
    .filter((value) => Number.isFinite(value));
  const slippage = input.slippage_r_per_trade ?? 0;
  const slippageTrades = input.high_slippage_results_r
    ? input.high_slippage_results_r.map((value) => Number(value) - costs)
    : baseTrades.map((value) => value - slippage);
  const rollingWindow = Math.max(1, Math.floor(input.rolling_window ?? 20));
  const rollingTrades = baseTrades.slice(-rollingWindow);
  const winners = baseTrades.filter((value) => value > 0);
  const losers = baseTrades.filter((value) => value < 0);
  const grossWins = winners.reduce((sum, value) => sum + value, 0);
  const grossLosses = Math.abs(losers.reduce((sum, value) => sum + value, 0));
  const expectancy = mean(baseTrades);
  const slippageExpectancy = mean(slippageTrades);
  const backtestExpectancy = input.backtest_expectancy_r ?? expectancy;
  const liveExpectancy = input.live_expectancy_r ?? expectancy;

  return {
    expectancy_r: round(expectancy),
    rolling_expectancy_r: round(mean(rollingTrades)),
    profit_factor_after_costs: round(
      grossLosses > 0 ? grossWins / grossLosses : grossWins > 0 ? 99 : 0,
    ),
    max_drawdown: round(maxDrawdownR(baseTrades)),
    average_winner_r: round(mean(winners)),
    average_loser_r: round(mean(losers)),
    ...calculateOutlierDependenceMetrics(baseTrades),
    slippage_sensitivity: round(Math.max(0, expectancy - slippageExpectancy)),
    live_vs_backtest_decay: round(
      backtestExpectancy > 0
        ? Math.max(0, (backtestExpectancy - liveExpectancy) / backtestExpectancy)
        : 0,
    ),
  };
}

export function calculateOutlierDependenceMetrics(
  tradeResultsR: number[],
): Pick<
  EvaluationMetrics,
  | "top_1_profit_dependency"
  | "top_3_profit_dependency"
  | "result_without_top_1"
  | "result_without_top_3"
> {
  const trades = tradeResultsR
    .map(Number)
    .filter((value) => Number.isFinite(value));
  const total = trades.reduce((sum, value) => sum + value, 0);
  const winners = trades.filter((value) => value > 0).sort((a, b) => b - a);
  const top1 = winners.slice(0, 1).reduce((sum, value) => sum + value, 0);
  const top3 = winners.slice(0, 3).reduce((sum, value) => sum + value, 0);
  const denominator = Math.max(Math.abs(total), 1e-9);

  return {
    top_1_profit_dependency: round(top1 / denominator),
    top_3_profit_dependency: round(top3 / denominator),
    result_without_top_1: round(total - top1),
    result_without_top_3: round(total - top3),
  };
}

export function isAllowedTransition(
  oldState: ModelLifecycleState,
  newState: ModelLifecycleState,
  config: ModelLifecycleConfig = DEFAULT_MODEL_LIFECYCLE_CONFIG,
): boolean {
  assertState(oldState);
  assertState(newState);
  return config.state_machine[oldState]?.includes(newState) ?? false;
}

function normalizeConfig(input: Partial<ModelLifecycleConfig>): ModelLifecycleConfig {
  return deepFreeze({
    state_machine: normalizeStateMachine(input.state_machine),
    promotion_rules: {
      ...DEFAULT_MODEL_LIFECYCLE_CONFIG.promotion_rules,
      ...(input.promotion_rules ?? {}),
    },
    retirement_rules: {
      ...DEFAULT_MODEL_LIFECYCLE_CONFIG.retirement_rules,
      ...(input.retirement_rules ?? {}),
    },
  });
}

function normalizeStateMachine(
  input: Partial<Record<ModelLifecycleState, ModelLifecycleState[]>> | undefined,
): Record<ModelLifecycleState, ModelLifecycleState[]> {
  const merged = {
    ...DEFAULT_MODEL_LIFECYCLE_CONFIG.state_machine,
    ...(input ?? {}),
  };

  for (const state of MODEL_LIFECYCLE_STATES) {
    assertState(state);
    merged[state] = (merged[state] ?? []).map((candidate) => {
      assertState(candidate);
      return candidate;
    });
  }

  return merged;
}

function assertState(state: string): asserts state is ModelLifecycleState {
  if (!MODEL_LIFECYCLE_STATES.includes(state as ModelLifecycleState)) {
    throw new Error(`Unknown model lifecycle state: ${state}`);
  }
}

function minGate(
  failures: MetricGateFailure[],
  gate: string,
  metric: MetricGateFailure["metric"],
  actual: number,
  threshold: number,
): void {
  if (actual < threshold) {
    failures.push({
      gate,
      metric,
      actual,
      threshold,
      message: `${String(metric)} ${actual} is below required ${threshold}`,
    });
  }
}

function maxGate(
  failures: MetricGateFailure[],
  gate: string,
  metric: keyof EvaluationMetrics,
  actual: number,
  threshold: number,
): void {
  if (actual > threshold) {
    failures.push({
      gate,
      metric,
      actual,
      threshold,
      message: `${metric} ${actual} exceeds allowed ${threshold}`,
    });
  }
}

function retirementMinTrigger(
  failures: MetricGateFailure[],
  metric: keyof EvaluationMetrics,
  actual: number,
  threshold: number,
): void {
  if (actual < threshold) {
    failures.push({
      gate: `retirement_${metric}`,
      metric,
      actual,
      threshold,
      message: `${metric} ${actual} fell below retirement threshold ${threshold}`,
    });
  }
}

function retirementMaxTrigger(
  failures: MetricGateFailure[],
  metric: keyof EvaluationMetrics,
  actual: number,
  threshold: number,
): void {
  if (actual > threshold) {
    failures.push({
      gate: `retirement_${metric}`,
      metric,
      actual,
      threshold,
      message: `${metric} ${actual} exceeded retirement threshold ${threshold}`,
    });
  }
}

function formatGateFailure(prefix: string, failures: MetricGateFailure[]): string {
  return `${prefix}: ${failures.map((failure) => failure.message).join("; ")}`;
}

function mean(values: number[]): number {
  return values.length
    ? values.reduce((sum, value) => sum + value, 0) / values.length
    : 0;
}

function maxDrawdownR(values: number[]): number {
  let equity = 0;
  let peak = 0;
  let maxDrawdown = 0;
  for (const value of values) {
    equity += value;
    peak = Math.max(peak, equity);
    maxDrawdown = Math.max(maxDrawdown, peak - equity);
  }
  return maxDrawdown;
}

function round(value: number): number {
  return Number((Number.isFinite(value) ? value : 0).toFixed(6));
}

function freezeRecord(record: ModelLifecycleRecord): ModelLifecycleRecord {
  return deepFreeze({
    ...record,
    training_window: { ...record.training_window },
    validation_window: { ...record.validation_window },
  });
}

function freezeAuditEntry(
  entry: ModelLifecycleAuditLogEntry,
): ModelLifecycleAuditLogEntry {
  return deepFreeze({
    ...entry,
    metrics_snapshot: freezeMetrics(entry.metrics_snapshot),
  });
}

function freezeMetrics(metrics: EvaluationMetrics): EvaluationMetrics {
  return deepFreeze({ ...metrics });
}

function deepFreeze<T>(value: T): T {
  if (value && typeof value === "object") {
    for (const nested of Object.values(value)) {
      deepFreeze(nested);
    }
    return Object.freeze(value);
  }
  return value;
}

export const SIGNAL_PIPELINE_STAGES = [
  "RAW_DATA",
  "FEATURE_EXTRACTION",
  "INDICATOR_CALCULATION",
  "SIGNAL_GENERATION",
  "PERCEPTION_ALIGNMENT",
  "RISK_FILTERING",
  "CONFIDENCE_SCORING",
  "POSITION_SIZING",
  "PARTICIPATION_GATING",
  "FINAL_DECISION",
  "BACKTEST_INCLUSION",
  "TRADE_EXECUTION_SIMULATION",
] as const;

export type SignalPipelineStage = (typeof SIGNAL_PIPELINE_STAGES)[number];

export type DiagnosticRuntimeMode =
  | "MODE_RAW_TECHNICAL"
  | "MODE_TECHNICAL_PLUS_RISK"
  | "MODE_FULL_PERCEPTION";

export type PipelineAuditEvent = {
  asset: string;
  timestamp: number | string;
  stage: SignalPipelineStage;
  passed: boolean;
  score?: number | null;
  threshold?: number | string | null;
  reason: string;
  metadata?: Record<string, unknown>;
};

export type ScoreDiagnosticSample = {
  asset: string;
  rawScore: number | null;
  normalizedScore: number | null;
  postFilterScore: number | null;
  finalConfidenceScore: number | null;
  reason?: string;
  metadata?: Record<string, unknown>;
};

type GateDependencyGraph = Record<string, string[]>;

export class SignalPipelineAuditTrail {
  private readonly memory: PipelineAuditEvent[] = [];
  private readonly enabled: boolean;
  private readonly debugMode: boolean;
  private readonly persistent: boolean;
  private readonly maxEvents: number;

  constructor(options: {
    enabled?: boolean;
    debug?: boolean;
    persistent?: boolean;
    maxEvents?: number;
  } = {}) {
    this.enabled = options.enabled === true || options.debug === true || options.persistent === true;
    this.debugMode = options.debug === true;
    this.persistent = options.persistent === true || this.debugMode;
    this.maxEvents = Math.max(0, Math.floor(options.maxEvents ?? 5_000));
  }

  emit(event: PipelineAuditEvent) {
    if (!this.enabled) return null;

    const normalized = normalizeAuditEvent(event);

    if (this.persistent && this.maxEvents > 0) {
      this.memory.push(normalized);
      this.memory.splice(0, Math.max(0, this.memory.length - this.maxEvents));
    }

    if (this.debugMode) {
      console.debug(JSON.stringify({ type: "signal.pipeline.audit", ...normalized }));
    }

    return normalized;
  }

  stage(input: Omit<PipelineAuditEvent, "timestamp"> & { timestamp?: number | string }) {
    return this.emit({ ...input, timestamp: input.timestamp ?? Date.now() });
  }

  events() {
    return this.memory.slice();
  }
}

export class SuppressionCascadeInspector {
  inspect(events: PipelineAuditEvent[], assets?: string[]) {
    const analytics = buildStageSurvivalAnalytics(events, assets);
    const eliminatingStage =
      analytics.stages.find((stage) => stage.reached > 0 && stage.passed === 0)?.stage ?? null;
    const warnings = [...analytics.warnings];

    if (eliminatingStage) {
      warnings.push(`Single-layer suppression detected at ${eliminatingStage}.`);
    }

    return {
      analytics,
      eliminatedBySingleLayer: Boolean(eliminatingStage),
      eliminatingStage,
      warnings,
    };
  }
}

export class RecursiveGateDetector {
  detect(dependencies: GateDependencyGraph) {
    const cycles: string[][] = [];
    const visited = new Set<string>();
    const active = new Set<string>();
    const stack: string[] = [];

    const visit = (node: string) => {
      if (active.has(node)) {
        const start = stack.indexOf(node);
        if (start >= 0) cycles.push([...stack.slice(start), node]);
        return;
      }

      if (visited.has(node)) return;

      visited.add(node);
      active.add(node);
      stack.push(node);

      for (const dependency of dependencies[node] ?? []) {
        visit(dependency);
      }

      stack.pop();
      active.delete(node);
    };

    for (const node of Object.keys(dependencies)) visit(node);

    const uniqueCycles = Array.from(
      new Map(cycles.map((cycle) => [cycle.join(">"), cycle])).values(),
    );

    return {
      hasCycle: uniqueCycles.length > 0,
      cycles: uniqueCycles,
      warnings: uniqueCycles.map((cycle) => `Recursive gate cycle detected: ${cycle.join(" -> ")}.`),
    };
  }
}

export class DeadlockAnalyzer {
  analyze(input: {
    events: PipelineAuditEvent[];
    assets?: string[];
    dependencies?: GateDependencyGraph;
  }) {
    const suppression = new SuppressionCascadeInspector().inspect(input.events, input.assets);
    const recursive = new RecursiveGateDetector().detect(input.dependencies ?? {});
    const bottleneck = suppression.analytics.bottleneck?.stage ?? null;
    const deadlocked = recursive.hasCycle || suppression.eliminatedBySingleLayer;
    const suggestedResolution = [
      recursive.hasCycle
        ? "Break recursive gating by making one gate depend on observable market evidence instead of downstream confirmations."
        : "",
      suppression.eliminatedBySingleLayer && suppression.eliminatingStage
        ? `Inspect thresholds and rejection reasons at ${suppression.eliminatingStage} before changing upstream scoring.`
        : "",
      bottleneck && bottleneck !== suppression.eliminatingStage
        ? `Review ${bottleneck} because it is the largest attrition point.`
        : "",
    ].filter(Boolean);

    return {
      deadlocked,
      cycles: recursive.cycles,
      bottleneck,
      warnings: [...suppression.warnings, ...recursive.warnings],
      suggestedResolution,
    };
  }
}

export class ScoreNormalizationDiagnostics {
  analyze(samples: ScoreDiagnosticSample[]) {
    const finiteFinals = finiteValues(samples.map((sample) => sample.finalConfidenceScore));
    const finiteRaw = finiteValues(samples.map((sample) => sample.rawScore));
    const finiteNormalized = finiteValues(samples.map((sample) => sample.normalizedScore));
    const finitePostFilter = finiteValues(samples.map((sample) => sample.postFilterScore));
    const midpointCount = samples.filter((sample) => {
      const score = finiteOrNull(sample.finalConfidenceScore);
      return score != null && score >= 49 && score <= 53;
    }).length;
    const fallbackCount = samples.filter((sample) => {
      const reason = String(sample.reason ?? sample.metadata?.reason ?? "").toLowerCase();
      const score = finiteOrNull(sample.finalConfidenceScore);
      return reason.includes("fallback") || reason.includes("nan") || (score != null && score >= 50 && score <= 52);
    }).length;
    const nanFallbackCount = samples.filter((sample) => {
      const reason = String(sample.reason ?? sample.metadata?.reason ?? "").toLowerCase();
      return reason.includes("nan") || [sample.rawScore, sample.normalizedScore, sample.postFilterScore, sample.finalConfidenceScore]
        .some((value) => value == null || !Number.isFinite(Number(value)));
    }).length;
    const clampedCount = samples.filter((sample) => {
      const score = finiteOrNull(sample.finalConfidenceScore);
      return score != null && (score <= 1 || score >= 99);
    }).length;
    const saturationCount = samples.filter((sample) => {
      const score = finiteOrNull(sample.normalizedScore);
      return score != null && (score <= 5 || score >= 95);
    }).length;
    const sampleCount = samples.length;
    const rawRange = rangeOrNull(finiteRaw);
    const normalizedRange = rangeOrNull(finiteNormalized);
    const postFilterRange = rangeOrNull(finitePostFilter);
    const finalRange = rangeOrNull(finiteFinals);
    const midpointCollapsePct = pct(midpointCount, sampleCount);
    const fallbackCollapsePct = pct(fallbackCount, sampleCount);
    const nanFallbackPct = pct(nanFallbackCount, sampleCount);
    const clampedPct = pct(clampedCount, sampleCount);
    const saturationPct = pct(saturationCount, sampleCount);
    const warnings: string[] = [];

    if (midpointCollapsePct >= 75) warnings.push(`${Math.round(midpointCollapsePct)}% of assets collapsed into the 49-53 confidence range.`);
    if (fallbackCollapsePct >= 50) warnings.push(`${Math.round(fallbackCollapsePct)}% of assets appear to use fallback confidence values.`);
    if (nanFallbackPct >= 10) warnings.push(`${Math.round(nanFallbackPct)}% of score samples contain NaN/null fallback evidence.`);
    if (rawRange != null && rawRange > 10 && normalizedRange != null && normalizedRange < 2) warnings.push("Raw score dispersion exists, but normalization compresses scores into a very narrow band.");
    if (finalRange != null && finalRange < 3 && finiteFinals.length >= 5) warnings.push("Final confidence scores have low dispersion; check denominator floors and midpoint defaults.");
    if (clampedPct >= 25) warnings.push(`${Math.round(clampedPct)}% of final confidence values are hard-clamped near 0 or 100.`);
    if (saturationPct >= 25) warnings.push(`${Math.round(saturationPct)}% of normalized scores are saturated near bounds.`);

    return {
      sampleCount,
      finiteFinalCount: finiteFinals.length,
      rawRange,
      normalizedRange,
      postFilterRange,
      finalRange,
      midpointCollapsePct,
      fallbackCollapsePct,
      nanFallbackPct,
      clampedPct,
      saturationPct,
      warnings,
      samples: samples.slice(),
    };
  }
}

function buildStageSurvivalAnalytics(events: PipelineAuditEvent[], assets?: string[]) {
  const normalizedEvents = events.map(normalizeAuditEvent);
  const allAssets = new Set([
    ...(assets ?? []).map(normalizeAsset).filter(Boolean),
    ...normalizedEvents.map((event) => normalizeAsset(event.asset)).filter(Boolean),
  ]);
  const universeSize = allAssets.size;
  const stages: any[] = [];
  let cumulative = universeSize;

  for (const stage of SIGNAL_PIPELINE_STAGES) {
    const stageEvents = normalizedEvents.filter((event) => event.stage === stage);
    const reachedAssets = new Set(stageEvents.map((event) => normalizeAsset(event.asset)).filter(Boolean));
    const passedAssets = new Set(stageEvents.filter((event) => event.passed).map((event) => normalizeAsset(event.asset)).filter(Boolean));
    const rejectedEvents = stageEvents.filter((event) => !event.passed);
    const reached = stageEvents.length ? reachedAssets.size : cumulative;
    const passed = stageEvents.length ? passedAssets.size : reached;
    const rejected = Math.max(0, reached - passed);
    const reasons = summarizeReasons(rejectedEvents, Math.max(1, rejectedEvents.length));

    stages.push({
      stage,
      reached,
      passed,
      rejected,
      survivalPct: pct(passed, reached),
      attritionPct: pct(rejected, reached),
      cumulativePassed: passed,
      cumulativeSurvivalPct: pct(passed, universeSize),
      dominantReason: reasons[0]?.reason ?? null,
      reasons,
    });
    cumulative = passed;
  }

  const bottleneck =
    stages
      .filter((stage) => stage.reached > 0 && stage.rejected > 0)
      .sort((a, b) => b.attritionPct - a.attritionPct || b.rejected - a.rejected)[0] ?? null;
  const warnings: string[] = [];

  if (bottleneck?.passed === 0) warnings.push(`${bottleneck.stage} eliminated every candidate that reached it.`);
  if (bottleneck && bottleneck.attritionPct >= 80) warnings.push(`${bottleneck.stage} rejected ${Math.round(bottleneck.attritionPct)}% of reached candidates.`);

  return {
    universeSize,
    stages,
    bottleneck,
    dominantRejectionStage: bottleneck?.stage ?? null,
    warnings,
  };
}

function normalizeAuditEvent(event: PipelineAuditEvent): PipelineAuditEvent {
  return {
    ...event,
    asset: normalizeAsset(event.asset) || "UNKNOWN",
    timestamp: event.timestamp ?? Date.now(),
    score: finiteOrNull(event.score),
    threshold: event.threshold ?? null,
    reason: String(event.reason || (event.passed ? "passed" : "rejected")),
    metadata: event.metadata ?? {},
  };
}

function summarizeReasons(events: PipelineAuditEvent[], denominator: number) {
  const counts = new Map<string, number>();
  for (const event of events) counts.set(event.reason, (counts.get(event.reason) ?? 0) + 1);
  return Array.from(counts.entries())
    .map(([reason, count]) => ({ reason, count, pct: pct(count, denominator) }))
    .sort((a, b) => b.count - a.count);
}

function normalizeAsset(value: unknown) {
  return String(value ?? "").trim().toUpperCase();
}

function finiteValues(values: Array<number | null | undefined>) {
  return values.map((value) => finiteOrNull(value)).filter((value): value is number => value != null);
}

function finiteOrNull(value: unknown) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function rangeOrNull(values: number[]) {
  if (!values.length) return null;
  return Math.max(...values) - Math.min(...values);
}

function pct(numerator: number, denominator: number) {
  return denominator > 0 ? (numerator / denominator) * 100 : 0;
}

