  survivalMemory?: StockSurvivalMemoryDiagnostic | null;
};

export type StockJudgementResult = JudgementResult & {
  survivalMemory?: StockSurvivalMemoryDiagnostic;
};

export type StockJudgementExposureGate = {
  allowsNewExposure: boolean;
  requiresReview: boolean;
  blocksNewExposure: boolean;
  exposureMultiplier: number;
  adjustedExposurePct: number;
  reasons: string[];
};

export function evaluateStockJudgement(input: StockJudgementInput): StockJudgementResult {
  const survivalMemory = input.survivalMemory ?? buildStockSurvivalMemory({
    market: input.market,
    symbol: input.symbol,
    rawAction: input.rawAction,
    setupQuality: input.setupQuality,
    riskPressure: input.riskPressure,
    volatilityPct: input.volatilityPct,
    liquidityScore: input.liquidityScore,
    expectedEdgePct: input.expectedEdgePct,
    rawSuggestedExposurePct: input.rawSuggestedExposurePct,
    maxPositionPct: input.readiness.maxPositionPct,
    readiness: input.readiness,
    trades: input.previousTrades,
    strategyHistory: input.strategyHistory,
    requireExplicitSurvivalFields: true,
  });
  const judgement = evaluateJudgement({
    currentState: currentStateFor(input),
    proposedDecision: {
      type: "stock-signal",
      action: input.rawAction,
      rawConfidence: input.calibratedConfidence,
      calibratedConfidence: input.calibratedConfidence,
      expectedEdgePct: input.expectedEdgePct,
      readinessStage: input.readiness.stage ?? "Unknown",
    },
    proposedAction: {
      kind: actionKindFor(input.rawAction),
      requestedExposurePct: input.rawSuggestedExposurePct,
      sizingDecision: input.sizingResult?.decision ?? "unknown",
      sizingMode: input.sizingResult?.mode ?? "none",
      sizedExposurePct: input.sizingResult?.size ?? 0,
    },
    historicalOutcomes: [
      ...tradeOutcomes(input),
      ...strategyHistoryOutcomes(input),
    ],
    traces: [
      ...forwardShadowTraces(input),
      ...opportunityTraces(input),
      ...agencyTraces(input),
    ],
    context: {
      market: input.market,
      symbol: input.symbol,
      rawConfidence: input.calibratedConfidence,
      calibratedConfidence: input.calibratedConfidence,
      minimumSimilarSamples: 5,
      strongSampleSize: 16,
      similarityThreshold: 0.42,
      overfitRisk: overfitRiskFor(input.readiness),
      calibrationStatus: input.readiness.calibration?.status,
      calibrationWarnings: input.readiness.calibration?.warnings ?? [],
    },
  });

  return applySurvivalMemoryToJudgement(
    judgement,
    survivalMemory,
    input.rawAction === "Buy" && input.expectedEdgePct > 0,
  );
}

export function judgementExposureGate(judgement: JudgementResult | null | undefined, exposurePct: number): StockJudgementExposureGate {
  if (!judgement) {
    return {
      allowsNewExposure: true,
      requiresReview: false,
      blocksNewExposure: false,
      exposureMultiplier: 1,
      adjustedExposurePct: roundPct(exposurePct),
      reasons: [],
    };
  }

  const blocksNewExposure = judgement.status === "blocked";
  const requiresReview = judgement.status === "review_required";
  const allowsNewExposure = !blocksNewExposure && !requiresReview;
  const confidenceRatio = judgement.rawConfidence > 0
    ? clamp(judgement.adjustedConfidence / judgement.rawConfidence, 0, 1)
    : 0;
  const exposureMultiplier = allowsNewExposure
    ? judgement.status === "trusted"
      ? confidenceRatio
      : Math.min(0.75, confidenceRatio)
    : 0;
  const adjustedExposurePct = roundPct(exposurePct * exposureMultiplier);

  return {
    allowsNewExposure,
    requiresReview,
    blocksNewExposure,
    exposureMultiplier: roundPct(exposureMultiplier),
    adjustedExposurePct,
    reasons: judgementReasons(judgement),
  };
}

export function judgementTrustForAgency(readinessTrust: number, judgement: JudgementResult | null | undefined) {
  const baseTrust = clamp(readinessTrust);
  if (!judgement) return baseTrust;
  if (judgement.status === "trusted") return roundPct(Math.max(baseTrust, judgement.trust));
  if (judgement.status === "cautious") return roundPct(Math.min(baseTrust, judgement.trust));
  return roundPct(Math.min(baseTrust, judgement.trust, judgement.adjustedConfidence));
}

export function judgementReasons(judgement: JudgementResult) {
  return [
    ...judgement.reasons,
    ...judgement.warnings.map((warning) => `Judgement warning: ${warning}.`),
  ];
}

function applySurvivalMemoryToJudgement(
  judgement: JudgementResult,
  survivalMemory: StockSurvivalMemoryDiagnostic,
  opensNewExposure: boolean,
): StockJudgementResult {
  if (!opensNewExposure || survivalMemory.recordCount === 0 || survivalMemory.scarCount === 0) {
    return { ...judgement, survivalMemory };
  }

  const penalty = clamp(survivalMemory.confidencePenalty, 0, 45);
  const adjustedConfidence = clamp(
    Math.min(judgement.adjustedConfidence - penalty, survivalMemory.survivalConfidence),
  );
  const trust = clamp(Math.min(judgement.trust - penalty * 0.6, survivalMemory.survivalConfidence));
  const reliability = clamp(Math.min(judgement.reliability, 100 - survivalMemory.averageSurvivalCost * 0.7));
  const outcomeStability = clamp(Math.min(judgement.outcomeStability, 100 - survivalMemory.averageSurvivalCost * 0.8));
  const overfitRisk = clamp(Math.max(judgement.overfitRisk, survivalMemory.averageSurvivalCost));
  const status: JudgementResult["status"] =
    survivalMemory.recommendation === "wait" && survivalMemory.exposureMultiplier === 0
      ? "blocked"
      : survivalMemory.recommendation === "wait"
        ? "review_required"
        : judgement.status === "trusted"
          ? "cautious"
          : judgement.status;
  const reasons = unique([
    ...judgement.reasons,
    ...survivalMemory.reasons,
    survivalMemory.mainWarnings.some((warning) => /profitable/i.test(warning))
      ? "Survival memory penalized confidence because similar states were profitable but had unacceptable drawdown."
      : "Survival memory capped confidence because similar states carried survival scars.",
  ]);
  const warnings = unique([
    ...judgement.warnings,
    "survival scars detected",
    ...survivalMemory.mainWarnings,
  ]);

  return {
    ...judgement,
    status,
    adjustedConfidence,
    trust,
    reliability,
    outcomeStability,
    overfitRisk,
    confidenceDelta: roundPct(adjustedConfidence - judgement.rawConfidence),
    reasons,
    warnings,
    survivalMemory,
  };
}

function currentStateFor(input: StockJudgementInput) {
  return {
    market: input.market,
    symbol: input.symbol,
    rawAction: input.rawAction,
    expectedEdgePct: input.expectedEdgePct,
    setupQuality: input.setupQuality,
    riskPressure: input.riskPressure,
    volatilityPct: input.volatilityPct,
    liquidityScore: input.liquidityScore ?? 70,
    readinessStage: input.readiness.stage ?? "Unknown",
    readinessScore: input.readiness.readinessScore ?? input.readiness.calibratedConfidence ?? input.calibratedConfidence,
    benchmarkExcessPct: input.readiness.benchmarks?.excessReturnAfterCostsPct ?? 0,
    liveSignalScore: input.readiness.components?.liveSignalConsistency?.score ?? 0,
    parameterPassRate: input.readiness.parameterStability?.passRate ?? 0,
    sizingDecision: input.sizingResult?.decision ?? "unknown",
    sizingMode: input.sizingResult?.mode ?? "none",
  };
}

function tradeOutcomes(input: StockJudgementInput): JudgementOutcome[] {
  return safeArray(input.previousTrades).map((trade, index) => {
    const record = objectOrEmpty(trade);
    const returnPct = firstNumber(record.returnPct, record.return_pct, record.profitPct, record.pnlPct, 0) as number;
    const symbol = String(record.symbol ?? record.ticker ?? input.symbol ?? `trade-${index}`).toUpperCase();

    return {
      id: String(record.id ?? `${symbol}-${index}`),
      state: {
        market: record.market ?? input.market,
        symbol,
        rawAction: record.signalAction ?? record.action ?? "Buy",
        setupQuality: firstNumber(record.setupQuality, input.setupQuality),
        riskPressure: firstNumber(record.riskPressure, input.riskPressure),
        volatilityPct: firstNumber(record.volatilityPct, input.volatilityPct),
        readinessStage: input.readiness.stage ?? "Unknown",
        benchmarkExcessPct: input.readiness.benchmarks?.excessReturnAfterCostsPct ?? 0,
      },
      decision: {
        type: "stock-signal",
        action: record.signalAction ?? record.action ?? "Buy",
        expectedEdgePct: firstNumber(record.expectedEdgePct, returnPct, input.expectedEdgePct),
      },
      action: {
        kind: "open_exposure",
        requestedExposurePct: firstNumber(record.entryExposure, record.exposurePct, input.rawSuggestedExposurePct),
      },
      outcome: {
        returnPct,
        success: returnPct > 0 ? true : returnPct < 0 ? false : null,
        label: returnPct > 0 ? "success" : returnPct < 0 ? "failure" : "neutral",
      },
      confidence: firstNumber(record.confidence, record.signalConfidence, record.rawConfidence, input.rawConfidence),
      metadata: {
        source: "previous-trade",
        survivalCost: firstNumber(record.survivalCost),
        outcomeClass: record.outcomeClass,
        maxDrawdown: firstNumber(record.maxDrawdown, record.maxDrawdownPct),
        maxAdverseExcursion: firstNumber(record.maxAdverseExcursion),
      },
    };
  });
}

function strategyHistoryOutcomes(input: StockJudgementInput): JudgementOutcome[] {
  return safeArray(input.strategyHistory).flatMap((entry, index) => {
    const record = objectOrEmpty(entry);
    const returnPct = firstNumber(record.returnPct, record.return_pct, record.portfolioReturnPct, record.changePct);
    if (returnPct == null) return [];

    return [{
      id: String(record.id ?? record.date ?? `history-${index}`),
      state: {
        market: input.market,
        rawAction: input.rawAction,
        readinessStage: input.readiness.stage ?? "Unknown",
        setupQuality: input.setupQuality,
        riskPressure: input.riskPressure,
        volatilityPct: input.volatilityPct,
      },
      decision: {
        type: "strategy-history",
        confidence: firstNumber(record.confidence, input.rawConfidence),
      },
      action: {
        kind: actionKindFor(input.rawAction),
        requestedExposurePct: input.rawSuggestedExposurePct,
      },
      outcome: {
        returnPct,
        success: returnPct > 0 ? true : returnPct < 0 ? false : null,
      },
      confidence: firstNumber(record.confidence, input.rawConfidence),
      metadata: {
        source: "strategy-history",
        survivalCost: firstNumber(record.survivalCost),
        outcomeClass: record.outcomeClass,
      },
    }];
  });
}

function forwardShadowTraces(input: StockJudgementInput): JudgementTrace[] {
  const shadow = input.forwardShadow;
  if (!shadow) return [];

  const evaluated = firstNumber(shadow.evaluatedSignalCount, shadow.evaluatedSignals, 0) as number;
  if (evaluated <= 0) return [];

  const averageReturnPct = firstNumber(shadow.averageReturnPct, shadow.meanReturnPct, 0) as number;
  return [{
    state: {
      market: input.market,
      rawAction: input.rawAction,
      readinessStage: input.readiness.stage ?? "Unknown",
      setupQuality: input.setupQuality,
      riskPressure: input.riskPressure,
    },
    decision: {
      type: "forward-shadow",
      confidence: input.calibratedConfidence,
    },
    action: {
      kind: actionKindFor(input.rawAction),
    },
    outcome: {
      returnPct: averageReturnPct,
      success: averageReturnPct > 0 ? true : averageReturnPct < 0 ? false : null,
    },
    confidence: input.calibratedConfidence,
    metadata: { source: "forward-shadow", sampleSize: evaluated },
  }];
}

function opportunityTraces(input: StockJudgementInput): JudgementTrace[] {
  return safeArray(input.opportunityCandidates).slice(0, 5).map((candidate, index) => {
    const record = objectOrEmpty(candidate);
    const score = firstNumber(record.candidateScore, record.score, 0) as number;
    return {
      id: String(record.symbol ?? record.id ?? `candidate-${index}`),
      state: {
        market: input.market,
        symbol: record.symbol ?? input.symbol,
        rawAction: input.rawAction,
        setupQuality: firstNumber(record.candidateScore, input.setupQuality),
        riskPressure: input.riskPressure,
      },
      decision: {
        type: "opportunity-candidate",
        confidence: score,
      },
      action: {
        kind: actionKindFor(input.rawAction),
      },
      outcome: {
        returnPct: firstNumber(record.expectedOutcome, record.expectedMove, input.expectedEdgePct),
        success: score >= 60,
      },
      confidence: score,
      metadata: { source: "opportunity-candidate" },
    };
  });
}

function agencyTraces(input: StockJudgementInput): JudgementTrace[] {
  const agency = input.agencyResult;
  if (!agency) return [];

  return [{
    state: {
      market: input.market,
      symbol: input.symbol,
      rawAction: input.rawAction,
      setupQuality: input.setupQuality,
      riskPressure: input.riskPressure,
    },
    decision: {
      type: "agency-audit",
      confidence: input.calibratedConfidence,
    },
    action: {
      kind: actionKindFor(input.rawAction),
    },
    outcome: {
      label: agency.allowed === true ? "success" : agency.requiresApproval === true ? "partial" : "failure",
    },
    confidence: input.calibratedConfidence,
    metadata: { source: "agency-audit" },
  }];
}

function overfitRiskFor(readiness: StockJudgementReadiness) {
  const robustness = readiness.robustnessDiagnostics ?? {};
  const explicit = firstNumber(
    robustness.overfitRisk,
    robustness.overfitRiskPct,
    robustness.overfitRiskScore,
  );
  const concentration = readiness.concentration?.outlierDependent
    ? Math.max(
        firstNumber(readiness.concentration.top1TradeContributionPct, 0) as number,
        firstNumber(readiness.concentration.top5TradeContributionPct, 0) as number,
      )
    : 0;
  const walkForwardRisk = readiness.walkForward?.stable === false ? 70 : 0;
  const parameterRisk = readiness.parameterStability?.stable === false
    ? 100 - (firstNumber(readiness.parameterStability.passRate, 0) as number)
    : 0;

  return clamp(Math.max(explicit ?? 0, concentration, walkForwardRisk, parameterRisk));
}

function actionKindFor(action: string) {
  if (action === "Buy") return "open_exposure";
  if (action === "Sell") return "reduce_exposure";
  return "observe";
}

function safeArray(value: unknown) {
  return Array.isArray(value) ? value : [];
}

function objectOrEmpty(value: unknown) {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
}

function firstNumber(...values: unknown[]) {
  for (const value of values) {
    const numberValue = Number(value);
    if (Number.isFinite(numberValue)) return numberValue;
  }
  return undefined;
}

function clamp(value: number, min = 0, max = 100) {
  return Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));
}

function roundPct(value: number) {
  return Math.round(value * 100) / 100;
}

function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

import {
  buildSurvivalMemoryRecord,
  evaluateSurvivalMemory,
  fingerprintSurvivalState,
  type SurvivalMemoryAnalysis,
  type SurvivalMemoryRecord,
  type SurvivalOutcomeClass,
} from "../../../signal-framework/survival-memory/engine";

export type StockSurvivalMemoryInput = {
  market?: string;
  symbol?: string;
  rawAction?: string;
  setupQuality?: number;
  riskPressure?: number;
  volatilityPct?: number;
  liquidityScore?: number;
  expectedEdgePct?: number;
  rawSuggestedExposurePct?: number;
  maxPositionPct?: number;
  readiness?: Record<string, any> | null;
  trades?: unknown[];
  strategyHistory?: unknown[];
  requireExplicitSurvivalFields?: boolean;
};

export type StockSurvivalMemoryDiagnostic = SurvivalMemoryAnalysis & {
  module: "stocks.survival-memory";
  name: "Survival Memory";
  maxExposurePct: number;
  stateFingerprint: string;
  records: SurvivalMemoryRecord[];
};

export type SurvivalEnrichedTrade<T> = T & {
  stateFingerprint: string;
  maxDrawdown: number;
  maxAdverseExcursion: number;
  recoveryTimeBars?: number;
  volatilityExpansion: number;
  tailRisk: number;
  liquidityStress: number;
  structuralDanger: number;
  novelty: number;
  opportunityDensity: number;
  outcomeClass: SurvivalOutcomeClass;
  survivalCost: number;
  scarWeight: number;
  survivalNotes?: string[];
};

export function buildStockSurvivalMemory(input: StockSurvivalMemoryInput): StockSurvivalMemoryDiagnostic {
  const currentState = stockSurvivalState(input);
  const stateFingerprint = fingerprintSurvivalState(currentState);
  const records = [
    ...recordsFromTrades(input.trades ?? [], input),
    ...recordsFromHistory(input.strategyHistory ?? [], input),
  ];
  const analysis = evaluateSurvivalMemory({
    records,
    currentState,
    stateFingerprint,
    similarityThreshold: 0.3,
  });
  const baseMaxExposure = clamp(firstNumber(input.maxPositionPct, input.readiness?.maxPositionPct, input.rawSuggestedExposurePct, 0));
  const maxExposurePct = round(baseMaxExposure * analysis.exposureMultiplier);

  return {
    ...analysis,
    module: "stocks.survival-memory",
    name: "Survival Memory",
    maxExposurePct,
    stateFingerprint,
    records,
  };
}

export function enrichTradesWithSurvivalMemory<T>(trades: T[], input: StockSurvivalMemoryInput = {}): Array<SurvivalEnrichedTrade<T>> {
  return trades.map((trade, index) => {
    const record = survivalRecordFromObject(trade, index, input, "trade");

    return {
      ...trade,
      stateFingerprint: record.stateFingerprint,
      maxDrawdown: record.maxDrawdown,
      maxAdverseExcursion: record.maxAdverseExcursion,
      recoveryTimeBars: record.recoveryTimeBars,
      volatilityExpansion: record.volatilityExpansion,
      tailRisk: record.tailRisk,
      liquidityStress: record.liquidityStress,
      structuralDanger: record.structuralDanger,
      novelty: record.novelty,
      opportunityDensity: record.opportunityDensity,
      outcomeClass: record.outcomeClass,
      survivalCost: record.survivalCost,
      scarWeight: record.scarWeight,
      ...(record.notes?.length ? { survivalNotes: record.notes } : {}),
    };
  });
}

function recordsFromTrades(trades: unknown[], input: StockSurvivalMemoryInput) {
  return trades.flatMap((trade, index) => {
    if (input.requireExplicitSurvivalFields && !hasExplicitSurvivalFields(trade)) return [];
    return [survivalRecordFromObject(trade, index, input, "trade")];
  });
}

function recordsFromHistory(history: unknown[], input: StockSurvivalMemoryInput) {
  return history.flatMap((entry, index) => {
    const record = objectOrEmpty(entry);
    if (input.requireExplicitSurvivalFields && !hasExplicitSurvivalFields(record)) return [];
    const returnPct = firstNumber(record.returnPct, record.return_pct, record.portfolioReturnPct, record.changePct);
    if (returnPct == null) return [];

    return survivalRecordFromObject({
      ...record,
      returnPct,
      symbol: input.symbol,
      market: input.market,
      entryExposure: firstNumber(record.deployedPct, input.rawSuggestedExposurePct, input.maxPositionPct, 0),
      riskPressure: firstNumber(record.riskPressure, input.riskPressure, record.drawdownPct, record.maxDrawdownPct, 0),
    }, index, input, "history");
  });
}

function hasExplicitSurvivalFields(value: unknown) {
  const record = objectOrEmpty(value);
  return [
    "survivalCost",
    "outcomeClass",
    "scarWeight",
    "maxDrawdown",
    "maxDrawdownPct",
    "maxAdverseExcursion",
    "maxAdverseExcursionPct",
    "recoveryTimeBars",
    "volatilityExpansion",
    "tailRisk",
    "liquidityStress",
    "structuralDanger",
  ].some((key) => record[key] !== null && record[key] !== undefined && record[key] !== "");
}

function survivalRecordFromObject(value: unknown, index: number, input: StockSurvivalMemoryInput, source: "trade" | "history"): SurvivalMemoryRecord {
  const record = objectOrEmpty(value);
  const symbol = String(record.symbol ?? record.ticker ?? input.symbol ?? `${source}-${index + 1}`).toUpperCase();
  const market = String(record.market ?? input.market ?? "").toUpperCase() || undefined;
  const realizedReturn = firstNumber(record.realizedReturn, record.returnPct, record.return_pct, record.profitPct, record.pnlPct, 0)!;
  const maxExposure = firstNumber(record.maxExposure, record.entryExposure, record.exposurePct, input.rawSuggestedExposurePct, input.maxPositionPct, 0)!;
  const riskPressure = clamp(firstNumber(record.riskPressure, input.riskPressure, 0)!);
  const volatilityPct = Math.max(0, firstNumber(record.volatilityPct, input.volatilityPct, riskPressure / 12, 0)!);
  const liquidityScore = clamp(firstNumber(record.liquidityScore, input.liquidityScore, 70)!);
  const maxDrawdown = firstNumber(
    record.maxDrawdown,
    record.maxDrawdownPct,
    record.drawdownPct,
    record.drawdown,
    record.maxAdverseExcursion,
    realizedReturn < 0 ? Math.abs(realizedReturn) : riskPressure * 0.16,
    0,
  )!;
  const maxAdverseExcursion = firstNumber(
    record.maxAdverseExcursion,
    record.maxAdverseExcursionPct,
    record.adverseExcursionPct,
    maxDrawdown,
    realizedReturn < 0 ? Math.abs(realizedReturn) : riskPressure * 0.2,
    0,
  )!;
  const structuralDanger = Math.max(
    firstNumber(record.structuralDanger, record.structuralRisk, 0)!,
    structuralDangerFor(input.readiness),
  );
  const recoveryTimeBars = firstNumber(
    record.recoveryTimeBars,
    record.recoveryBars,
    record.holdingBars,
    durationBars(record.entryDate, record.exitDate),
  );
  const state = stockSurvivalState({
    ...input,
    symbol,
    market,
    rawAction: String(record.signalAction ?? record.action ?? input.rawAction ?? "Buy"),
    setupQuality: firstNumber(record.setupQuality, input.setupQuality, 50)!,
    riskPressure,
    volatilityPct,
    liquidityScore,
    expectedEdgePct: realizedReturn,
    rawSuggestedExposurePct: maxExposure,
  });

  return buildSurvivalMemoryRecord({
    id: String(record.id ?? `${source}-${symbol}-${index + 1}`),
    timestamp: String(record.exitDate ?? record.date ?? record.timestamp ?? record.entryDate ?? ""),
    asset: symbol,
    venue: market,
    regime: String(record.regime ?? input.readiness?.stage ?? input.readiness?.readinessStage ?? "unknown"),
    state,
    stateFingerprint: typeof record.stateFingerprint === "string" ? record.stateFingerprint : undefined,
    action: String(record.signalAction ?? record.action ?? input.rawAction ?? "Buy"),
    maxExposure,
    realizedReturn,
    maxDrawdown,
    maxAdverseExcursion,
    recoveryTimeBars,
    volatilityExpansion: firstNumber(record.volatilityExpansion, record.volatilityShock, riskPressure, volatilityPct * 12, 0)!,
    tailRisk: firstNumber(record.tailRisk, record.tailPressure, Math.max(riskPressure, maxAdverseExcursion * 2), 0)!,
    liquidityStress: firstNumber(record.liquidityStress, record.liquidityPressure, 100 - liquidityScore, riskPressure * 0.45, 0)!,
    structuralDanger,
    novelty: firstNumber(record.novelty, noveltyFor(input.readiness), 0)!,
    opportunityDensity: firstNumber(
      record.opportunityDensity,
      input.maxPositionPct && input.maxPositionPct > 0 ? maxExposure / input.maxPositionPct * 100 : undefined,
      input.setupQuality,
      0,
    )!,
  });
}

function stockSurvivalState(input: StockSurvivalMemoryInput) {
  const readiness = input.readiness ?? {};
  const structuralDanger = structuralDangerFor(readiness);
  const liquidityStress = 100 - clamp(firstNumber(input.liquidityScore, 70)!);
  const riskPressure = clamp(firstNumber(input.riskPressure, input.volatilityPct != null ? input.volatilityPct * 12 : undefined, 0)!);

  return {
    venue: input.market,
    regime: readiness.stage ?? readiness.readinessStage ?? readiness.lifecycleStage,
    action: input.rawAction ?? "Buy",
    setupQuality: input.setupQuality,
    riskPressure,
    volatilityExpansion: firstNumber(input.volatilityPct != null ? input.volatilityPct * 12 : undefined, riskPressure, 0),
    liquidityStress,
    tailRisk: Math.max(riskPressure, Math.max(0, -number(input.expectedEdgePct)) * 5),
    structuralDanger,
    novelty: noveltyFor(readiness),
    opportunityDensity: input.maxPositionPct && input.maxPositionPct > 0
      ? number(input.rawSuggestedExposurePct) / input.maxPositionPct * 100
      : input.setupQuality,
  };
}

function structuralDangerFor(readiness: Record<string, any> | null | undefined) {
  const concentration = readiness?.concentration?.outlierDependent
    ? Math.max(
        firstNumber(readiness.concentration.top1TradeContributionPct, 0)!,
        firstNumber(readiness.concentration.top5TradeContributionPct, 0)!,
      )
    : 0;

  return clamp(Math.max(
    firstNumber(readiness?.robustnessDiagnostics?.overfitRisk, readiness?.robustnessDiagnostics?.overfitRiskPct, 0)!,
    concentration,
    readiness?.walkForward?.stable === false ? 70 : 0,
    readiness?.parameterStability?.stable === false ? 65 : 0,
  ));
}

function noveltyFor(readiness: Record<string, any> | null | undefined) {
  const sampleSize = firstNumber(readiness?.calibration?.sampleSize, readiness?.similarSampleSize, 0)!;
  return clamp(100 - Math.min(100, sampleSize * 4));
}

function durationBars(start: unknown, end: unknown) {
  const startMs = Date.parse(String(start ?? ""));
  const endMs = Date.parse(String(end ?? ""));
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs < startMs) return undefined;
  return Math.max(1, Math.round((endMs - startMs) / 86_400_000));
}

function objectOrEmpty(value: unknown) {
  return value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, any>
    : {};
}

function firstNumber(...values: unknown[]) {
  for (const value of values) {
    if (value === null || value === undefined || value === "") continue;
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }
  return undefined;
}

function number(value: unknown) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function clamp(value: number, min = 0, max = 100) {
  /* c8 ignore next 1 */
  if (!Number.isFinite(value)) return min;
  return Math.min(max, Math.max(min, value));
}

function round(value: number) {
  return Math.round(Math.max(0, value) * 100) / 100;
}

