};

export function applyStockAgencyDiagnostics(input: StockAgencyDiagnosticsInput): StockAgencyApplicationResult {
  const signals = input.signals.filter((signal) => symbolOf(signal));
  const memory = createInMemoryAgencyMemory();
  const baseTimestamp = resolveBaseTimestamp(input.summary, signals);
  const latestTradeBySymbol = latestTradesBySymbol(input.trades ?? []);

  const enrichedSignals = signals.map((signal, index) => {
    const symbol = symbolOf(signal);
    const policy = {
      minimumConfidence: 0.52,
      maximumSize: maxSizeFor(signal, input.summary),
      humanApprovalRequired: requiresHumanApproval(signal, input.summary),
    };
    const pipeline = createAgencyPipeline({
      memory,
      policy,
      clock: () => new Date(baseTimestamp),
      idGenerator: () => traceIdFor(input.market, symbol, index),
      calibration: { minimumSamples: 2 },
      selfDiagnosis: { minimumTraceCount: 2 },
    });
    const trace = pipeline.runAgencyCycle(
      cycleInputForSignal({
        market: input.market,
        signal,
        summary: input.summary,
        trade: latestTradeBySymbol.get(symbol),
      }),
    );
    const audit = auditForTrace(symbol, trace);

    return {
      ...signal,
      agencyTrace: trace,
      agency: audit,
    };
  });
  const traces = memory.list();
  const state = evaluateAgencyState(traces, {
    calibration: { minimumSamples: 2 },
    selfDiagnosis: { minimumTraceCount: 2 },
  });

  return {
    signals: enrichedSignals,
    agencyDiagnostics: {
      summary: summaryFor(
        traces,
        state.selfDiagnosis.recommendation,
        enrichedSignals.map((signal) => signal.agency as StockAgencySignalAudit),
      ),
      state,
      traces,
      signalAudits: enrichedSignals.map((signal) => signal.agency as StockAgencySignalAudit),
    },
  };
}

function cycleInputForSignal(input: {
  market: string;
  signal: StockAgencySignal;
  summary?: StockAgencySummary;
  trade?: StockAgencyTrade;
}): AgencyCycleInput {
  const symbol = symbolOf(input.signal);
  const confidence = confidenceFor(input.signal, input.summary);
  const action = actionFor(input.signal);
  const outcome = outcomeFor(input.trade);

  return {
    perception: {
      market: input.market,
      symbol,
      price: numberOrNull(input.signal.price),
      setupQuality: numeric(input.signal.setupQuality),
      riskPressure: numeric(input.signal.riskPressure),
      opportunityScore: numeric(input.signal.opportunityDiscovery?.candidateScore),
    },
    intelligence: {
      signalAction: input.signal.signalAction ?? "Hold",
      allocationAction: input.signal.allocationAction ?? input.signal.signalAction ?? "Hold",
      expectedMove: numeric(input.signal.expectedMove),
      trendQuality: numeric(input.signal.trendQuality),
      timingQuality: numeric(input.signal.timingQuality),
      lifecycle: input.signal.opportunityDiscovery?.lifecycle ?? "Untracked",
    },
    decision: decisionFor(input.signal, confidence, symbol),
    sizing: {
      size: numeric(input.signal.suggestedExposure),
      unit: "exposure_pct",
      rationale: sizingRationaleFor(input.signal),
    },
    action,
    outcome,
    blockReasons: blockReasonsFor(input.signal, input.summary),
  };
}

function decisionFor(signal: StockAgencySignal, confidence: number, symbol: string): AgencyDecision {
  const rawConfidence = rawConfidenceFor(signal);
  const calibratedConfidence = calibratedConfidenceFor(signal, undefined);
  return {
    decisionId: `${symbol}:${signal.signalAction ?? "Hold"}`,
    kind: decisionKindFor(signal),
    confidence,
    rationale: signal.explanation ?? signal.rejectionReason ?? "Signal decision translated into an agency trace.",
    expectedOutcome: expectedOutcomeFor(signal),
    metadata: {
      symbol,
      signalAction: signal.signalAction ?? "Hold",
      allocationAction: signal.allocationAction ?? signal.signalAction ?? "Hold",
      sizingMode: signal.sizingMode ?? "none",
      rawConfidence,
      calibratedConfidence,
      trustworthiness: finiteNumber(signal.trustworthiness) ?? calibratedConfidence,
      calibrationWarnings: signal.calibrationWarnings ?? [],
      ...(signal.judgement ? { judgement: signal.judgement } : {}),
      ...(signal.trustGovernor ? { trustGovernor: signal.trustGovernor } : {}),
      ...(signal.belief ? { belief: signal.belief } : {}),
      ...(signal.survivalMemory ? { survivalMemory: signal.survivalMemory } : {}),
    },
  };
}

function actionFor(signal: StockAgencySignal): AgencyAction | undefined {
  const action = signal.signalAction ?? "Hold";
  const size = numeric(signal.suggestedExposure);

  if (action === "Buy" && size > 0) {
    return {
      kind: "request_exposure",
      payload: { symbol: symbolOf(signal), exposurePct: size },
    };
  }

  if (action === "Sell") {
    return {
      kind: "reduce_exposure",
      payload: { symbol: symbolOf(signal) },
    };
  }

  return undefined;
}

function outcomeFor(trade?: StockAgencyTrade): OutcomeInput {
  if (trade === undefined || !Number.isFinite(Number(trade.returnPct))) {
    return { success: null, outcomeLabel: "unknown" };
  }

  const returnPct = Number(trade.returnPct);
  return {
    success: returnPct > 0 ? true : returnPct < 0 ? false : null,
    reward: returnPct > 0 ? round(returnPct) : undefined,
    loss: returnPct < 0 ? round(Math.abs(returnPct)) : undefined,
    durationMs: durationMs(trade.entryDate, trade.exitDate),
  };
}

function blockReasonsFor(signal: StockAgencySignal, summary?: StockAgencySummary) {
  const reasons: string[] = [];
  const riskPressure = numeric(signal.riskPressure);

  if (signal.allocationAction === "Blocked" || signal.signalStatus === "blocked") {
    reasons.push("strategy_readiness_blocked");
  }

  if (riskPressure >= 78) {
    reasons.push("risk_pressure_high");
  }

  if (signal.signalAction === "Buy" && numeric(signal.suggestedExposure) <= 0) {
    reasons.push("missing_positive_size");
  }

  if (
    signal.belief &&
    signal.belief.verdict !== "justified" &&
    (signal.allocationAction === "Blocked" || signal.signalStatus === "blocked" || signal.allocationAction === "Watch")
  ) {
    reasons.push(`belief_${String(signal.belief.verdict).replace(/[^a-z0-9]+/gi, "_").toLowerCase()}`);
  }

  if (signal.judgement?.status === "blocked" || signal.judgement?.status === "review_required") {
    reasons.push(`judgement_${signal.judgement.status}`);
  }

  if (isParticipationAction(signal) && signal.survivalMemory?.recommendation === "wait") {
    reasons.push("survival_memory_wait");
  }

  if (signal.trustGovernor && !signal.trustGovernor.allowsNewExposure && isParticipationAction(signal)) {
    reasons.push(`trust_${signal.trustGovernor.primaryBlocker ?? signal.trustGovernor.participationMode}`);
  }

  if (summary?.promotionBlocked === true || summary?.strategyReadiness?.blocked === true) {
    reasons.push("system_readiness_blocked");
  }

  return reasons;
}

function auditForTrace(symbol: string, trace: AgencyTrace): StockAgencySignalAudit {
  const trustAdjustment = reducedSizeOutcomeTrustAdjustment(trace);
  const trustAdjustmentReason = trustAdjustment > 0
    ? "Clean reduced-size outcome evidence improves Agency trust without restoring normal sizing."
    : undefined;
  const adjustedTrust = round(clamp(trace.selfDiagnosis.trust + trustAdjustment, 0, 1));
  const reasons = unique([
    ...trace.selfDiagnosis.reasons,
    ...(trustAdjustmentReason ? [trustAdjustmentReason] : []),
  ]);

  return {
    traceId: trace.traceId,
    symbol,
    decisionKind: trace.decision.kind,
    allowed: trace.policy.allowed,
    requiresApproval: trace.policy.requiresApproval,
    actionKind: trace.action?.kind ?? null,
    outcomeLabel: trace.outcome!.outcomeLabel,
    trust: adjustedTrust,
    rawConfidence: numeric((trace.decision.metadata as any)?.rawConfidence),
    calibratedConfidence: numeric((trace.decision.metadata as any)?.calibratedConfidence),
    trustworthiness: numeric((trace.decision.metadata as any)?.trustworthiness),
    calibrationWarnings: Array.isArray((trace.decision.metadata as any)?.calibrationWarnings)
      ? (trace.decision.metadata as any).calibrationWarnings
      : [],
    survivalRecommendation: (trace.decision.metadata as any)?.survivalMemory?.recommendation,
    survivalWarnings: Array.isArray((trace.decision.metadata as any)?.survivalMemory?.mainWarnings)
      ? (trace.decision.metadata as any).survivalMemory.mainWarnings
      : [],
    recommendation: trace.selfDiagnosis.recommendation,
    violations: trace.policy.violations,
    reasons,
    ...(trustAdjustment > 0 ? { trustAdjustment, trustAdjustmentReason } : {}),
  };
}

function summaryFor(
  traces: AgencyTrace[],
  recommendation: SelfDiagnosisRecommendation,
  audits: StockAgencySignalAudit[],
) {
  const traceCount = traces.length;
  const allowedActions = traces.filter((trace) => trace.policy.allowed).length;
  const blockedActions = traceCount - allowedActions;
  const missingOutcomes = traces.filter((trace) => trace.outcome?.success === null).length;
  const baseAverageTrust = traceCount
    ? round(traces.reduce((sum, trace) => sum + trace.selfDiagnosis.trust, 0) / traceCount)
    : 0;
  const averageTrust = audits.length
    ? round(audits.reduce((sum, audit) => sum + audit.trust, 0) / audits.length)
    : baseAverageTrust;
  const trustAdjustment = round(Math.max(0, averageTrust - baseAverageTrust));

  return {
    traceCount,
    allowedActions,
    blockedActions,
    missingOutcomes,
    averageTrust,
    ...(trustAdjustment > 0 ? {
      baseAverageTrust,
      trustAdjustment,
      trustAdjustmentReason: "Clean reduced-size outcomes are improving Agency trust while normal sizing remains gated.",
    } : {}),
    recommendation,
  };
}

function reducedSizeOutcomeTrustAdjustment(trace: AgencyTrace) {
  const metadata = trace.decision.metadata as Record<string, any>;
  const survivalMemory = metadata.survivalMemory as Record<string, any> | undefined;
  const calibratedConfidence = numeric(metadata.calibratedConfidence);
  const trustworthiness = numeric(metadata.trustworthiness);
  const survivalConfidence = numeric(survivalMemory?.survivalConfidence);
  const maxExposurePct = numeric(survivalMemory?.maxExposurePct);
  const isCleanReducedSizeTrace =
    trace.policy.allowed === true &&
    trace.policy.violations.length === 0 &&
    trace.outcome?.success === true &&
    survivalMemory?.recommendation === "act_with_reduced_size" &&
    maxExposurePct > 0 &&
    calibratedConfidence >= 60 &&
    trustworthiness >= 70 &&
    survivalConfidence >= 55;

  if (!isCleanReducedSizeTrace) return 0;

  const requestExposureCredit = trace.action?.kind === "request_exposure" ? 0.025 : 0.01;
  const survivalCredit = Math.min(0.025, Math.max(0, (survivalConfidence - 55) / 600));
  const calibrationCredit = Math.min(0.02, Math.max(0, (calibratedConfidence - 60) / 1_000));
  const trustworthinessCredit = Math.min(0.015, Math.max(0, (trustworthiness - 70) / 1_000));

  return round(Math.min(0.08, requestExposureCredit + survivalCredit + calibrationCredit + trustworthinessCredit));
}

function latestTradesBySymbol(trades: StockAgencyTrade[]) {
  const bySymbol = new Map<string, StockAgencyTrade>();

  for (const trade of trades) {
    const symbol = symbolOf(trade);
    if (!symbol) continue;

    const current = bySymbol.get(symbol);
    if (current === undefined || String(trade.exitDate ?? "") >= String(current.exitDate ?? "")) {
      bySymbol.set(symbol, trade);
    }
  }

  return bySymbol;
}

function resolveBaseTimestamp(summary: StockAgencySummary | undefined, signals: StockAgencySignal[]) {
  const candidates = [
    summary?.updatedAt,
    ...signals.map((signal) => signal.observedAt),
    ...signals.map((signal) => signal.signalDate),
    "1970-01-01T00:00:00.000Z",
  ];
  const candidate = candidates.find((value) => typeof value === "string" && !Number.isNaN(Date.parse(value)));
  return new Date(candidate as string).toISOString();
}

function requiresHumanApproval(signal: StockAgencySignal, summary?: StockAgencySummary) {
  return isParticipationAction(signal) && (
    signal.survivalMemory?.recommendation === "wait" ||
    !readinessAllowsParticipation(signal, summary) ||
    signal.judgement?.status === "review_required" ||
    trustRequiresHumanApproval(signal.trustGovernor) ||
    trustRequiresHumanApproval(summary?.trustGovernor)
  );
}

function readinessAllowsParticipation(signal: StockAgencySignal, summary?: StockAgencySummary) {
  if (summary?.productionEligible === true) {
    return true;
  }

  if (summary?.promotionBlocked === true || summary?.strategyReadiness?.blocked === true) {
    return false;
  }

  const stage = normalizeToken(
    (summary?.strategyReadiness as { stage?: string } | undefined)?.stage ??
      summary?.readinessLabel,
  );
  const trustGovernor = signal.trustGovernor ?? summary?.trustGovernor;
  const trustAllowsLimitedLive =
    trustGovernor?.allowsNewExposure === true &&
    !trustRequiresHumanApproval(trustGovernor);

  return (stage === "limited-live" || stage === "production-eligible") && trustAllowsLimitedLive;
}

function trustRequiresHumanApproval(trustGovernor?: TrustGovernorResult | null) {
  if (!trustGovernor) {
    return false;
  }

  const hardBlocker = Array.isArray(trustGovernor.blockers)
    ? trustGovernor.blockers.some((blocker) => blocker.severity === "high" || blocker.severity === "critical")
    : false;

  return hardBlocker || (trustGovernor.requiresReview === true && trustGovernor.allowsNewExposure !== true);
}

function maxSizeFor(signal: StockAgencySignal, summary?: StockAgencySummary) {
  if (isParticipationAction(signal) && signal.survivalMemory?.recommendation === "wait") {
    return 0;
  }

  if (signal.trustGovernor && !signal.trustGovernor.allowsNewExposure) {
    return 0;
  }

  if (signal.judgement?.status === "blocked" || signal.judgement?.status === "review_required") {
    return 0;
  }

  const configuredCap =
    finiteNumber(signal.trustGovernor?.maxExposure) ??
    finiteNumber(summary?.trustGovernor?.maxExposure) ??
    finiteNumber(signal.maxPositionPct) ??
    finiteNumber(summary?.maxPositionPct) ??
    finiteNumber(summary?.strategyReadiness?.maxPositionPct);
  const survivalCap = finiteNumber(signal.survivalMemory?.maxExposurePct);
  return Math.max(0, Math.min(configuredCap ?? numeric(signal.suggestedExposure), survivalCap ?? Number.POSITIVE_INFINITY));
}

function confidenceFor(signal: StockAgencySignal, summary?: StockAgencySummary) {
  return round(clamp(calibratedConfidenceFor(signal, summary) / 100, 0, 1));
}

function rawConfidenceFor(signal: StockAgencySignal, summary?: StockAgencySummary) {
  return (
    finiteNumber(signal.rawConfidence) ??
    finiteNumber(signal.signalConfidence) ??
    finiteNumber(signal.setupQuality) ??
    finiteNumber(summary?.rawConfidence) ??
    finiteNumber(summary?.promotionConfidence) ??
    finiteNumber(summary?.strategyReadiness?.rawConfidence) ??
    finiteNumber(summary?.strategyReadiness?.maxConfidence) ??
    finiteNumber(summary?.survivalScore) ??
    50
  );
}

function calibratedConfidenceFor(signal: StockAgencySignal, summary?: StockAgencySummary) {
  return Math.min(
    rawConfidenceFor(signal, summary),
    finiteNumber(signal.calibratedConfidence) ??
      finiteNumber(summary?.calibratedConfidence) ??
    finiteNumber(summary?.strategyReadiness?.calibratedConfidence) ??
    finiteNumber(summary?.strategyReadiness?.maxConfidence) ??
    rawConfidenceFor(signal, summary),
    finiteNumber(signal.trustGovernor?.confidenceCap) ?? 100,
    finiteNumber(signal.trustGovernor?.trustScore) ?? 100,
    finiteNumber(summary?.trustGovernor?.confidenceCap) ?? 100,
    finiteNumber(signal.belief?.confidence) ?? 100,
    finiteNumber(signal.belief?.trustworthiness) ?? 100,
    finiteNumber(signal.judgement?.adjustedConfidence) ?? 100,
    finiteNumber(signal.survivalMemory?.survivalConfidence) ?? 100,
  );
}

function decisionKindFor(signal: StockAgencySignal) {
  if (isParticipationAction(signal)) return "increase_participation";
  if (signal.signalAction === "Sell") return "reduce_participation";
  if (signal.allocationAction === "Blocked") return "blocked_participation";
  return "observe";
}

function expectedOutcomeFor(signal: StockAgencySignal) {
  if (isParticipationAction(signal)) return "Positive measured follow-through after sized participation.";
  if (signal.signalAction === "Sell") return "Lower exposure while risk remains elevated.";
  return "More evidence before taking a sized action.";
}

function sizingRationaleFor(signal: StockAgencySignal) {
  const reasons = Array.isArray(signal.sizingReasons) ? signal.sizingReasons.filter(Boolean) : [];
  return reasons[0] ?? "Sizing translated from the current strategy decision.";
}

function isParticipationAction(signal: StockAgencySignal) {
  return signal.signalAction === "Buy" && numeric(signal.suggestedExposure) > 0;
}

function traceIdFor(market: string, symbol: string, index: number) {
  return `agency-${cleanId(market)}-${cleanId(symbol)}-${index + 1}`;
}

function durationMs(start?: string, end?: string) {
  const startMs = Date.parse(String(start ?? ""));
  const endMs = Date.parse(String(end ?? ""));
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs < startMs) {
    return undefined;
  }

  return endMs - startMs;
}

function symbolOf(value: { symbol?: string; ticker?: string }) {
  return String(value.symbol ?? value.ticker ?? "").trim().toUpperCase();
}

function numberOrNull(value: unknown) {
  if (value === null || value === undefined) {
    return null;
  }

  const resolved = finiteNumber(value);
  return resolved === undefined ? null : resolved;
}

function numeric(value: unknown) {
  return finiteNumber(value) ?? 0;
}

function finiteNumber(value: unknown) {
  const n = Number(value);
  return Number.isFinite(n) ? n : undefined;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function cleanId(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "unknown";
}

function normalizeToken(value: unknown) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, "-");
}

function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

function round(value: number) {
  return Math.round(value * 1_000_000) / 1_000_000;
}

import {
  recognizeState,
  type RecognitionInput,
  type RecognitionResult,
  type RecognitionVerdict,
} from "../../../signal-framework/recognition/engine";

export type StockRecognitionSignal = {
  symbol?: string;
  ticker?: string;
  signalAction?: string;
  allocationAction?: string;
  signalStatus?: string;
  setupQuality?: number;
  riskPressure?: number;
  trendQuality?: number;
  timingQuality?: number;
  expectedMove?: number;
  signalConfidence?: number;
  rawConfidence?: number;
  calibratedConfidence?: number;
  diagnostic?: Record<string, unknown>;
  opportunityDiscovery?: any;
  judgement?: any;
  survivalMemory?: any;
  recovery?: any;
  recognition?: RecognitionResult;
};

export type StockRecognitionDiagnostics = {
  module: "stocks.recognition-adapter";
  primary: RecognitionResult | null;
  verdictCounts: Record<RecognitionVerdict, number>;
  signals: Array<{
    symbol: string;
    verdict: RecognitionVerdict;
    recognitionScore: number;
    recurrenceConfidence: number;
    noveltyScore: number;
    archetype: string;
    matchedSamples: number;
  }>;
};

export type StockRecognitionApplicationResult<T extends StockRecognitionSignal> = {
  signals: Array<T & { recognition: RecognitionResult }>;
  recognitionDiagnostics: StockRecognitionDiagnostics;
};

export function applyStockRecognitionDiagnostics<T extends StockRecognitionSignal>(input: {
  market: string;
  signals: T[];
  trades?: unknown[];
  summary?: Record<string, any>;
  opportunityDiscovery?: any;
}): StockRecognitionApplicationResult<T> {
  const candidates = new Map(
    array(input.opportunityDiscovery?.candidates).map((candidate: any) => [symbolOf(candidate), candidate]),
  );
  const signals = input.signals.map((signal) => {
    const recognition = recognizeState(buildStockRecognitionInput({
      signal,
      candidate: candidates.get(symbolOf(signal)),
      trades: input.trades,
      summary: input.summary,
      opportunityDiscovery: input.opportunityDiscovery,
    }));

    return {
      ...signal,
      recognition,
    };
  });

  return {
    signals,
    recognitionDiagnostics: summarizeRecognitionDiagnostics(signals),
  };
}

export function buildStockRecognitionInput(input: {
  signal: StockRecognitionSignal;
  candidate?: any;
  trades?: unknown[];
  summary?: Record<string, any>;
  opportunityDiscovery?: any;
}): RecognitionInput {
  const signal = input.signal;
  const candidate = input.candidate ?? signal.opportunityDiscovery ?? {};
  const genericDiscovery = candidate.discovery ?? signal.opportunityDiscovery?.discovery ?? input.opportunityDiscovery?.discovery ?? null;
  const judgement = signal.judgement ?? null;
  const survivalMemory = signal.survivalMemory ?? judgement?.survivalMemory ?? null;
  const rawAction = actionIntentFor(signal);
  const currentState = {
    actionIntent: rawAction,
    setupQuality: finiteNumber(signal.setupQuality),
    riskPressure: finiteNumber(signal.riskPressure),
    signalConfidence: finiteNumber(signal.calibratedConfidence ?? signal.signalConfidence ?? signal.rawConfidence),
  };
  const perception = {
    opportunityDensity: finiteNumber(input.opportunityDiscovery?.density?.density),
    opportunityQuality: finiteNumber(candidate.candidateScore ?? input.opportunityDiscovery?.density?.quality),
    readinessScore: finiteNumber(input.summary?.readinessScore),
    dataReliability: finiteNumber(input.summary?.strategyReadiness?.components?.dataReliability?.score ?? input.summary?.dataReliability?.score),
  };

  return {
    currentState,
    perception,
    discovery: genericDiscovery,
    judgement,
    survivalMemory,
    recovery: compactRecoveryContext(signal.recovery ?? input.summary?.recovery ?? null),
    outcomeSamples: tradeOutcomeSamples(input.trades, rawAction),
    archetypes: [
      ...archetypesFromCandidate(candidate, input.trades),
      ...archetypesFromJudgement({
        currentState,
        judgement,
        perception,
        summary: input.summary,
      }),
    ],
    now: "1970-01-01T00:00:00.000Z",
  };
}

function tradeOutcomeSamples(trades: unknown[] | undefined, actionIntent: string) {
  return array(trades).map((trade: any, index) => {
    const realized = finiteNumber(trade?.returnPct ?? trade?.profitPct ?? trade?.value ?? trade?.score) ?? 0;

    return {
      id: String(trade?.id ?? trade?.tradeId ?? `trade:${index + 1}`),
      state: {
        actionIntent: String(trade?.rawAction ?? trade?.action ?? (actionIntent || "Buy")),
        setupQuality: finiteNumber(trade?.setupQuality),
        riskPressure: finiteNumber(trade?.riskPressure),
        signalConfidence: finiteNumber(trade?.confidence ?? trade?.signalConfidence),
      },
      value: realized,
      success: realized > 0 ? true : realized < 0 ? false : null,
      archetype: realized > 0 ? "stable_positive_state" : realized < 0 ? "stable_negative_state" : "mixed_recurring_state",
      confidence: finiteNumber(trade?.confidence ?? trade?.signalConfidence),
    };
  });
}

function archetypesFromCandidate(candidate: any, trades: unknown[] | undefined) {
  const closed = array(trades);
  const outcomes = closed
    .map((trade: any) => finiteNumber(trade?.returnPct ?? trade?.profitPct ?? trade?.value ?? trade?.score))
    .filter((value): value is number => value != null);
  if (!outcomes.length) return [];

  const positiveOutcomes = outcomes.filter((value) => value > 0).length;
  const negativeOutcomes = outcomes.filter((value) => value < 0).length;
  const neutralOutcomes = outcomes.length - positiveOutcomes - negativeOutcomes;
  const setupQuality = finiteNumber(candidate?.candidateScore);
  if (setupQuality == null) return [];

  return [{
    id: "candidate-outcome-archetype",
    label: positiveOutcomes >= negativeOutcomes ? "stable_positive_state" : "stable_negative_state",
    state: {
      setupQuality,
    },
    confidence: Math.min(95, Math.max(50, (positiveOutcomes / Math.max(1, outcomes.length)) * 100)),
    sampleSize: outcomes.length,
    positiveOutcomes,
    negativeOutcomes,
    neutralOutcomes,
    outcomeStability: Math.max(0, (Math.max(positiveOutcomes, negativeOutcomes, neutralOutcomes) / outcomes.length) * 100),
  }];
}

function compactRecoveryContext(recovery: any) {
  if (!recovery || typeof recovery !== "object" || Array.isArray(recovery)) return null;

  const context: Record<string, string | number> = {};
  const status = stringValue(recovery.status);
  const mode = stringValue(recovery.mode);
  const recoveryScore = finiteNumber(recovery.recoveryScore);
  const trustedCapacity = finiteNumber(recovery.trustedCapacity);
  const recommendedExposureCap = finiteNumber(recovery.recommendedExposureCap);
  const confidenceCapLift = finiteNumber(recovery.confidenceCapLift);

  if (status) context.status = status;
  if (mode) context.mode = mode;
  if (recoveryScore != null) context.recoveryScore = recoveryScore;
  if (trustedCapacity != null) context.trustedCapacity = trustedCapacity;
  if (recommendedExposureCap != null) context.recommendedExposureCap = recommendedExposureCap;
  if (confidenceCapLift != null) context.confidenceCapLift = confidenceCapLift;

  return Object.keys(context).length ? context : null;
}

function archetypesFromJudgement(input: {
  currentState: Record<string, unknown>;
  judgement: any;
  perception: Record<string, unknown>;
  summary?: Record<string, any>;
}) {
  const judgement = input.judgement;
  const evidence = judgement?.evidence ?? {};
  const similarStates = Math.max(
    Math.round(finiteNumber(judgement?.similarSampleSize) ?? 0),
    Math.round(finiteNumber(evidence.similarStates) ?? 0),
  );
  const positiveOutcomes = Math.max(0, Math.round(finiteNumber(evidence.positiveOutcomes) ?? 0));
  const negativeOutcomes = Math.max(0, Math.round(finiteNumber(evidence.negativeOutcomes) ?? 0));
  const neutralOutcomes = Math.max(0, Math.round(finiteNumber(evidence.neutralOutcomes) ?? 0));
  const outcomeCount = positiveOutcomes + negativeOutcomes + neutralOutcomes;
  const reliability = finiteNumber(judgement?.reliability) ?? 0;
  const outcomeStability = finiteNumber(judgement?.outcomeStability) ?? finiteNumber(evidence.consistency) ?? 0;
  const dataReliability = finiteNumber(input.summary?.strategyReadiness?.components?.dataReliability?.score ?? input.summary?.dataReliability?.score);
  const stateFeatureCount = Object.values(input.currentState).filter((value) => value != null && value !== "").length;
  const hasStrongLinkage =
    similarStates >= 12 &&
    outcomeCount >= 5 &&
    reliability >= 70 &&
    outcomeStability >= 60 &&
    stateFeatureCount >= 3 &&
    (dataReliability == null || dataReliability >= 70);

  if (!hasStrongLinkage) return [];

  const dominantOutcomes = Math.max(positiveOutcomes, negativeOutcomes, neutralOutcomes);
  const dominantRatio = dominantOutcomes / outcomeCount;
  const label = dominantRatio >= 0.7 && positiveOutcomes === dominantOutcomes
    ? "stable_positive_state"
    : dominantRatio >= 0.7 && negativeOutcomes === dominantOutcomes
      ? "stable_negative_state"
      : "mixed_recurring_state";
  const sampleConfidence = Math.min(100, (similarStates / 16) * 100);
  const confidence = Math.min(95, Math.max(60, (
    reliability * 0.35 +
    outcomeStability * 0.35 +
    sampleConfidence * 0.2 +
    (dataReliability ?? reliability) * 0.1
  )));

  return [{
    id: "judgement-outcome-archetype",
    label,
    state: input.currentState,
    perception: input.perception,
    confidence,
    sampleSize: similarStates,
    positiveOutcomes,
    negativeOutcomes,
    neutralOutcomes,
    outcomeStability,
    metadata: {
      source: "judgement",
      reliability,
      similarStates,
    },
  }];
}

function summarizeRecognitionDiagnostics(
  signals: Array<StockRecognitionSignal & { recognition: RecognitionResult }>,
): StockRecognitionDiagnostics {
  const verdictCounts: Record<RecognitionVerdict, number> = {
    recognized: 0,
    partially_recognized: 0,
    novel: 0,
    conflicted: 0,
    insufficient_evidence: 0,
  };

  for (const signal of signals) {
    verdictCounts[signal.recognition.verdict] += 1;
  }

  const primary = [...signals].sort((left, right) =>
    right.recognition.recognitionScore - left.recognition.recognitionScore ||
    symbolOf(left).localeCompare(symbolOf(right)),
  )[0]?.recognition ?? null;

  return {
    module: "stocks.recognition-adapter",
    primary,
    verdictCounts,
    signals: signals.map((signal) => ({
      symbol: symbolOf(signal),
      verdict: signal.recognition.verdict,
      recognitionScore: signal.recognition.recognitionScore,
      recurrenceConfidence: signal.recognition.recurrenceConfidence,
      noveltyScore: signal.recognition.noveltyScore,
      archetype: signal.recognition.archetype,
      matchedSamples: signal.recognition.matchedSamples,
    })),
  };
}

function actionIntentFor(signal: StockRecognitionSignal) {
  return String(signal.diagnostic?.rawAction ?? signal.signalAction ?? signal.allocationAction ?? "Hold");
}

function symbolOf(value: any) {
  return String(value?.symbol ?? value?.ticker ?? "").trim().toUpperCase();
}

function finiteNumber(value: unknown) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : undefined;
}

function stringValue(value: unknown) {
  const text = String(value ?? "").trim();
  return text ? text : undefined;
}

function array<T = any>(value: unknown): T[] {
  return Array.isArray(value) ? value : [];
}

import {
  resolveCommitment,
  type ResolveInput,
  type ResolveOutput,
} from "../../../signal-framework/resolve/engine";
import type { DiscoveryResult } from "../../../signal-framework/discovery/engine";
import type { RecognitionResult } from "../../../signal-framework/recognition/engine";
import type {
  StockAgencyDiagnostics,
  StockAgencySignal,
  StockAgencySignalAudit,
  StockAgencySummary,
} from "./agency-diagnostics";

export type StockResolveSignal = StockAgencySignal & {
  agency?: StockAgencySignalAudit;
  recognition?: RecognitionResult;
  resolve?: ResolveOutput;
};

export type StockResolveDiagnostics = {
  module: "stocks.resolve-adapter";
  primary: ResolveOutput | null;
  decisionCounts: Record<ResolveOutput["decision"], number>;
  signals: Array<{
    symbol: string;
    decision: ResolveOutput["decision"];
    commitmentLevel: ResolveOutput["commitmentLevel"];
    resolveScore: number;
    requiredScore: number;
    humanReviewRequired: boolean;
  }>;
};

export type StockResolveApplicationResult<T extends StockResolveSignal> = {
  signals: Array<T & { resolve: ResolveOutput }>;
  resolveDiagnostics: StockResolveDiagnostics;
};

export function mapStockSignalToResolveInput(input: {
  signal: StockResolveSignal;
  summary?: StockAgencySummary & Record<string, any>;
  agencyDiagnostics?: StockAgencyDiagnostics | null;
  opportunityDensity?: number | null;
  discovery?: DiscoveryResult | null;
  recognition?: RecognitionResult | null;
}): ResolveInput {
  const signal = input.signal;
  const summary = input.summary ?? {};
  const audit = signal.agency;
  const judgement = signal.judgement;
  const trustGovernor = signal.trustGovernor ?? summary.trustGovernor;
  const survivalMemory = signal.survivalMemory ?? summary.survivalMemory;
  const strategyReadiness = summary.strategyReadiness ?? {};
  const opensNewExposure = signal.signalAction === "Buy" && numeric(signal.suggestedExposure) > 0;
  const survivalMaxExposure = opensNewExposure
    ? finiteNumber(survivalMemory?.maxExposurePct)
    : undefined;
  const trustedExposure =
    trustGovernor?.maxExposure ??
    finiteNumber(summary.trustedMaxExposurePct) ??
    finiteNumber(signal.maxPositionPct) ??
    finiteNumber((strategyReadiness as any).maxPositionPct);
  const strategyComponents = (strategyReadiness as any).components ?? {};
  const robustness = summary.robustnessDiagnostics ?? {};
  const calibration = (strategyReadiness as any).calibration ?? {};
  const agencyRecommendation =
    audit?.recommendation ??
    input.agencyDiagnostics?.summary?.recommendation ??
    "wait";
  const opportunityDensity = finiteNumber(input.opportunityDensity);
  const domainMissingEvidence: string[] = [];
  const domainUnlockConditions: string[] = [];
  const domainInvalidationConditions: string[] = [
    "Invalidate if the app-specific opportunity thesis loses its leading evidence cluster.",
  ];
  const discovery = input.discovery;
  const recognition = signal.recognition ?? input.recognition ?? summary.recognitionDiagnostics?.primary ?? null;
  const recognitionClearsDiscovery = recognitionClearsDiscoveryReview(recognition);

  if (opensNewExposure && opportunityDensity != null && opportunityDensity < 50) {
    domainMissingEvidence.push("Broader opportunity density across independent candidates");
    domainUnlockConditions.push("Increase opportunity density above the app review threshold.");
  }

  if (discovery) {
    domainMissingEvidence.push(...discovery.missingEvidence.slice(0, 3));
    domainUnlockConditions.push(...discovery.foresight.unlockConditions.slice(0, 3));
    domainInvalidationConditions.push(...discovery.invalidationConditions.slice(0, 3));

    if (discovery.confidence < 50 && !recognitionClearsDiscovery) {
      domainMissingEvidence.push("Discovery confidence above the app review threshold");
      domainUnlockConditions.push(discovery.recommendedNextStep);
    } else if (discovery.confidence < 50 && recognitionClearsDiscovery) {
      domainUnlockConditions.push("Recognition recurrence evidence clears the Discovery confidence review item.");
    }
  }

  if (audit?.requiresApproval === true) {
    domainMissingEvidence.push("Agency approval for this action");
    domainUnlockConditions.push("Clear the Agency approval requirement for this action.");
  }

  if (opensNewExposure && survivalMemory?.recommendation === "wait") {
    domainMissingEvidence.push("Survival memory clearance");
    domainUnlockConditions.push(
      survivalMemory.unlockConditions?.[0] ??
        "Wait until similar states show acceptable survival cost before opening exposure.",
    );
    domainInvalidationConditions.push(
      survivalMemory.invalidationConditions?.[0] ??
        "Invalidate if similar states repeat unacceptable adverse excursion.",
    );
  } else if (opensNewExposure && survivalMemory?.recommendation === "act_with_reduced_size") {
    domainMissingEvidence.push("Reduced-size survival review");
    domainUnlockConditions.push(
      survivalMemory.unlockConditions?.[0] ??
        "Restore normal sizing only after survival confidence improves.",
    );

    if (recognitionClearsDiscovery) {
      const archetype = recognizedArchetypeLabel(recognition);
      domainUnlockConditions.push(
        `Use reduced-size outcomes with acceptable drawdown and stress cost to prove the ${archetype} archetype is survival-safe before normal sizing.`,
      );
      domainInvalidationConditions.push(
        "Do not restore normal sizing from Recognition state recurrence alone if survival-cost outcome linkage remains missing.",
      );
    }
  }

  return {
    actionName: actionNameFor(signal),
    agencyRecommendation,
    agencyTrust: audit?.trust ?? input.agencyDiagnostics?.summary?.averageTrust,
    trustScore: trustGovernor?.trustScore,
    calibratedConfidence: finiteNumber(signal.calibratedConfidence) ??
      finiteNumber(summary.calibratedConfidence) ??
      finiteNumber((strategyReadiness as any).calibratedConfidence),
    rawConfidence: finiteNumber(signal.rawConfidence) ??
      finiteNumber(summary.rawConfidence) ??
      finiteNumber((strategyReadiness as any).rawConfidence),
    judgementReliability: judgement?.reliability,
    outcomeStability: judgement?.outcomeStability,
    overfitRisk: judgement?.overfitRisk ??
      finiteNumber(robustness.overfitRisk) ??
      finiteNumber(robustness.overfitRiskPct),
    riskScore: Math.max(
      finiteNumber(signal.riskPressure) ?? 0,
      opensNewExposure ? finiteNumber(survivalMemory?.averageSurvivalCost) ?? 0 : 0,
    ),
    dataReliability: finiteNumber(strategyComponents.dataReliability?.score) ??
      finiteNumber((summary as any).dataReliability?.score) ??
      finiteNumber((summary as any).dataQualityReport?.coveragePct),
    beliefConfidence: signal.belief?.confidence,
    beliefFragility: signal.belief?.fragility,
    sizingMode: signal.sizingMode,
    suggestedExposure: signal.suggestedExposure,
    maxTrustedExposure: survivalMaxExposure == null
      ? trustedExposure
      : Math.min(trustedExposure ?? survivalMaxExposure, survivalMaxExposure),
    blockedActions: audit?.allowed === false ? 1 : 0,
    missingOutcomes: input.agencyDiagnostics?.summary?.missingOutcomes,
    similarSamples: judgement?.similarSampleSize ?? finiteNumber(calibration.sampleSize),
    positiveOutcomes: judgement?.evidence?.positiveOutcomes,
    negativeOutcomes: judgement?.evidence?.negativeOutcomes,
    evidence: {
      humanReviewRequired: audit?.requiresApproval === true,
      missingEvidence: domainMissingEvidence,
      unlockConditions: domainUnlockConditions,
      invalidationConditions: domainInvalidationConditions,
      recognition,
      recognitionClearsDiscovery,
    },
  };
}

export function recognitionClearsDiscoveryReview(recognition?: RecognitionResult | null) {
  if (!recognition) return false;
  return recognition.verdict === "recognized" &&
    recognition.recurrenceConfidence >= 70 &&
    recognition.recognitionScore >= 65 &&
    recognition.outcomeStability >= 60 &&
    recognition.discoveryNoveltyJustified === false &&
    (recognition.matchedSamples >= 5 || recognition.archetypeConfidence >= 70);
}

function recognizedArchetypeLabel(recognition: RecognitionResult) {
  return String(recognition.archetype).replace(/_/g, " ");
}

export function applyStockResolveDiagnostics<T extends StockResolveSignal>(input: {
  market: string;
  signals: T[];
  summary?: StockAgencySummary & Record<string, any>;
  agencyDiagnostics?: StockAgencyDiagnostics | null;
  opportunityDiscovery?: any;
}): StockResolveApplicationResult<T> {
  const opportunityDensity = finiteNumber(input.opportunityDiscovery?.density?.density) ??
    finiteNumber(input.opportunityDiscovery?.density?.futureDensity) ??
    finiteNumber(input.opportunityDiscovery?.density?.confidence);
  const discovery = input.opportunityDiscovery?.discovery ?? null;
  const signals = input.signals.map((signal) => {
    const resolve = resolveCommitment(mapStockSignalToResolveInput({
      signal,
      summary: input.summary,
      agencyDiagnostics: input.agencyDiagnostics,
      opportunityDensity,
      discovery,
    }));

    return {
      ...signal,
      resolve,
    };
  });

  return {
    signals,
    resolveDiagnostics: summarizeResolveDiagnostics(signals),
  };
}

function summarizeResolveDiagnostics(signals: Array<StockResolveSignal & { resolve: ResolveOutput }>): StockResolveDiagnostics {
  const decisionCounts: Record<ResolveOutput["decision"], number> = {
    commit: 0,
    wait: 0,
    escalate: 0,
    reject: 0,
    invalidate: 0,
  };

  for (const signal of signals) {
    decisionCounts[signal.resolve.decision] += 1;
  }

  const primarySignal = [...signals].sort((left, right) =>
    priorityFor(right.resolve.decision) - priorityFor(left.resolve.decision) ||
    right.resolve.resolveScore - left.resolve.resolveScore,
  )[0];

  return {
    module: "stocks.resolve-adapter",
    primary: primarySignal?.resolve ?? null,
    decisionCounts,
    signals: signals.map((signal) => ({
      symbol: symbolOf(signal),
      decision: signal.resolve.decision,
      commitmentLevel: signal.resolve.commitmentLevel,
      resolveScore: signal.resolve.resolveScore,
      requiredScore: signal.resolve.requiredScore,
      humanReviewRequired: signal.resolve.humanReviewRequired,
    })),
  };
}

function priorityFor(decision: ResolveOutput["decision"]) {
  if (decision === "commit") return 5;
  if (decision === "escalate") return 4;
  if (decision === "wait") return 3;
  if (decision === "reject") return 2;
  return 1;
}

function actionNameFor(signal: StockResolveSignal) {
  const symbol = symbolOf(signal) || "selected instrument";
  const action = signal.signalAction ?? signal.allocationAction ?? "Review";
  return `${action} ${symbol}`;
}

function symbolOf(signal: StockResolveSignal) {
  return String(signal.symbol ?? signal.ticker ?? "").trim().toUpperCase();
}

function numeric(value: unknown) {
  return finiteNumber(value) ?? 0;
}

function finiteNumber(value: unknown) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : undefined;
}

import { clamp, mean, stdev } from "../math/statistics";

export type CalibrationInput = {
  id?: string;
  timestamp?: string;
  prediction: unknown;
  confidence: number;
  outcome?: unknown;
  metadata?: Record<string, unknown>;
};

export type ReliabilityBucket = {
  minConfidence: number;
  maxConfidence: number;
  sampleSize: number;
  averageConfidence: number;
  actualAccuracy: number;
  calibrationGap: number;
};

export type CalibrationResult = {
  rawConfidence: number;
  calibratedConfidence: number;
  historicalAccuracy: number;
  calibrationError: number;
  brierScore?: number;
  trustworthiness: number;
  sampleSize: number;
  reliabilityBuckets: ReliabilityBucket[];
  warnings: string[];
};

export type CalibrationOptions = {
  minimumSamples?: number;
  sufficientSamples?: number;
  poorCalibrationThreshold?: number;
  overconfidenceThreshold?: number;
  lowTrustworthinessThreshold?: number;
};

export type CalibrationRunInput = {
  current: CalibrationInput;
  history?: CalibrationInput[];
  options?: CalibrationOptions;
};

type EvaluatedRecord = {
  confidence: number;
  correctness: number;
  binaryOutcome?: number;
};

const DEFAULT_OPTIONS = {
  minimumSamples: 5,
  sufficientSamples: 20,
  poorCalibrationThreshold: 20,
  overconfidenceThreshold: 10,
  lowTrustworthinessThreshold: 50,
};

const POSITIVE_LABELS = new Set([
  "success",
  "succeeded",
  "true",
  "correct",
  "positive",
  "passed",
  "pass",
  "approved",
  "yes",
  "win",
  "winning",
]);

const NEGATIVE_LABELS = new Set([
  "failure",
  "failed",
  "false",
  "incorrect",
  "negative",
  "denied",
  "rejected",
  "no",
  "loss",
  "losing",
]);

const PARTIAL_LABELS = new Set(["partial", "mixed", "neutral"]);

export function calibrate(input: CalibrationRunInput): CalibrationResult {
  const options = { ...DEFAULT_OPTIONS, ...(input.options ?? {}) };
  const rawConfidence = normalizeConfidence(input.current.confidence);
  const evaluated = safeArray(input.history).flatMap(evaluateRecord);
  const sampleSize = evaluated.length;
  const historicalAccuracy = roundScore(
    sampleSize ? mean(evaluated.map((record) => record.correctness)) * 100 : 50,
  );
  const averageConfidence = roundScore(
    sampleSize ? mean(evaluated.map((record) => record.confidence)) : 50,
  );
  const calibrationError = roundSignedScore(
    averageConfidence - historicalAccuracy,
  );
  const binaryOutcomes = evaluated.filter(
    (record): record is EvaluatedRecord & { binaryOutcome: number } =>
      record.binaryOutcome === 0 || record.binaryOutcome === 1,
  );
  const brierScore = binaryOutcomes.length
    ? roundRatio(
        mean(
          binaryOutcomes.map(
            (record) => (record.confidence / 100 - record.binaryOutcome) ** 2,
          ),
        ),
      )
    : undefined;
  const reliabilityBuckets = buildReliabilityBuckets(evaluated);
  const trustworthiness = trustworthinessScore({
    evaluated,
    historicalAccuracy,
    calibrationError,
    brierScore,
    sufficientSamples: options.sufficientSamples,
  });
  const calibratedConfidence = calibratedScore({
    rawConfidence,
    historicalAccuracy,
    calibrationError,
    trustworthiness,
    sampleSize,
    minimumSamples: options.minimumSamples,
    sufficientSamples: options.sufficientSamples,
  });
  const warnings = warningsFor({
    evaluated,
    sampleSize,
    calibrationError,
    trustworthiness,
    minimumSamples: options.minimumSamples,
    poorCalibrationThreshold: options.poorCalibrationThreshold,
    overconfidenceThreshold: options.overconfidenceThreshold,
    lowTrustworthinessThreshold: options.lowTrustworthinessThreshold,
  });

  return {
    rawConfidence,
    calibratedConfidence,
    historicalAccuracy,
    calibrationError,
    ...(brierScore == null ? {} : { brierScore }),
    trustworthiness,
    sampleSize,
    reliabilityBuckets,
    warnings,
  };
}

export const calibrateConfidence = calibrate;

function evaluateRecord(record: CalibrationInput): EvaluatedRecord[] {
  const correctness = correctnessFor(record);
  if (correctness == null) return [];
  const binaryOutcome = binaryOutcomeFor(record.outcome);
  return [
    {
      confidence: normalizeConfidence(record.confidence),
      correctness,
      ...(binaryOutcome == null ? {} : { binaryOutcome }),
    },
  ];
}

function correctnessFor(record: CalibrationInput): number | null {
  const explicit = explicitCorrectness(record.outcome);
  if (explicit != null) return explicit;

  const predictionLabel = labelFor(record.prediction);
  const outcomeLabel = labelFor(record.outcome);
  if (predictionLabel && outcomeLabel) {
    if (predictionLabel === outcomeLabel) return 1;
    if (PARTIAL_LABELS.has(outcomeLabel)) return 0.5;
    return 0;
  }

  if (record.outcome !== undefined && primitive(record.prediction)) {
    return Object.is(record.prediction, record.outcome) ? 1 : 0;
  }

  return null;
}

function explicitCorrectness(outcome: unknown): number | null {
  if (typeof outcome === "boolean") return outcome ? 1 : 0;
  if (!outcome || typeof outcome !== "object") return null;
  const object = outcome as Record<string, unknown>;
  const value = object.correct ?? object.success;
  if (typeof value === "boolean") return value ? 1 : 0;
  if (typeof value === "number" && Number.isFinite(value))
    return clamp(value, 0, 1);
  return null;
}

function binaryOutcomeFor(outcome: unknown): number | null {
  if (typeof outcome === "boolean") return outcome ? 1 : 0;
  const label = labelFor(outcome);
  if (!label) return null;
  if (POSITIVE_LABELS.has(label)) return 1;
  if (NEGATIVE_LABELS.has(label)) return 0;
  return null;
}

function labelFor(value: unknown): string | null {
  if (typeof value === "string") return normalizeLabel(value);
  if (!value || typeof value !== "object") return null;
  const object = value as Record<string, unknown>;
  const candidate =
    object.label ??
    object.outcomeLabel ??
    object.expectedOutcome ??
    object.value ??
    object.kind;
  return typeof candidate === "string" ? normalizeLabel(candidate) : null;
}

function normalizeLabel(value: string) {
  const normalized = value.trim().toLowerCase();
  return normalized.length ? normalized : null;
}

function primitive(value: unknown) {
  return (
    value == null ||
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  );
}

function buildReliabilityBuckets(evaluated: EvaluatedRecord[]) {
  return Array.from({ length: 10 }, (_, index) => {
    const minConfidence = index * 10;
    const maxConfidence = index === 9 ? 100 : minConfidence + 10;
    const bucketRecords = evaluated.filter((record) =>
      index === 9
        ? record.confidence >= minConfidence && record.confidence <= maxConfidence
        : record.confidence >= minConfidence && record.confidence < maxConfidence,
    );
    const averageConfidence = roundScore(
      bucketRecords.length
        ? mean(bucketRecords.map((record) => record.confidence))
        : 0,
    );
    const actualAccuracy = roundScore(
      bucketRecords.length
        ? mean(bucketRecords.map((record) => record.correctness)) * 100
        : 0,
    );
    return {
      minConfidence,
      maxConfidence,
      sampleSize: bucketRecords.length,
      averageConfidence,
      actualAccuracy,
      calibrationGap: roundSignedScore(averageConfidence - actualAccuracy),
    };
  });
}

function trustworthinessScore(input: {
  evaluated: EvaluatedRecord[];
  historicalAccuracy: number;
  calibrationError: number;
  brierScore?: number;
  sufficientSamples: number;
}) {
  if (!input.evaluated.length) return 35;
  const sampleScore = clamp(
    (input.evaluated.length / Math.max(1, input.sufficientSamples)) * 100,
  );
  const calibrationQuality = clamp(100 - Math.abs(input.calibrationError));
  const consistency = clamp(
    100 - stdev(input.evaluated.map((record) => record.correctness)) * 100,
  );
  const confidenceStability = clamp(
    100 - stdev(input.evaluated.map((record) => record.confidence)),
  );
  const brierQuality =
    input.brierScore == null ? calibrationQuality : clamp(100 - input.brierScore * 100);

  return roundScore(
    input.historicalAccuracy * 0.28 +
      calibrationQuality * 0.24 +
      sampleScore * 0.18 +
      consistency * 0.12 +
      confidenceStability * 0.08 +
      brierQuality * 0.1,
  );
}

function calibratedScore(input: {
  rawConfidence: number;
  historicalAccuracy: number;
  calibrationError: number;
  trustworthiness: number;
  sampleSize: number;
  minimumSamples: number;
  sufficientSamples: number;
}) {
  if (input.sampleSize === 0) return roundScore(input.rawConfidence * 0.85);
  const sampleScore = clamp(
    (input.sampleSize / Math.max(1, input.sufficientSamples)) * 100,
  );
  const evidenceCap = clamp(input.historicalAccuracy + sampleScore * 0.15);
  const overconfidencePenalty = Math.max(0, input.calibrationError) * 0.65;
  const weakHistoryPenalty = Math.max(0, 60 - input.historicalAccuracy) * 0.25;
  const trustPenalty = Math.max(0, 50 - input.trustworthiness) * 0.25;
  let adjusted =
    input.rawConfidence -
    overconfidencePenalty -
    weakHistoryPenalty -
    trustPenalty;
  adjusted = Math.min(adjusted, evidenceCap);
  if (input.sampleSize < input.minimumSamples) {
    adjusted = Math.min(adjusted, input.rawConfidence * 0.85);
  }
  return roundScore(Math.min(input.rawConfidence, clamp(adjusted)));
}

function warningsFor(input: {
  evaluated: EvaluatedRecord[];
  sampleSize: number;
  calibrationError: number;
  trustworthiness: number;
  minimumSamples: number;
  poorCalibrationThreshold: number;
  overconfidenceThreshold: number;
  lowTrustworthinessThreshold: number;
}) {
  const warnings: string[] = [];
  if (input.sampleSize < input.minimumSamples)
    warnings.push("insufficient history");
  if (Math.abs(input.calibrationError) >= input.poorCalibrationThreshold)
    warnings.push("poor calibration");
  if (input.calibrationError >= input.overconfidenceThreshold)
    warnings.push("overconfidence");
  if (
    input.evaluated.length > 1 &&
    stdev(input.evaluated.map((record) => record.correctness)) >= 0.4
  )
    warnings.push("unstable outcomes");
  if (input.trustworthiness < input.lowTrustworthinessThreshold)
    warnings.push("low trustworthiness");
  return warnings;
}

function normalizeConfidence(value: number) {
  if (!Number.isFinite(value)) return 0;
  return roundScore(value <= 1 ? clamp(value * 100) : clamp(value));
}

function safeArray<T>(value: T[] | undefined) {
  return Array.isArray(value) ? value.filter((item) => item != null) : [];
}

function roundScore(value: number) {
  return Math.round(clamp(value) * 100) / 100;
}

function roundSignedScore(value: number) {
  return Math.round(value * 100) / 100;
}

function roundRatio(value: number) {
  return Math.round(Math.max(0, value) * 1_000_000) / 1_000_000;
}

export function clamp(value: number, min = 0, max = 100) {
  return Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));
}

export function numeric(value: unknown, fallback = 0) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : fallback;
}

export function mean(values: number[]) {
  const usable = values.filter(Number.isFinite);
  return usable.length ? usable.reduce((sum, value) => sum + value, 0) / usable.length : 0;
}

export function stdev(values: number[]) {
  const usable = values.filter(Number.isFinite);
  if (usable.length < 2) return 0;
  const average = mean(usable);
  return Math.sqrt(mean(usable.map((value) => (value - average) ** 2)));
}

export function percentileRank(values: number[], value: number) {
  const usable = values.filter(Number.isFinite);
  if (!usable.length) return clamp(value);
  return clamp((usable.filter((item) => item <= value).length / usable.length) * 100);
}

export function signRatio(values: number[], direction: "positive" | "negative") {
  const usable = values.filter(Number.isFinite);
  if (!usable.length) return 0;
  return usable.filter((value) => (direction === "positive" ? value >= 0 : value < 0)).length / usable.length;
}

export function immutable<T>(value: T): Readonly<T> {
  return deepFreeze(structuredClone(value));
}

function deepFreeze<T>(value: T): Readonly<T> {
  if (value && typeof value === "object") {
    Object.freeze(value);
    for (const child of Object.values(value as Record<string, unknown>)) {
      deepFreeze(child);
    }
  }
  return value as Readonly<T>;
}

