export type SizingMode = "none" | "micro" | "small" | "normal" | "large" | "maxSafe";

export type SizingDecision = "blocked" | "deferred" | "allowed";

export type SizingConstraint = {
  id: string;
  label?: string;
  type: "hard" | "soft";
  passed: boolean;
  severity?: "low" | "medium" | "high" | "critical";
  reason?: string;
};

export type SizingInput = {
  targetRef: string;
  actionRef?: string;
  decisionRef?: string;

  confidence: number;
  risk: number;
  utility?: number;

  availableCapacity?: number;
  requestedCapacity?: number;
  minCapacity?: number;
  maxCapacity?: number;

  constraints?: SizingConstraint[];
  context?: Record<string, unknown>;
};

export type SizingResult = {
  decision: SizingDecision;
  mode: SizingMode;
  size: number;
  normalizedSize: number;
  confidence: number;
  risk: number;
  reasons: string[];
  constraints: SizingConstraint[];
  audit: {
    cappedBy?: string[];
    blockedBy?: string[];
    requestedCapacity?: number;
    availableCapacity?: number;
    maxCapacity?: number;
  };
};

type NormalizedCapacity = {
  value: number | undefined;
  specified: boolean;
};
/* c8 ignore stop */

const CONSTRAINT_REDUCTION: Record<NonNullable<SizingConstraint["severity"]>, number> = {
  low: 0.9,
  medium: 0.75,
  high: 0.55,
  critical: 0.35,
};

const HARD_NON_BLOCKING_REDUCTION: Record<NonNullable<SizingConstraint["severity"]>, number> = {
  low: 0.8,
  medium: 0.6,
  high: 0,
  critical: 0,
};

export function sizeDecision(input: SizingInput): SizingResult {
  const reasons: string[] = [];
  const cappedBy: string[] = [];
  const blockedBy: string[] = [];
  const constraints = normalizeConstraints(input.constraints);
  const confidence = normalizeRatio(input.confidence, "Confidence", 0, reasons);
  const risk = normalizeRatio(input.risk, "Risk", 1, reasons);
  const utility = input.utility == null ? undefined : normalizeRatio(input.utility, "Utility", 0.5, reasons);
  const requestedCapacity = normalizeCapacity(input.requestedCapacity, "Requested capacity", reasons);
  const availableCapacity = normalizeCapacity(input.availableCapacity, "Available capacity", reasons);
  const minCapacity = normalizeCapacity(input.minCapacity, "Minimum capacity", reasons);
  const maxCapacity = normalizeCapacity(input.maxCapacity, "Maximum capacity", reasons);
  const audit = buildAudit(requestedCapacity.value, availableCapacity.value, maxCapacity.value);
  const blockingConstraints = constraints.filter(
    (constraint) =>
      constraint.type === "hard" &&
      !constraint.passed &&
      (constraint.severity === "high" || constraint.severity === "critical"),
  );

  if (blockingConstraints.length > 0) {
    for (const constraint of blockingConstraints) {
      blockedBy.push(constraint.id);
      reasons.push(`Blocked by ${constraintName(constraint)}.`);
      if (constraint.reason) reasons.push(constraint.reason);
    }

    return {
      decision: "blocked",
      mode: "none",
      size: 0,
      normalizedSize: 0,
      confidence,
      risk,
      reasons: unique(reasons),
      constraints,
      audit: {
        ...audit,
        blockedBy,
      },
    };
  }

  let normalizedSize = confidence * (1 - risk);

  if (confidence <= 0) {
    reasons.push("Confidence is zero; sizing starts at zero.");
  } else if (confidence < 0.35) {
    reasons.push(`Confidence ${formatPercent(confidence)} is low; sizing is conservative.`);
  } else if (confidence < 0.6) {
    reasons.push(`Confidence ${formatPercent(confidence)} is moderate; sizing remains limited.`);
  } else {
    reasons.push(`Confidence ${formatPercent(confidence)} supports sizing.`);
  }

  if (risk >= 1) {
    reasons.push("Risk is at maximum; sizing starts at zero.");
  } else if (risk > 0.75) {
    reasons.push(`Risk ${formatPercent(risk)} is high; sizing is reduced.`);
  } else if (risk > 0.45) {
    reasons.push(`Risk ${formatPercent(risk)} is moderate; sizing is controlled.`);
  } else {
    reasons.push(`Risk ${formatPercent(risk)} is controlled.`);
  }

  if (utility != null) {
    const utilityMultiplier = 0.8 + utility * 0.4;
    normalizedSize *= utilityMultiplier;
    if (utility < 0.4) reasons.push(`Utility ${formatPercent(utility)} reduces sizing.`);
    if (utility > 0.7) reasons.push(`Utility ${formatPercent(utility)} supports sizing.`);
  }

  const failedNonBlocking = constraints.filter((constraint) => !constraint.passed);
  for (const constraint of failedNonBlocking) {
    const severity = constraint.severity as NonNullable<SizingConstraint["severity"]>;
    const factor =
      constraint.type === "hard"
        ? HARD_NON_BLOCKING_REDUCTION[severity]
        : CONSTRAINT_REDUCTION[severity];
    normalizedSize *= factor;
    reasons.push(`${constraintName(constraint)} failed with ${severity} severity; sizing reduced.`);
    if (constraint.reason) reasons.push(constraint.reason);
  }

  if (constraints.length > 0 && failedNonBlocking.length === 0) {
    reasons.push("All sizing constraints passed.");
  }

  if (confidence >= 0.75 && risk <= 0.35 && failedNonBlocking.length === 0) {
    normalizedSize *= 1.15;
    reasons.push("Strong confidence and controlled risk support increased sizing.");
  }

  normalizedSize = clampUnit(normalizedSize);

  const basis = capacityBasis(availableCapacity, requestedCapacity, maxCapacity);
  if (basis <= 0) {
    reasons.push("Available sizing capacity is zero.");
    return finalize({
      decision: "deferred",
      size: 0,
      normalizedSize: 0,
      confidence,
      risk,
      reasons,
      constraints,
      audit,
      cappedBy,
    });
  }

  let size = normalizedSize * basis;
  size = applyCap("requestedCapacity", requestedCapacity.value, size, cappedBy, reasons);
  size = applyCap("maxCapacity", maxCapacity.value, size, cappedBy, reasons);
  size = applyCap("availableCapacity", availableCapacity.value, size, cappedBy, reasons);

  if (minCapacity.value != null && minCapacity.value > 0 && normalizedSize > 0 && size > 0 && size < minCapacity.value) {
    const upperCap = smallestDefined(requestedCapacity.value, maxCapacity.value, availableCapacity.value);
    if (minCapacity.value <= upperCap) {
      size = minCapacity.value;
      reasons.push(`Raised to minimum capacity ${formatNumber(minCapacity.value)}.`);
    } else {
      reasons.push(`Minimum capacity ${formatNumber(minCapacity.value)} could not be met within caps.`);
    }
  }

  size = Math.max(0, size);
  const finalNormalizedSize = clampUnit(size / basis);

  if (finalNormalizedSize === 0) {
    reasons.push("No capacity committed after confidence, risk, constraints, and caps.");
  }

  return finalize({
    decision: finalNormalizedSize > 0 ? "allowed" : "deferred",
    size: round(size),
    normalizedSize: finalNormalizedSize,
    confidence,
    risk,
    reasons,
    constraints,
    audit,
    cappedBy,
    });
}

function finalize(args: {
  decision: SizingDecision;
  size: number;
  normalizedSize: number;
  confidence: number;
  risk: number;
  reasons: string[];
  constraints: SizingConstraint[];
  audit: SizingResult["audit"];
  cappedBy: string[];
}): SizingResult {
  return {
    decision: args.decision,
    mode: modeFor(args.normalizedSize),
    size: round(args.size),
    normalizedSize: round(clampUnit(args.normalizedSize)),
    confidence: args.confidence,
    risk: args.risk,
    reasons: unique(args.reasons),
    constraints: args.constraints,
    audit: {
      ...args.audit,
      ...(args.cappedBy.length ? { cappedBy: unique(args.cappedBy) } : {}),
    },
  };
}

function normalizeConstraints(constraints: SizingInput["constraints"]): SizingConstraint[] {
  if (!Array.isArray(constraints)) return [];
  return constraints.map((constraint, index) => ({
    id: String(constraint.id || `constraint-${index + 1}`),
    label: constraint.label,
    type: constraint.type === "hard" ? "hard" : "soft",
    passed: Boolean(constraint.passed),
    severity: normalizeSeverity(constraint.severity),
    reason: constraint.reason,
  }));
}

function normalizeSeverity(severity: SizingConstraint["severity"]): NonNullable<SizingConstraint["severity"]> {
  return severity === "low" || severity === "medium" || severity === "high" || severity === "critical"
    ? severity
    : "medium";
}

function normalizeRatio(value: unknown, label: string, fallback: number, reasons: string[]) {
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) {
    reasons.push(`${label} was missing or invalid; using ${formatPercent(fallback)}.`);
    return fallback;
  }

  const scaled = Math.abs(numberValue) > 1 ? numberValue / 100 : numberValue;
  const clamped = clampUnit(scaled);
  if (clamped !== scaled) {
    reasons.push(`${label} was outside 0-100%; clamped to ${formatPercent(clamped)}.`);
  }

  return clamped;
}

function normalizeCapacity(value: unknown, label: string, reasons: string[]): NormalizedCapacity {
  if (value == null) return { value: undefined, specified: false };
  const numberValue = Number(value);
  if (!Number.isFinite(numberValue)) {
    reasons.push(`${label} was invalid and ignored.`);
    return { value: undefined, specified: true };
  }
  if (numberValue < 0) {
    reasons.push(`${label} was below zero; using 0.`);
    return { value: 0, specified: true };
  }
  return { value: numberValue, specified: true };
}

function buildAudit(
  requestedCapacity: number | undefined,
  availableCapacity: number | undefined,
  maxCapacity: number | undefined,
): SizingResult["audit"] {
  return {
    ...(requestedCapacity != null ? { requestedCapacity } : {}),
    ...(availableCapacity != null ? { availableCapacity } : {}),
    ...(maxCapacity != null ? { maxCapacity } : {}),
  };
}

function capacityBasis(
  availableCapacity: NormalizedCapacity,
  requestedCapacity: NormalizedCapacity,
  maxCapacity: NormalizedCapacity,
) {
  const capacities = [availableCapacity, requestedCapacity, maxCapacity]
    .filter((capacity) => capacity.specified)
    .map((capacity) => capacity.value ?? 0);
  if (capacities.length > 0) return Math.max(...capacities);
  return 1;
}

function applyCap(
  name: "requestedCapacity" | "availableCapacity" | "maxCapacity",
  cap: number | undefined,
  size: number,
  cappedBy: string[],
  reasons: string[],
) {
  if (cap == null || size <= cap) return size;
  cappedBy.push(name);
  reasons.push(`Capped by ${name} at ${formatNumber(cap)}.`);
  return cap;
}

function smallestDefined(...values: Array<number | undefined>) {
  const defined = values.filter((value): value is number => value != null);
  return defined.length ? Math.min(...defined) : Number.POSITIVE_INFINITY;
}

function constraintName(constraint: SizingConstraint) {
  return constraint.label ? `${constraint.label} (${constraint.id})` : constraint.id;
}

function modeFor(normalizedSize: number): SizingMode {
  if (normalizedSize <= 0) return "none";
  if (normalizedSize <= 0.05) return "micro";
  if (normalizedSize <= 0.15) return "small";
  if (normalizedSize <= 0.4) return "normal";
  if (normalizedSize <= 0.7) return "large";
  return "maxSafe";
}

function clampUnit(value: number) {
  /* c8 ignore next */
  if (!Number.isFinite(value)) return 0;
  return Math.min(1, Math.max(0, value));
}

function round(value: number) {
  return Number(value.toFixed(6));
}

function formatPercent(value: number) {
  return `${Math.round(value * 100)}%`;
}

function formatNumber(value: number) {
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}

/* c8 ignore next 3 */
function unique(values: string[]) {
  return Array.from(new Set(values));
}

import { clamp, mean, numeric } from "../math/statistics";

export type ViabilityVerdict = "viable" | "marginal" | "not-viable" | "blocked";

export type ViabilitySeverity = "low" | "medium" | "high" | "critical";

export type ViabilityConstraintOperator = "<" | "<=" | ">" | ">=" | "==" | "!=";

export type ViabilityConstraintInput = {
  id: string;
  label?: string;
  type?: "hard" | "soft" | string;
  dimension?: string;
  hard?: boolean;
  passed?: boolean;
  value?: number | string | boolean | null;
  limit?: number | string | boolean | null;
  min?: number;
  max?: number;
  operator?: ViabilityConstraintOperator;
  severity?: ViabilitySeverity | string;
  weight?: number;
  reason?: string;
  warning?: string;
  blocker?: boolean;
  metadata?: Record<string, unknown>;
};

export type ViabilityConstraintResult = {
  id: string;
  label: string;
  type: string;
  dimension?: string;
  hard: boolean;
  severity: ViabilitySeverity;
  passed: boolean;
  score: number;
  weight: number;
  reason: string;
  warning?: string;
  blocker: boolean;
  metadata?: Record<string, unknown>;
};

export type ViabilityInput = {
  targetRef: string;
  actionRef?: string;
  decisionRef?: string;
  expectedBenefit: number;
  expectedCost: number;
  expectedRisk: number;
  uncertainty?: number;
  confidence?: number;
  constraints?: ViabilityConstraintInput[];
  minMarginOfSafety?: number;
  thresholds?: {
    minConfidence?: number;
    maxCost?: number;
    maxRisk?: number;
    maxUncertainty?: number;
  };
  weights?: {
    benefit?: number;
    cost?: number;
    risk?: number;
    uncertainty?: number;
  };
  context?: Record<string, unknown>;
};

export type ViabilityResult = {
  targetRef: string;
  actionRef?: string;
  decisionRef?: string;
  verdict: ViabilityVerdict;
  finalVerdict: ViabilityVerdict;
  score: number;
  expectedBenefit: number;
  expectedCost: number;
  expectedRisk: number;
  uncertainty: number;
  confidence: number;
  marginOfSafety: number;
  requiredMarginOfSafety: number;
  constraints: ViabilityConstraintResult[];
  blockers: string[];
  warnings: string[];
  reasons: string[];
  audit: {
    componentScores: {
      expectedBenefit: number;
      expectedCost: number;
      expectedRisk: number;
      uncertainty: number;
      confidence: number;
      constraintScore: number;
      marginScore: number;
    };
    weights: {
      benefit: number;
      cost: number;
      risk: number;
      uncertainty: number;
    };
    thresholds: {
      minConfidence: number;
      maxCost: number;
      maxRisk: number;
      maxUncertainty: number;
      minMarginOfSafety: number;
    };
    formulas: string[];
  };
};

type NormalizedViability = {
  benefit: number;
  cost: number;
  risk: number;
  uncertainty: number;
  confidence: number;
  weights: Required<NonNullable<ViabilityInput["weights"]>>;
};

const DEFAULT_WEIGHTS: Required<NonNullable<ViabilityInput["weights"]>> = {
  benefit: 1,
  cost: 0.35,
  risk: 0.45,
  uncertainty: 0.2,
};

const DEFAULT_THRESHOLDS = {
  minConfidence: 0.35,
  maxCost: 0.85,
  maxRisk: 0.8,
  maxUncertainty: 0.7,
  minMarginOfSafety: 0.05,
};

const FAILED_CONSTRAINT_SCORE: Record<ViabilitySeverity, number> = {
  low: 72,
  medium: 52,
  high: 24,
  critical: 0,
};

export function evaluateViability(input: ViabilityInput): ViabilityResult {
  const normalized = normalizeViability(input);
  const constraints = normalizeConstraints(input.constraints);
  const constraintScore = weightedConstraintScore(constraints);
  const requiredMarginOfSafety = normalizeMargin(
    input.minMarginOfSafety,
    DEFAULT_THRESHOLDS.minMarginOfSafety,
  );
  const thresholds = {
    minConfidence: ratio(input.thresholds?.minConfidence, DEFAULT_THRESHOLDS.minConfidence),
    maxCost: ratio(input.thresholds?.maxCost, DEFAULT_THRESHOLDS.maxCost),
    maxRisk: ratio(input.thresholds?.maxRisk, DEFAULT_THRESHOLDS.maxRisk),
    maxUncertainty: ratio(input.thresholds?.maxUncertainty, DEFAULT_THRESHOLDS.maxUncertainty),
    minMarginOfSafety: requiredMarginOfSafety,
  };
  const marginOfSafety = calculateMarginOfSafety(input);
  const blockers = constraints
    .filter((constraint) => constraint.blocker)
    .map((constraint) => constraintName(constraint));
  const warnings = collectWarnings({
    normalized,
    constraints,
    thresholds,
    marginOfSafety,
    blockers,
  });
  const verdict = resolveVerdict({
    marginOfSafety,
    requiredMarginOfSafety,
    normalized,
    thresholds,
    blockers,
    warnings,
  });
  const marginScore = clamp(50 + marginOfSafety * 100);
  const rawScore = clamp(
    marginScore * 0.55 +
      constraintScore * 0.25 +
      normalized.confidence * 100 * 0.2,
  );
  const score = capScoreByVerdict(rawScore, verdict);
  const result: ViabilityResult = {
    targetRef: String(input.targetRef ?? "target"),
    actionRef: input.actionRef,
    decisionRef: input.decisionRef,
    verdict,
    finalVerdict: verdict,
    score: roundScore(score),
    expectedBenefit: roundUnit(normalized.benefit),
    expectedCost: roundUnit(normalized.cost),
    expectedRisk: roundUnit(normalized.risk),
    uncertainty: roundUnit(normalized.uncertainty),
    confidence: roundUnit(normalized.confidence),
    marginOfSafety,
    requiredMarginOfSafety: roundUnit(requiredMarginOfSafety),
    constraints,
    blockers: unique(blockers),
    warnings,
    reasons: [],
    audit: {
      componentScores: {
        expectedBenefit: roundUnit(normalized.benefit),
        expectedCost: roundUnit(normalized.cost),
        expectedRisk: roundUnit(normalized.risk),
        uncertainty: roundUnit(normalized.uncertainty),
        confidence: roundUnit(normalized.confidence),
        constraintScore: roundScore(constraintScore),
        marginScore: roundScore(marginScore),
      },
      weights: normalized.weights,
      thresholds,
      formulas: [
        "adjustedBenefit = expectedBenefit * (0.5 + confidence * 0.5)",
        "expectedDrag = expectedCost * costWeight + expectedRisk * riskWeight + uncertainty * uncertaintyWeight",
        "marginOfSafety = adjustedBenefit * benefitWeight - expectedDrag",
      ],
    },
  };

  return {
    ...result,
    reasons: unique([
      createViabilityReason(result),
      ...constraints
        .filter((constraint) => !constraint.passed)
        .map((constraint) => constraint.reason),
      ...warnings,
    ]),
  };
}

export function evaluateViabilityConstraint(
  input: ViabilityConstraintInput,
): ViabilityConstraintResult {
  const id = String(input.id || "constraint");
  const label = input.label || id;
  const hard = input.hard ?? input.type === "hard";
  const type = input.type || (hard ? "hard" : "soft");
  const severity = normalizeSeverity(input.severity);
  const evaluation = evaluateConstraintPass(input);
  const blocker =
    !evaluation.passed &&
    (input.blocker === true ||
      (hard && (severity === "high" || severity === "critical")));
  const reason =
    input.reason ??
    evaluation.reason ??
    `${label} ${evaluation.passed ? "passed" : "failed"}.`;

  return {
    id,
    label,
    type,
    dimension: input.dimension,
    hard,
    severity,
    passed: evaluation.passed,
    score: evaluation.passed ? 100 : FAILED_CONSTRAINT_SCORE[severity],
    weight: positive(input.weight, 1),
    reason,
    warning: !evaluation.passed && !blocker ? input.warning ?? reason : input.warning,
    blocker,
    metadata: input.metadata,
  };
}

export function calculateMarginOfSafety(input: ViabilityInput): number {
  const normalized = normalizeViability(input);
  const adjustedBenefit =
    normalized.benefit *
    normalized.weights.benefit *
    (0.5 + normalized.confidence * 0.5);
  const expectedDrag =
    normalized.cost * normalized.weights.cost +
    normalized.risk * normalized.weights.risk +
    normalized.uncertainty * normalized.weights.uncertainty;
  return roundMargin(clamp(adjustedBenefit - expectedDrag, -100, 100));
}

export function createViabilityReason(result: ViabilityResult): string {
  const margin = formatSignedPercent(result.marginOfSafety);
  const confidence = formatPercent(result.confidence);

  if (result.verdict === "blocked") {
    const blocker = result.blockers[0] ?? "a hard constraint";
    return `Blocked: ${blocker} prevents the action despite a ${margin} margin of safety.`;
  }

  if (result.verdict === "not-viable") {
    return `Not viable: expected benefit does not clear cost, risk, and uncertainty with enough safety margin (${margin}, confidence ${confidence}).`;
  }

  if (result.verdict === "marginal") {
    return `Marginal: the action clears the basic viability check with a thin ${margin} margin of safety at ${confidence} confidence.`;
  }

  return `Viable: expected benefit clears cost, risk, and uncertainty with a ${margin} margin of safety at ${confidence} confidence.`;
}

function normalizeViability(input: ViabilityInput): NormalizedViability {
  const uncertaintySeed =
    input.uncertainty == null && input.confidence != null
      ? 1 - ratio(input.confidence, 0.5)
      : 0.5;
  const uncertainty = ratio(input.uncertainty, uncertaintySeed);
  const confidence = ratio(input.confidence, 1 - uncertainty);

  return {
    benefit: ratio(input.expectedBenefit, 0),
    cost: ratio(input.expectedCost, 0),
    risk: ratio(input.expectedRisk, 0),
    uncertainty,
    confidence,
    weights: {
      benefit: positive(input.weights?.benefit, DEFAULT_WEIGHTS.benefit),
      cost: positive(input.weights?.cost, DEFAULT_WEIGHTS.cost),
      risk: positive(input.weights?.risk, DEFAULT_WEIGHTS.risk),
      uncertainty: positive(input.weights?.uncertainty, DEFAULT_WEIGHTS.uncertainty),
    },
  };
}

function normalizeConstraints(
  constraints: ViabilityInput["constraints"],
): ViabilityConstraintResult[] {
  if (!Array.isArray(constraints)) return [];
  return constraints.map((constraint, index) =>
    evaluateViabilityConstraint({
      ...constraint,
      id: constraint.id || `constraint-${index + 1}`,
    }),
  );
}

function evaluateConstraintPass(input: ViabilityConstraintInput): {
  passed: boolean;
  reason?: string;
} {
  if (typeof input.passed === "boolean") {
    return { passed: input.passed };
  }

  if (input.operator) {
    return evaluateOperator(input);
  }

  const value = Number(input.value);
  if (Number.isFinite(value) && (input.min != null || input.max != null)) {
    const aboveMin = input.min == null || value >= input.min;
    const belowMax = input.max == null || value <= input.max;
    return {
      passed: aboveMin && belowMax,
      reason: `Value ${formatNumber(value)} must be between ${formatBoundary(input.min, "-infinity")} and ${formatBoundary(input.max, "infinity")}.`,
    };
  }

  if (typeof input.value === "boolean") {
    return { passed: input.value };
  }

  return {
    passed: true,
    reason: "Constraint supplied without an evaluable rule; treated as informational.",
  };
}

function evaluateOperator(input: ViabilityConstraintInput): {
  passed: boolean;
  reason: string;
} {
  const left = Number(input.value);
  const right = Number(input.limit);
  const operator = input.operator as ViabilityConstraintOperator;
  const numericComparison = Number.isFinite(left) && Number.isFinite(right);

  if (numericComparison) {
    return {
      passed: compareNumbers(left, right, operator),
      reason: `Value ${formatNumber(left)} must be ${operator} ${formatNumber(right)}.`,
    };
  }

  if (operator === "==" || operator === "!=") {
    const passed =
      operator === "=="
        ? Object.is(input.value, input.limit)
        : !Object.is(input.value, input.limit);
    return {
      passed,
      reason: `Value must be ${operator} ${String(input.limit)}.`,
    };
  }

  return {
    passed: false,
    reason: "Constraint could not be evaluated from non-numeric values.",
  };
}

function compareNumbers(
  left: number,
  right: number,
  operator: ViabilityConstraintOperator,
) {
  if (operator === "<") return left < right;
  if (operator === "<=") return left <= right;
  if (operator === ">") return left > right;
  if (operator === ">=") return left >= right;
  if (operator === "==") return left === right;
  return left !== right;
}

function collectWarnings(args: {
  normalized: NormalizedViability;
  constraints: ViabilityConstraintResult[];
  thresholds: ViabilityResult["audit"]["thresholds"];
  marginOfSafety: number;
  blockers: string[];
}) {
  const warnings: string[] = [];
  if (args.normalized.confidence < args.thresholds.minConfidence) {
    warnings.push(
      `Confidence ${formatPercent(args.normalized.confidence)} is below the minimum ${formatPercent(args.thresholds.minConfidence)}.`,
    );
  }
  if (args.normalized.cost > args.thresholds.maxCost) {
    warnings.push(
      `Expected cost ${formatPercent(args.normalized.cost)} exceeds the maximum ${formatPercent(args.thresholds.maxCost)}.`,
    );
  }
  if (args.normalized.risk > args.thresholds.maxRisk) {
    warnings.push(
      `Expected risk ${formatPercent(args.normalized.risk)} exceeds the maximum ${formatPercent(args.thresholds.maxRisk)}.`,
    );
  }
  if (args.normalized.uncertainty > args.thresholds.maxUncertainty) {
    warnings.push(
      `Uncertainty ${formatPercent(args.normalized.uncertainty)} exceeds the maximum ${formatPercent(args.thresholds.maxUncertainty)}.`,
    );
  }
  if (args.marginOfSafety < args.thresholds.minMarginOfSafety) {
    warnings.push(
      `Margin of safety ${formatSignedPercent(args.marginOfSafety)} is below the required ${formatPercent(args.thresholds.minMarginOfSafety)}.`,
    );
  }

  for (const constraint of args.constraints) {
    if (constraint.warning) warnings.push(constraint.warning);
  }

  if (args.blockers.length) {
    warnings.push(`Blocked by ${args.blockers.join(", ")}.`);
  }

  return unique(warnings);
}

function resolveVerdict(args: {
  marginOfSafety: number;
  requiredMarginOfSafety: number;
  normalized: NormalizedViability;
  thresholds: ViabilityResult["audit"]["thresholds"];
  blockers: string[];
  warnings: string[];
}): ViabilityVerdict {
  if (args.blockers.length > 0) return "blocked";
  if (args.marginOfSafety < 0) return "not-viable";

  const thresholdPressure =
    args.normalized.confidence < args.thresholds.minConfidence ||
    args.normalized.cost > args.thresholds.maxCost ||
    args.normalized.risk > args.thresholds.maxRisk ||
    args.normalized.uncertainty > args.thresholds.maxUncertainty;

  if (args.marginOfSafety < args.requiredMarginOfSafety) return "marginal";
  if (thresholdPressure || args.warnings.length > 0) return "marginal";
  return "viable";
}

function weightedConstraintScore(constraints: ViabilityConstraintResult[]) {
  if (!constraints.length) return 100;
  const totalWeight = constraints.reduce((sum, constraint) => sum + constraint.weight, 0);
  if (totalWeight <= 0) return mean(constraints.map((constraint) => constraint.score));
  return constraints.reduce(
    (sum, constraint) => sum + constraint.score * constraint.weight,
    0,
  ) / totalWeight;
}

function capScoreByVerdict(score: number, verdict: ViabilityVerdict) {
  if (verdict === "blocked") return Math.min(score, 20);
  if (verdict === "not-viable") return Math.min(score, 49);
  if (verdict === "marginal") return Math.min(score, 69);
  return score;
}

function normalizeSeverity(severity: ViabilityConstraintInput["severity"]): ViabilitySeverity {
  return severity === "low" ||
    severity === "medium" ||
    severity === "high" ||
    severity === "critical"
    ? severity
    : "medium";
}

function ratio(value: unknown, fallback: number) {
  const parsed = numeric(value, fallback);
  const scaled = Math.abs(parsed) > 1 ? parsed / 100 : parsed;
  return clamp(scaled, 0, 1);
}

function positive(value: unknown, fallback: number) {
  const parsed = numeric(value, fallback);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function normalizeMargin(value: unknown, fallback: number) {
  const parsed = numeric(value, fallback);
  if (!Number.isFinite(parsed)) return fallback;
  if (Math.abs(parsed) > 1) return clamp(parsed / 100, -1, 1);
  return clamp(parsed, -1, 1);
}

function constraintName(constraint: ViabilityConstraintResult) {
  return constraint.label && constraint.label !== constraint.id
    ? `${constraint.label} (${constraint.id})`
    : constraint.id;
}

function roundUnit(value: number) {
  return Number(value.toFixed(6));
}

function roundScore(value: number) {
  return Number(value.toFixed(2));
}

function roundMargin(value: number) {
  return Number(value.toFixed(6));
}

function formatPercent(value: number) {
  return `${Math.round(value * 100)}%`;
}

function formatSignedPercent(value: number) {
  const rounded = Math.round(value * 100);
  return `${rounded >= 0 ? "+" : ""}${rounded}%`;
}

function formatNumber(value: number) {
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}

function formatBoundary(value: number | undefined, fallback: string) {
  return value == null ? fallback : formatNumber(value);
}

function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

/* c8 ignore next */
import { clamp, mean, stdev } from "../math/statistics";

export type JudgementStatus = "trusted" | "cautious" | "review_required" | "blocked";

export type JudgementOutcome = {
  id?: string;
  state?: Record<string, unknown>;
  currentState?: Record<string, unknown>;
  decision?: Record<string, unknown>;
  proposedDecision?: Record<string, unknown>;
  action?: Record<string, unknown>;
  proposedAction?: Record<string, unknown>;
  context?: Record<string, unknown>;
  outcome?: unknown;
  result?: unknown;
  value?: number;
  score?: number;
  returnPct?: number;
  confidence?: number;
  rawConfidence?: number;
  calibratedConfidence?: number;
  adjustedConfidence?: number;
  success?: boolean | null;
  weight?: number;
  timestamp?: number | string | Date;
  metadata?: Record<string, unknown>;
};

export type JudgementTrace = {
  id?: string;
  currentState?: Record<string, unknown>;
  state?: Record<string, unknown>;
  perception?: Record<string, unknown>;
  decision?: Record<string, unknown>;
  proposedDecision?: Record<string, unknown>;
  action?: Record<string, unknown>;
  proposedAction?: Record<string, unknown>;
  context?: Record<string, unknown>;
  outcome?: unknown;
  result?: unknown;
  confidence?: number;
  rawConfidence?: number;
  adjustedConfidence?: number;
  metadata?: Record<string, unknown>;
};

export type JudgementInput = {
  currentState: Record<string, unknown>;
  proposedDecision?: Record<string, unknown>;
  proposedAction?: Record<string, unknown>;
  historicalOutcomes?: JudgementOutcome[];
  traces?: JudgementTrace[];
  context?: Record<string, unknown>;
};

export type JudgementResult = {
  status: JudgementStatus;
  rawConfidence: number;
  adjustedConfidence: number;
  trust: number;
  calibration: number;
  reliability: number;
  overfitRisk: number;
  outcomeStability: number;
  similarSampleSize: number;
  expectedOutcome?: number;
  confidenceDelta: number;
  reasons: string[];
  warnings: string[];
  evidence: {
    similarStates: number;
    positiveOutcomes: number;
    negativeOutcomes: number;
    neutralOutcomes: number;
    averageOutcome?: number;
    winRate?: number;
    consistency?: number;
  };
};

type FeatureValue = number | string | boolean | string[];

type HistoricalRecord = {
  index: number;
  profile: Map<string, FeatureValue>;
  outcome?: number;
  confidence?: number;
};

type SimilarRecord = HistoricalRecord & {
  similarity: number;
};

type JudgementOptions = {
  minimumSimilarSamples: number;
  strongSampleSize: number;
  similarityThreshold: number;
};

const DEFAULT_MINIMUM_SIMILAR_SAMPLES = 5;
const DEFAULT_STRONG_SAMPLE_SIZE = 12;
const DEFAULT_SIMILARITY_THRESHOLD = 0.52;
const OUTCOME_EPSILON = 0.000001;

export function evaluateJudgement(input: JudgementInput): JudgementResult {
  const warnings: string[] = [];
  const source = input ?? ({} as JudgementInput);
  const currentState = recordOrEmpty(source.currentState, "currentState", warnings);
  const proposedDecision = optionalRecord(source.proposedDecision, "proposedDecision", warnings);
  const proposedAction = optionalRecord(source.proposedAction, "proposedAction", warnings);
  const context = optionalRecord(source.context, "context", warnings);
  const options = optionsFromContext(context);
  const rawConfidence = confidenceFrom(currentState, proposedDecision, proposedAction, context);
  const currentProfile = profileFor({
    state: currentState,
    decision: proposedDecision,
    action: proposedAction,
    context: filterContextForSimilarity(context),
  });
  const records = collectHistoricalRecords(source, warnings);
  const similar = records
    .map((record) => ({ ...record, similarity: similarityBetween(currentProfile, record.profile) }))
    .filter((record) => record.similarity >= options.similarityThreshold)
    .sort((left, right) => right.similarity - left.similarity || left.index - right.index);
  const outcomes = similar
    .map((record) => record.outcome)
    .filter((value): value is number => Number.isFinite(value));
  const similarSampleSize = outcomes.length;
  const evidence = evidenceFrom(similar.length, outcomes);
  const expectedOutcome = outcomes.length ? evidence.averageOutcome : undefined;
  const expectedScore = expectedScoreFromEvidence(evidence);
  const calibrationGap = calibrationGapFor(rawConfidence, expectedScore, similar);
  const calibration = roundScore(100 - calibrationGap * 1.15);
  const outcomeStability = stabilityFor(outcomes, evidence.consistency ?? 0);
  const overfitRisk = overfitRiskFor({
    context,
    rawConfidence,
    expectedScore,
    calibration,
    outcomeStability,
    similar,
    similarSampleSize,
    strongSampleSize: options.strongSampleSize,
  });
  const reliability = reliabilityFor({
    similarSampleSize,
    strongSampleSize: options.strongSampleSize,
    outcomeStability,
    calibration,
    consistency: evidence.consistency ?? 0,
    overfitRisk,
  });
  const trust = trustFor({
    reliability,
    calibration,
    overfitRisk,
    outcomeStability,
    outcomeDirectionScore: evidence.winRate ?? expectedScore,
  });
  const status = classifyJudgement({
    similarSampleSize,
    minimumSimilarSamples: options.minimumSimilarSamples,
    rawConfidence,
    expectedScore,
    calibration,
    reliability,
    overfitRisk,
    outcomeStability,
    positiveOutcomes: evidence.positiveOutcomes,
    negativeOutcomes: evidence.negativeOutcomes,
    winRate: evidence.winRate ?? 0,
  });
  const adjustedConfidence = adjustedConfidenceFor({
    status,
    rawConfidence,
    expectedScore,
    calibration,
    outcomeStability,
    overfitRisk,
    similarSampleSize,
    minimumSimilarSamples: options.minimumSimilarSamples,
    strongSampleSize: options.strongSampleSize,
    winRate: evidence.winRate ?? 0,
  });
  const reasons = reasonsFor({
    status,
    rawConfidence,
    adjustedConfidence,
    evidence,
    expectedScore,
    similarSampleSize,
    minimumSimilarSamples: options.minimumSimilarSamples,
    calibration,
    calibrationGap,
    reliability,
    overfitRisk,
    outcomeStability,
  });
  const judgementWarnings = warningsFor({
    warnings,
    similarSampleSize,
    minimumSimilarSamples: options.minimumSimilarSamples,
    calibration,
    overfitRisk,
    outcomeStability,
    status,
    similarStates: similar.length,
    outcomeCount: outcomes.length,
  });

  return {
    status,
    rawConfidence,
    adjustedConfidence,
    trust,
    calibration,
    reliability,
    overfitRisk,
    outcomeStability,
    similarSampleSize,
    ...(expectedOutcome == null ? {} : { expectedOutcome }),
    confidenceDelta: roundSigned(adjustedConfidence - rawConfidence),
    reasons,
    warnings: judgementWarnings,
    evidence,
  };
}

export const judge = evaluateJudgement;
export const judgeDecision = evaluateJudgement;

function collectHistoricalRecords(input: JudgementInput, warnings: string[]): HistoricalRecord[] {
  const outcomes = arrayOrEmpty(input?.historicalOutcomes, "historicalOutcomes", warnings);
  const traces = arrayOrEmpty(input?.traces, "traces", warnings);
  const outcomeRecords = outcomes.map((outcome, index) => recordFromOutcome(outcome, index));
  const traceRecords = traces.map((trace, index) => recordFromTrace(trace, outcomes.length + index));
  return [...outcomeRecords, ...traceRecords].filter((record) => record.profile.size > 0);
}

function recordFromOutcome(outcome: JudgementOutcome, index: number): HistoricalRecord {
  const metadata = optionalPlainRecord(outcome?.metadata);
  return {
    index,
    profile: profileFor({
      state: firstRecord(outcome?.state, outcome?.currentState, metadata?.state),
      decision: firstRecord(outcome?.decision, outcome?.proposedDecision, metadata?.decision),
      action: firstRecord(outcome?.action, outcome?.proposedAction, metadata?.action),
      context: firstRecord(outcome?.context, metadata?.context),
    }),
    outcome: outcomeValueFor(outcome),
    confidence: confidenceValueFor(outcome),
  };
}

function recordFromTrace(trace: JudgementTrace, index: number): HistoricalRecord {
  const metadata = optionalPlainRecord(trace?.metadata);
  return {
    index,
    profile: profileFor({
      state: firstRecord(trace?.currentState, trace?.state, trace?.perception, metadata?.state),
      decision: firstRecord(trace?.decision, trace?.proposedDecision, metadata?.decision),
      action: firstRecord(trace?.action, trace?.proposedAction, metadata?.action),
      context: firstRecord(trace?.context, metadata?.context),
    }),
    outcome: outcomeValueFor(trace),
    confidence: confidenceValueFor(trace),
  };
}

function profileFor(input: {
  state?: Record<string, unknown>;
  decision?: Record<string, unknown>;
  action?: Record<string, unknown>;
  context?: Record<string, unknown>;
}) {
  const features = new Map<string, FeatureValue>();
  flattenInto(features, "state", input.state);
  flattenInto(features, "decision", input.decision);
  flattenInto(features, "action", input.action);
  flattenInto(features, "context", input.context);
  return features;
}

function flattenInto(features: Map<string, FeatureValue>, prefix: string, value: unknown) {
  if (!value || typeof value !== "object") return;

  for (const [key, child] of Object.entries(value as Record<string, unknown>).sort(([left], [right]) => left.localeCompare(right))) {
    const path = `${prefix}.${key}`;
    if (isPlainRecord(child)) {
      flattenInto(features, path, child);
      continue;
    }

    const normalized = featureValue(child);
    if (normalized !== undefined) features.set(path, normalized);
  }
}

function featureValue(value: unknown): FeatureValue | undefined {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "boolean") return value;
  if (typeof value === "string") {
    const trimmed = value.trim().toLowerCase();
    return trimmed ? trimmed : undefined;
  }
  if (Array.isArray(value)) {
    const items = value
      .map((item) => String(item ?? "").trim().toLowerCase())
      .filter(Boolean)
      .sort();
    return items.length ? Array.from(new Set(items)) : undefined;
  }
  return undefined;
}

function similarityBetween(current: Map<string, FeatureValue>, historical: Map<string, FeatureValue>) {
  let totalWeight = 0;
  let weightedSimilarity = 0;

  for (const [key, currentValue] of current) {
    if (!historical.has(key)) continue;

    const itemSimilarity = valueSimilarity(currentValue, historical.get(key) as FeatureValue);
    const weight = featureWeight(key);
    totalWeight += weight;
    weightedSimilarity += itemSimilarity * weight;
  }

  return totalWeight > 0 ? roundRatio(weightedSimilarity / totalWeight) : 0;
}

function valueSimilarity(left: FeatureValue, right: FeatureValue) {
  if (typeof left === "number" && typeof right === "number") {
    const denominator = Math.max(1, Math.abs(left), Math.abs(right));
    return clamp(1 - Math.abs(left - right) / denominator, 0, 1);
  }

  if (Array.isArray(left) && Array.isArray(right)) {
    return jaccard(left, right);
  }

  if (typeof left === "string" && typeof right === "string") {
    if (left === right) return 1;
    return jaccard(tokens(left), tokens(right)) * 0.75;
  }

  return Object.is(left, right) ? 1 : 0;
}

function featureWeight(path: string) {
  if (path.startsWith("state.")) return 1.35;
  if (path.startsWith("decision.")) return 1.15;
  if (path.startsWith("action.")) return 1.1;
  return 0.85;
}

function jaccard(left: string[], right: string[]) {
  const leftSet = new Set(left);
  const rightSet = new Set(right);
  const union = new Set([...leftSet, ...rightSet]);
  if (!union.size) return 0;

  let overlap = 0;
  for (const item of leftSet) {
    if (rightSet.has(item)) overlap += 1;
  }

  return overlap / union.size;
}

function tokens(value: string) {
  return value.split(/[^a-z0-9]+/i).filter(Boolean);
}

function evidenceFrom(similarStates: number, outcomes: number[]): JudgementResult["evidence"] {
  const positiveOutcomes = outcomes.filter((value) => value > OUTCOME_EPSILON).length;
  const negativeOutcomes = outcomes.filter((value) => value < -OUTCOME_EPSILON).length;
  const neutralOutcomes = outcomes.length - positiveOutcomes - negativeOutcomes;
  const averageOutcome = outcomes.length ? roundSigned(mean(outcomes)) : undefined;
  const winRate = outcomes.length ? roundScore((positiveOutcomes / outcomes.length) * 100) : undefined;
  const consistency = outcomes.length
    ? roundScore((Math.max(positiveOutcomes, negativeOutcomes, neutralOutcomes) / outcomes.length) * 100)
    : undefined;

  return {
    similarStates,
    positiveOutcomes,
    negativeOutcomes,
    neutralOutcomes,
    ...(averageOutcome == null ? {} : { averageOutcome }),
    ...(winRate == null ? {} : { winRate }),
    ...(consistency == null ? {} : { consistency }),
  };
}

function expectedScoreFromEvidence(evidence: JudgementResult["evidence"]) {
  const outcomeScore = evidence.averageOutcome == null ? 50 : clamp(50 + evidence.averageOutcome / 2, 0, 100);
  const winRate = evidence.winRate ?? 50;
  return roundScore(mean([outcomeScore, winRate]));
}

function calibrationGapFor(rawConfidence: number, expectedScore: number, similar: SimilarRecord[]) {
  const currentGap = Math.abs(rawConfidence - expectedScore);
  const historicalGaps = similar
    .filter((record) => record.confidence != null && record.outcome != null)
    .map((record) => Math.abs((record.confidence as number) - clamp(50 + (record.outcome as number) / 2, 0, 100)));

  return roundScore(historicalGaps.length ? mean([currentGap, mean(historicalGaps)]) : currentGap);
}

function stabilityFor(outcomes: number[], consistency: number) {
  if (!outcomes.length) return 0;
  const dispersionSafety = clamp(100 - stdev(outcomes), 0, 100);
  return roundScore(consistency * 0.65 + dispersionSafety * 0.35);
}

function overfitRiskFor(input: {
  context: Record<string, unknown>;
  rawConfidence: number;
  expectedScore: number;
  calibration: number;
  outcomeStability: number;
  similar: SimilarRecord[];
  similarSampleSize: number;
  strongSampleSize: number;
}) {
  const sampleScore = clamp((input.similarSampleSize / input.strongSampleSize) * 100, 0, 100);
  const sampleRisk = 100 - sampleScore;
  const instabilityRisk = 100 - input.outcomeStability;
  const calibrationRisk = 100 - input.calibration;
  const highConfidenceRisk = clamp(Math.max(0, input.rawConfidence - input.expectedScore) * 1.15, 0, 100);
  const concentrationRisk = similarityConcentrationRisk(input.similar);
  const estimated = roundScore(
    sampleRisk * 0.28 +
      instabilityRisk * 0.25 +
      calibrationRisk * 0.22 +
      highConfidenceRisk * 0.15 +
      concentrationRisk * 0.1,
  );
  const explicit = explicitOverfitRisk(input.context);

  return explicit == null ? estimated : roundScore(Math.max(explicit, estimated * 0.5 + explicit * 0.5));
}

function similarityConcentrationRisk(similar: SimilarRecord[]) {
  if (similar.length < 2) return 80;
  const total = similar.reduce((sum, record) => sum + record.similarity, 0);
  if (total <= 0) return 80;
  const topShare = similar.slice(0, 3).reduce((sum, record) => sum + record.similarity, 0) / total * 100;
  return roundScore(clamp((topShare - 45) * 1.5, 0, 100));
}

function reliabilityFor(input: {
  similarSampleSize: number;
  strongSampleSize: number;
  outcomeStability: number;
  calibration: number;
  consistency: number;
  overfitRisk: number;
}) {
  const sampleScore = clamp((input.similarSampleSize / input.strongSampleSize) * 100, 0, 100);
  return roundScore(
    sampleScore * 0.28 +
      input.outcomeStability * 0.28 +
      input.calibration * 0.22 +
      input.consistency * 0.12 +
      (100 - input.overfitRisk) * 0.1,
  );
}

function trustFor(input: {
  reliability: number;
  calibration: number;
  overfitRisk: number;
  outcomeStability: number;
  outcomeDirectionScore: number;
}) {
  return roundScore(
    input.reliability * 0.34 +
      input.calibration * 0.24 +
      (100 - input.overfitRisk) * 0.22 +
      input.outcomeStability * 0.12 +
      input.outcomeDirectionScore * 0.08,
  );
}

function classifyJudgement(input: {
  similarSampleSize: number;
  minimumSimilarSamples: number;
  rawConfidence: number;
  expectedScore: number;
  calibration: number;
  reliability: number;
  overfitRisk: number;
  outcomeStability: number;
  positiveOutcomes: number;
  negativeOutcomes: number;
  winRate: number;
}): JudgementStatus {
  if (input.similarSampleSize < input.minimumSimilarSamples) return "review_required";
  if (
    input.overfitRisk >= 85 ||
    (input.overfitRisk >= 75 && input.reliability < 45) ||
    (input.rawConfidence >= 75 && input.expectedScore <= 35 && input.calibration < 50)
  ) {
    return "blocked";
  }
  if (
    input.overfitRisk >= 65 ||
    input.calibration < 45 ||
    input.outcomeStability < 45 ||
    input.reliability < 45
  ) {
    return "review_required";
  }
  if (
    input.reliability >= 70 &&
    input.calibration >= 65 &&
    input.outcomeStability >= 65 &&
    input.overfitRisk < 40 &&
    input.winRate >= 70 &&
    input.positiveOutcomes >= input.negativeOutcomes
  ) {
    return "trusted";
  }
  return "cautious";
}

function adjustedConfidenceFor(input: {
  status: JudgementStatus;
  rawConfidence: number;
  expectedScore: number;
  calibration: number;
  outcomeStability: number;
  overfitRisk: number;
  similarSampleSize: number;
  minimumSimilarSamples: number;
  strongSampleSize: number;
  winRate: number;
}) {
  if (input.status === "blocked") return 0;

  const evidencePenalty = Math.max(0, input.rawConfidence - input.expectedScore) * 0.55;
  let adjusted = input.rawConfidence - evidencePenalty;

  if (input.outcomeStability < 60) {
    adjusted *= clamp(0.55 + input.outcomeStability / 200, 0.45, 0.85);
  }
  if (input.calibration < 60) {
    adjusted -= (60 - input.calibration) * 0.35;
  }
  if (input.overfitRisk > 45) {
    adjusted *= clamp(1 - (input.overfitRisk - 45) / 160, 0.35, 1);
  }
  if (input.similarSampleSize < input.minimumSimilarSamples) {
    adjusted = Math.min(adjusted, input.rawConfidence * 0.7);
  }
  if (input.status === "review_required") {
    adjusted = Math.min(adjusted, input.rawConfidence * 0.65);
  }

  const strongPositiveEvidence =
    input.similarSampleSize >= input.strongSampleSize &&
    input.winRate >= 70 &&
    input.outcomeStability >= 75 &&
    input.calibration >= 70 &&
    input.overfitRisk <= 35 &&
    input.expectedScore > input.rawConfidence + 5;

  if (strongPositiveEvidence) {
    return roundScore(Math.min(100, input.rawConfidence + Math.min(8, (input.expectedScore - input.rawConfidence) * 0.25)));
  }

  return roundScore(Math.min(input.rawConfidence, Math.max(0, adjusted)));
}

function reasonsFor(input: {
  status: JudgementStatus;
  rawConfidence: number;
  adjustedConfidence: number;
  evidence: JudgementResult["evidence"];
  expectedScore: number;
  similarSampleSize: number;
  minimumSimilarSamples: number;
  calibration: number;
  calibrationGap: number;
  reliability: number;
  overfitRisk: number;
  outcomeStability: number;
}) {
  const reasons = [
    `Judgement compared the current state with ${input.evidence.similarStates} similar historical state(s).`,
  ];

  if (input.similarSampleSize < input.minimumSimilarSamples) {
    reasons.push(`Only ${input.similarSampleSize} similar outcome(s) were usable; minimum is ${input.minimumSimilarSamples}.`);
  } else {
    reasons.push(`Similar outcomes show ${input.evidence.positiveOutcomes} positive, ${input.evidence.negativeOutcomes} negative, and ${input.evidence.neutralOutcomes} neutral result(s).`);
  }

  if ((input.evidence.winRate ?? 0) >= 70 && input.outcomeStability >= 70) {
    reasons.push("Similar historical outcomes were consistently positive.");
  }
  if (input.rawConfidence >= 75 && input.outcomeStability < 60) {
    reasons.push("Raw confidence is high, but similar outcomes are not stable enough to trust fully.");
  }
  if (input.calibration < 60) {
    reasons.push(`Calibration is weak: expected evidence score ${formatPercent(input.expectedScore)} differs from raw confidence by ${formatPercent(input.calibrationGap)}.`);
  }
  if (input.overfitRisk >= 65) {
    reasons.push(`Overfit risk is elevated at ${formatPercent(input.overfitRisk)}.`);
  }

  reasons.push(`Reliability is ${formatPercent(input.reliability)} and outcome stability is ${formatPercent(input.outcomeStability)}.`);
  reasons.push(`Status is ${input.status}; confidence adjusted from ${formatPercent(input.rawConfidence)} to ${formatPercent(input.adjustedConfidence)}.`);

  return unique(reasons);
}

function warningsFor(input: {
  warnings: string[];
  similarSampleSize: number;
  minimumSimilarSamples: number;
  calibration: number;
  overfitRisk: number;
  outcomeStability: number;
  status: JudgementStatus;
  similarStates: number;
  outcomeCount: number;
}) {
  const warnings = [...input.warnings];

  if (input.similarSampleSize < input.minimumSimilarSamples) {
    warnings.push("low sample size");
  }
  if (input.similarStates > input.outcomeCount) {
    warnings.push("some similar states have no usable outcome");
  }
  if (input.outcomeStability < 55 && input.outcomeCount > 0) {
    warnings.push("unstable outcomes");
  }
  if (input.calibration < 55 && input.outcomeCount > 0) {
    warnings.push("poor calibration");
  }
  if (input.overfitRisk >= 65) {
    warnings.push("high overfit risk");
  }
  if (input.status === "blocked") {
    warnings.push("judgement blocked action");
  }
  if (input.status === "review_required") {
    warnings.push("human review required");
  }

  return unique(warnings);
}

function outcomeValueFor(value: unknown): number | undefined {
  const object = isPlainRecord(value) ? value : {};
  const direct = firstNumber(
    object.outcome,
    object.result,
    object.value,
    object.score,
    object.returnPct,
    object.metadata && isPlainRecord(object.metadata) ? object.metadata.outcome : undefined,
  );

  if (direct != null) return normalizeOutcomeNumber(direct);

  const nested = firstRecord(object.outcome, object.result);
  const nestedNumber = firstNumber(nested?.value, nested?.score, nested?.returnPct, nested?.reward);
  if (nestedNumber != null) return normalizeOutcomeNumber(nestedNumber);

  const success = firstBoolean(object.success, nested?.success, nested?.correct, nested?.passed);
  if (success != null) return success ? 100 : -100;

  const label = String(nested?.label ?? nested?.outcomeLabel ?? object.outcome ?? object.result ?? "").toLowerCase();
  if (["success", "win", "positive", "passed", "correct", "true"].includes(label)) return 100;
  if (["failure", "loss", "negative", "failed", "incorrect", "false"].includes(label)) return -100;
  if (["neutral", "mixed", "partial", "flat"].includes(label)) return 0;

  return undefined;
}

function confidenceValueFor(value: unknown) {
  const object = isPlainRecord(value) ? value : {};
  return firstScore(object.confidence, object.rawConfidence, object.calibratedConfidence, object.adjustedConfidence);
}

function confidenceFrom(
  currentState: Record<string, unknown>,
  proposedDecision: Record<string, unknown>,
  proposedAction: Record<string, unknown>,
  context: Record<string, unknown>,
) {
  return firstScore(
    proposedDecision.rawConfidence,
    proposedDecision.confidence,
    context.rawConfidence,
    context.confidence,
    currentState.rawConfidence,
    currentState.confidence,
    proposedAction.rawConfidence,
    proposedAction.confidence,
    proposedDecision.calibratedConfidence,
    context.calibratedConfidence,
    50,
  ) as number;
}

function optionsFromContext(context: Record<string, unknown>): JudgementOptions {
  return {
    minimumSimilarSamples: Math.max(
      1,
      Math.round(firstNumber(context.minimumSimilarSamples, context.minSimilarSamples, context.minimumSamples) ?? DEFAULT_MINIMUM_SIMILAR_SAMPLES),
    ),
    strongSampleSize: Math.max(
      1,
      Math.round(firstNumber(context.strongSampleSize, context.sufficientSamples) ?? DEFAULT_STRONG_SAMPLE_SIZE),
    ),
    similarityThreshold: clamp(
      firstNumber(context.similarityThreshold, context.judgementSimilarityThreshold) ?? DEFAULT_SIMILARITY_THRESHOLD,
      0,
      1,
    ),
  };
}

function explicitOverfitRisk(context: Record<string, unknown>) {
  const direct = firstScore(
    context.overfitRisk,
    context.overfitRiskPct,
    context.robustnessOverfitRisk,
    nestedScore(context.robustnessDiagnostics, "overfitRisk"),
    nestedScore(context.robustnessDiagnostics, "overfitRiskPct"),
    nestedScore(context.robustness, "overfitRisk"),
  );
  return direct == null ? undefined : direct;
}

function nestedScore(value: unknown, key: string) {
  return isPlainRecord(value) ? value[key] : undefined;
}

function filterContextForSimilarity(context: Record<string, unknown>) {
  const ignored = new Set([
    "minimumSimilarSamples",
    "minSimilarSamples",
    "minimumSamples",
    "strongSampleSize",
    "sufficientSamples",
    "similarityThreshold",
    "judgementSimilarityThreshold",
    "overfitRisk",
    "overfitRiskPct",
    "robustnessOverfitRisk",
    "robustnessDiagnostics",
    "robustness",
  ]);
  return Object.fromEntries(Object.entries(context).filter(([key]) => !ignored.has(key)));
}

function arrayOrEmpty<T>(value: T[] | undefined, field: string, warnings: string[]) {
  if (value == null) return [];
  if (Array.isArray(value)) return value;
  warnings.push(`${field} was not an array`);
  return [];
}

function recordOrEmpty(value: unknown, field: string, warnings: string[]) {
  if (isPlainRecord(value)) return value;
  warnings.push(`${field} was not an object`);
  return {};
}

function optionalRecord(value: unknown, field: string, warnings: string[]) {
  if (value == null) return {};
  if (isPlainRecord(value)) return value;
  warnings.push(`${field} was not an object`);
  return {};
}

function optionalPlainRecord(value: unknown) {
  return isPlainRecord(value) ? value : {};
}

function firstRecord(...values: unknown[]) {
  return values.find(isPlainRecord) as Record<string, unknown> | undefined;
}

function firstScore(...values: unknown[]) {
  for (const value of values) {
    const numberValue = firstNumber(value);
    if (numberValue != null) return normalizeScore(numberValue);
  }
  return undefined;
}

function firstNumber(...values: unknown[]) {
  for (const value of values) {
    const numberValue = Number(value);
    if (Number.isFinite(numberValue)) return numberValue;
  }
  return undefined;
}

function firstBoolean(...values: unknown[]) {
  for (const value of values) {
    if (typeof value === "boolean") return value;
  }
  return undefined;
}

function normalizeScore(value: number) {
  const scaled = value >= 0 && value <= 1 ? value * 100 : value;
  return roundScore(scaled);
}

function normalizeOutcomeNumber(value: number) {
  const scaled = value > -1 && value < 1 && value !== 0 ? value * 100 : value;
  return roundSigned(clamp(scaled, -100, 100));
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value) && !(value instanceof Date);
}

function roundScore(value: number) {
  return Math.round(clamp(value, 0, 100) * 100) / 100;
}

function roundSigned(value: number) {
  return Math.round(clamp(value, -100, 100) * 100) / 100;
}

function roundRatio(value: number) {
  return Math.round(clamp(value, 0, 1) * 1_000_000) / 1_000_000;
}

function formatPercent(value: number) {
  return `${Math.round(value)}%`;
}

/* c8 ignore next 3 */
function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

/* c8 ignore next */
export type SurvivalOutcomeClass =
  | "comfortable_survival"
  | "stressed_survival"
  | "barely_survived"
  | "failed_survival";

export type SurvivalAction = "buy" | "sell" | "hold" | "watch" | "reduce" | "exit";

export type SurvivalMemoryStatus = "empty" | "clear" | "watch" | "scarred" | "near_ruin";

export type SurvivalMemoryRecommendation = "act" | "act_with_reduced_size" | "wait";

export interface SurvivalMemoryRecord {
  id: string;
  timestamp: string;
  asset?: string;
  venue?: string;
  regime?: string;
  stateFingerprint: string;
  action: SurvivalAction;
  maxExposure: number;
  realizedReturn: number;
  maxDrawdown: number;
  maxAdverseExcursion: number;
  recoveryTimeBars?: number;
  volatilityExpansion: number;
  tailRisk: number;
  liquidityStress: number;
  structuralDanger: number;
  novelty: number;
  opportunityDensity: number;
  outcomeClass: SurvivalOutcomeClass;
  survivalCost: number;
  scarWeight: number;
  notes?: string[];
}

export type SurvivalCostInput = {
  maxDrawdown?: number;
  maxAdverseExcursion?: number;
  recoveryTimeBars?: number;
  volatilityExpansion?: number;
  tailRisk?: number;
  liquidityStress?: number;
  structuralDanger?: number;
  novelty?: number;
};

export type SurvivalClassificationInput = SurvivalCostInput & {
  realizedReturn?: number;
  survivalCost?: number;
};

export type SurvivalMemoryRecordInput = SurvivalClassificationInput & {
  id: string;
  timestamp?: string;
  asset?: string;
  venue?: string;
  regime?: string;
  stateFingerprint?: string;
  state?: Record<string, unknown>;
  action?: SurvivalAction | string;
  maxExposure?: number;
  opportunityDensity?: number;
  notes?: string[];
};

export type SurvivalMemoryAnalysisInput = {
  records?: SurvivalMemoryRecord[];
  currentState?: Record<string, unknown>;
  stateFingerprint?: string;
  similarityThreshold?: number;
};

export type SurvivalMemoryAnalysis = {
  status: SurvivalMemoryStatus;
  recommendation: SurvivalMemoryRecommendation;
  recordCount: number;
  matchedCount: number;
  scarCount: number;
  nearRuinCount: number;
  scarRate?: number;
  nearRuinRate?: number;
  severeNearRuinRate?: number;
  averageSurvivalCost: number;
  recoveryBurden: number;
  survivalConfidence: number;
  currentStateSimilarity: number;
  nearRuinSimilarity?: number;
  exposureMultiplier: number;
  confidencePenalty: number;
  mainWarnings: string[];
  reasons: string[];
  missingEvidence: string[];
  unlockConditions: string[];
  invalidationConditions: string[];
  fragileMatches: Array<{
    id: string;
    similarity: number;
    outcomeClass: SurvivalOutcomeClass;
    survivalCost: number;
    realizedReturn: number;
  }>;
};

const SURVIVAL_COST_WEIGHTS = {
  maxDrawdown: 0.18,
  maxAdverseExcursion: 0.18,
  recoveryTime: 0.12,
  volatilityExpansion: 0.12,
  tailRisk: 0.14,
  liquidityStress: 0.12,
  structuralDanger: 0.09,
  novelty: 0.05,
};

export function calculateSurvivalCost(input: SurvivalCostInput): number {
  const recoveryTime = scoreRecovery(input.recoveryTimeBars);
  return roundScore(
    normalizeMagnitude(input.maxDrawdown) * SURVIVAL_COST_WEIGHTS.maxDrawdown +
      normalizeMagnitude(input.maxAdverseExcursion) * SURVIVAL_COST_WEIGHTS.maxAdverseExcursion +
      recoveryTime * SURVIVAL_COST_WEIGHTS.recoveryTime +
      normalizeScore(input.volatilityExpansion) * SURVIVAL_COST_WEIGHTS.volatilityExpansion +
      normalizeScore(input.tailRisk) * SURVIVAL_COST_WEIGHTS.tailRisk +
      normalizeScore(input.liquidityStress) * SURVIVAL_COST_WEIGHTS.liquidityStress +
      normalizeScore(input.structuralDanger) * SURVIVAL_COST_WEIGHTS.structuralDanger +
      normalizeScore(input.novelty) * SURVIVAL_COST_WEIGHTS.novelty,
  );
}

export function classifySurvivalOutcome(input: SurvivalClassificationInput): SurvivalOutcomeClass {
  const survivalCost = normalizeScore(input.survivalCost ?? calculateSurvivalCost(input));
  const realizedReturn = number(input.realizedReturn);
  const maxDrawdown = normalizeMagnitude(input.maxDrawdown);
  const adverse = normalizeMagnitude(input.maxAdverseExcursion);
  const recovery = scoreRecovery(input.recoveryTimeBars);
  const tailRisk = normalizeScore(input.tailRisk);
  const liquidityStress = normalizeScore(input.liquidityStress);
  const structuralDanger = normalizeScore(input.structuralDanger);
  const stressPeak = Math.max(tailRisk, liquidityStress, structuralDanger);

  if (realizedReturn < 0 || maxDrawdown >= 45 || adverse >= 45 || survivalCost >= 85) {
    return "failed_survival";
  }

  if (
    survivalCost >= 58 ||
    maxDrawdown >= 25 ||
    adverse >= 30 ||
    recovery >= 75 ||
    stressPeak >= 70
  ) {
    return "barely_survived";
  }

  if (
    survivalCost >= 25 ||
    maxDrawdown >= 8 ||
    adverse >= 10 ||
    recovery >= 25 ||
    stressPeak >= 35 ||
    normalizeScore(input.volatilityExpansion) >= 35
  ) {
    return "stressed_survival";
  }

  return "comfortable_survival";
}

export function scarWeightForOutcome(outcomeClass: SurvivalOutcomeClass, survivalCost: number): number {
  const costRatio = normalizeScore(survivalCost) / 100;

  if (outcomeClass === "failed_survival") return 1;
  if (outcomeClass === "barely_survived") return roundRatio(Math.max(0.55, costRatio * 0.9));
  if (outcomeClass === "stressed_survival") return roundRatio(Math.max(0.18, costRatio * 0.55));
  return 0;
}

export function buildSurvivalMemoryRecord(input: SurvivalMemoryRecordInput): SurvivalMemoryRecord {
  const survivalCost = calculateSurvivalCost(input);
  const outcomeClass = classifySurvivalOutcome({ ...input, survivalCost });
  const scarWeight = scarWeightForOutcome(outcomeClass, survivalCost);
  const action = normalizeAction(input.action);
  const notes = unique([
    ...(input.notes ?? []),
    ...notesForRecord({
      ...input,
      action,
      survivalCost,
      outcomeClass,
      scarWeight,
    }),
  ]);

  return {
    id: input.id,
    timestamp: timestampFor(input.timestamp),
    ...(input.asset ? { asset: input.asset } : {}),
    ...(input.venue ? { venue: input.venue } : {}),
    ...(input.regime ? { regime: input.regime } : {}),
    stateFingerprint: input.stateFingerprint ?? fingerprintSurvivalState(input.state ?? {}),
    action,
    maxExposure: roundScore(normalizeScore(input.maxExposure)),
    realizedReturn: roundScore(number(input.realizedReturn)),
    maxDrawdown: roundScore(normalizeMagnitude(input.maxDrawdown)),
    maxAdverseExcursion: roundScore(normalizeMagnitude(input.maxAdverseExcursion)),
    ...(input.recoveryTimeBars == null ? {} : { recoveryTimeBars: Math.max(0, Math.round(number(input.recoveryTimeBars))) }),
    volatilityExpansion: roundScore(normalizeScore(input.volatilityExpansion)),
    tailRisk: roundScore(normalizeScore(input.tailRisk)),
    liquidityStress: roundScore(normalizeScore(input.liquidityStress)),
    structuralDanger: roundScore(normalizeScore(input.structuralDanger)),
    novelty: roundScore(normalizeScore(input.novelty)),
    opportunityDensity: roundScore(normalizeScore(input.opportunityDensity)),
    outcomeClass,
    survivalCost,
    scarWeight,
    ...(notes.length ? { notes } : {}),
  };
}

export function evaluateSurvivalMemory(input: SurvivalMemoryAnalysisInput = {}): SurvivalMemoryAnalysis {
  const records = Array.isArray(input.records) ? input.records : [];
  const currentFingerprint = input.stateFingerprint ?? fingerprintSurvivalState(input.currentState ?? {});
  const threshold = clampRatio(input.similarityThreshold ?? 0.35);
  const matched = records
    .map((record) => ({
      record,
      similarity: similarityForFingerprint(currentFingerprint, record.stateFingerprint),
    }))
    .filter((match) => match.similarity >= threshold)
    .sort((left, right) => right.similarity - left.similarity || right.record.id.localeCompare(left.record.id));
  const effectiveMatches = matched.length ? matched : records.map((record) => ({ record, similarity: 0 }));
  const fragileMatches = effectiveMatches.filter((match) => isSurvivalScar(match.record));
  const nearRuinMatches = effectiveMatches.filter((match) => isNearRuin(match.record));
  const severeNearRuinMatches = nearRuinMatches.filter((match) => isSevereNearRuin(match.record));
  const scarRate = ratio(fragileMatches.length, effectiveMatches.length);
  const nearRuinRate = ratio(nearRuinMatches.length, effectiveMatches.length);
  const severeNearRuinRate = ratio(severeNearRuinMatches.length, effectiveMatches.length);
  const averageSurvivalCost = average(effectiveMatches.map((match) => match.record.survivalCost));
  const recoveryBurden = average(effectiveMatches.map((match) => scoreRecovery(match.record.recoveryTimeBars)));
  const currentStateSimilarity = fragileMatches.length
    ? Math.max(...fragileMatches.map((match) => match.similarity))
    : 0;
  const nearRuinSimilarity = nearRuinMatches.length
    ? Math.max(...nearRuinMatches.map((match) => match.similarity))
    : 0;
  const exposureMultiplier = exposureMultiplierFor({
    averageSurvivalCost,
    scarRate,
    nearRuinCount: nearRuinMatches.length,
    nearRuinRate,
    severeNearRuinCount: severeNearRuinMatches.length,
    severeNearRuinRate,
    currentStateSimilarity,
    nearRuinSimilarity,
  });
  const controlledRecovery = averageSurvivalCost < 35 && recoveryBurden < 20;
  const confidencePenalty = roundScore(
    (1 - exposureMultiplier) * 35 +
      averageSurvivalCost * 0.1 +
      nearRuinRate * 8 * (controlledRecovery ? 0.4 : 1) +
      severeNearRuinRate * 20 * (controlledRecovery ? 0.35 : 1),
  );
  const survivalConfidence = survivalConfidenceFor({
    averageSurvivalCost,
    recoveryBurden,
    scarRate,
    nearRuinRate,
    severeNearRuinRate,
    currentStateSimilarity,
  });
  const status = statusFor({
    recordCount: records.length,
    averageSurvivalCost,
    scarRate,
    nearRuinRate,
    severeNearRuinCount: severeNearRuinMatches.length,
    severeNearRuinRate,
    nearRuinSimilarity,
  });
  const recommendation = recommendationFor(status, exposureMultiplier);
  const mainWarnings = warningsFor({
    fragileMatches: fragileMatches.map((match) => match.record),
    nearRuinCount: nearRuinMatches.length,
    averageSurvivalCost,
    recoveryBurden,
    currentStateSimilarity,
  });
  const reasons = reasonsFor({
    status,
    recommendation,
    exposureMultiplier,
    survivalConfidence,
    mainWarnings,
  });

  return {
    status,
    recommendation,
    recordCount: records.length,
    matchedCount: effectiveMatches.length,
    scarCount: fragileMatches.length,
    nearRuinCount: nearRuinMatches.length,
    scarRate: roundScore(scarRate * 100),
    nearRuinRate: roundScore(nearRuinRate * 100),
    severeNearRuinRate: roundScore(severeNearRuinRate * 100),
    averageSurvivalCost: roundScore(averageSurvivalCost),
    recoveryBurden: roundScore(recoveryBurden),
    survivalConfidence,
    currentStateSimilarity: roundScore(currentStateSimilarity * 100),
    nearRuinSimilarity: roundScore(nearRuinSimilarity * 100),
    exposureMultiplier,
    confidencePenalty,
    mainWarnings,
    reasons,
    missingEvidence: missingEvidenceFor(recommendation),
    unlockConditions: unlockConditionsFor(recommendation),
    invalidationConditions: invalidationConditionsFor(recommendation),
    fragileMatches: fragileMatches.slice(0, 5).map((match) => ({
      id: match.record.id,
      similarity: roundScore(match.similarity * 100),
      outcomeClass: match.record.outcomeClass,
      survivalCost: match.record.survivalCost,
      realizedReturn: match.record.realizedReturn,
    })),
  };
}

export function fingerprintSurvivalState(state: Record<string, unknown>): string {
  const tokens = Object.entries(state)
    .flatMap(([key, value]) => fingerprintTokens(key, value))
    .filter(Boolean)
    .sort();

  return tokens.length ? tokens.join("|") : "survival:unknown";
}

function fingerprintTokens(key: string, value: unknown): string[] {
  const normalizedKey = normalizeToken(key);

  if (!normalizedKey) return [];
  if (typeof value === "number" && Number.isFinite(value)) {
    return [`${normalizedKey}:${scoreBucket(value)}`];
  }
  if (typeof value === "boolean") {
    return [`${normalizedKey}:${value ? "true" : "false"}`];
  }
  if (typeof value === "string") {
    const normalized = normalizeToken(value);
    return normalized ? [`${normalizedKey}:${normalized}`] : [];
  }
  if (Array.isArray(value)) {
    return value.flatMap((item) => fingerprintTokens(normalizedKey, item));
  }
  return [];
}

function similarityForFingerprint(current: string, historical: string): number {
  if (current === historical) return 1;
  const currentTokens = new Set(current.split("|").filter(Boolean));
  const historicalTokens = new Set(historical.split("|").filter(Boolean));
  const union = new Set([...currentTokens, ...historicalTokens]);
  if (!union.size) return 0;
  let intersection = 0;

  for (const token of currentTokens) {
    if (historicalTokens.has(token)) intersection += 1;
  }

  return intersection / union.size;
}

function notesForRecord(input: SurvivalMemoryRecordInput & {
  action: SurvivalAction;
  survivalCost: number;
  outcomeClass: SurvivalOutcomeClass;
  scarWeight: number;
}) {
  const notes: string[] = [];
  const profitable = number(input.realizedReturn) > 0;

  if (profitable && input.outcomeClass === "barely_survived") {
    notes.push("Profitable outcome carried unacceptable survival cost.");
  }
  if (input.outcomeClass === "failed_survival") {
    notes.push("Outcome failed the survival boundary.");
  }
  if (normalizeMagnitude(input.maxDrawdown) >= 25) {
    notes.push("Large drawdown created survival scar tissue.");
  }
  if (normalizeScore(input.tailRisk) >= 70 || normalizeScore(input.liquidityStress) >= 70) {
    notes.push("Tail or liquidity pressure made the signal structurally fragile.");
  }

  return notes;
}

function isSurvivalScar(record: SurvivalMemoryRecord) {
  return record.scarWeight >= 0.18 || record.outcomeClass !== "comfortable_survival";
}

function isNearRuin(record: SurvivalMemoryRecord) {
  return record.outcomeClass === "failed_survival" ||
    record.outcomeClass === "barely_survived" && (
      record.survivalCost >= 65 ||
      record.maxDrawdown >= 30 ||
      record.maxAdverseExcursion >= 35 ||
      record.tailRisk >= 80 ||
      record.liquidityStress >= 80
    );
}

function isSevereNearRuin(record: SurvivalMemoryRecord) {
  return record.outcomeClass === "failed_survival" ||
    record.survivalCost >= 75 ||
    record.maxDrawdown >= 45 ||
    record.maxAdverseExcursion >= 45 ||
    record.tailRisk >= 90 ||
    record.liquidityStress >= 90;
}

function exposureMultiplierFor(input: {
  averageSurvivalCost: number;
  scarRate: number;
  nearRuinCount: number;
  nearRuinRate: number;
  severeNearRuinCount: number;
  severeNearRuinRate: number;
  currentStateSimilarity: number;
  nearRuinSimilarity: number;
}) {
  const severeCluster =
    input.severeNearRuinRate >= 0.2 &&
    (input.nearRuinSimilarity >= 0.5 || input.averageSurvivalCost >= 55);

  if (input.severeNearRuinCount >= 2 && severeCluster && input.averageSurvivalCost >= 65) return 0;
  if (severeCluster && input.averageSurvivalCost >= 35) return 0.2;
  if (input.averageSurvivalCost >= 70) return 0.25;
  if (input.averageSurvivalCost >= 55 || input.nearRuinRate >= 0.5 && input.averageSurvivalCost >= 35) return 0.4;
  if (input.averageSurvivalCost >= 35 || input.scarRate >= 0.5 || input.nearRuinRate >= 0.2) return 0.65;
  return 1;
}

function statusFor(input: {
  recordCount: number;
  averageSurvivalCost: number;
  scarRate: number;
  nearRuinRate: number;
  severeNearRuinCount: number;
  severeNearRuinRate: number;
  nearRuinSimilarity: number;
}): SurvivalMemoryStatus {
  if (input.recordCount === 0) return "empty";
  const severeCluster =
    input.severeNearRuinRate >= 0.2 &&
    (input.nearRuinSimilarity >= 0.45 || input.averageSurvivalCost >= 55);

  if (
    input.averageSurvivalCost >= 70 ||
    severeCluster && input.averageSurvivalCost >= 35
  ) {
    return "near_ruin";
  }
  if (input.averageSurvivalCost >= 55 || input.nearRuinRate >= 0.5 || input.scarRate >= 0.65) return "scarred";
  if (input.scarRate > 0 || input.nearRuinRate > 0 || input.averageSurvivalCost >= 30) return "watch";
  return "clear";
}

function survivalConfidenceFor(input: {
  averageSurvivalCost: number;
  recoveryBurden: number;
  scarRate: number;
  nearRuinRate: number;
  severeNearRuinRate: number;
  currentStateSimilarity: number;
}) {
  const controlledRecovery = input.averageSurvivalCost < 35 && input.recoveryBurden < 20;
  const stabilizingRecoveryCredit = controlledRecovery
    ? clampScore((35 - input.averageSurvivalCost) * 0.6 + (20 - input.recoveryBurden) * 0.25)
    : 0;
  const nearRuinPenaltyScale = controlledRecovery ? 0.25 : input.averageSurvivalCost < 45 ? 0.65 : 1;
  const severePenaltyScale = controlledRecovery ? 0.25 : input.averageSurvivalCost < 45 ? 0.6 : 1;
  const similarityPenaltyScale = controlledRecovery ? 0.6 : 1;

  return roundScore(clampScore(
    100 -
      input.averageSurvivalCost * 0.65 -
      input.scarRate * 12 -
      input.nearRuinRate * 18 * nearRuinPenaltyScale -
      input.severeNearRuinRate * 35 * severePenaltyScale -
      input.currentStateSimilarity * 6 * similarityPenaltyScale -
      input.recoveryBurden * 0.08 +
      stabilizingRecoveryCredit,
  ));
}

function recommendationFor(status: SurvivalMemoryStatus, exposureMultiplier: number): SurvivalMemoryRecommendation {
  if (status === "near_ruin" || exposureMultiplier === 0) return "wait";
  if (status === "scarred" || status === "watch" || exposureMultiplier < 0.85) return "act_with_reduced_size";
  return "act";
}

function warningsFor(input: {
  fragileMatches: SurvivalMemoryRecord[];
  nearRuinCount: number;
  averageSurvivalCost: number;
  recoveryBurden: number;
  currentStateSimilarity: number;
}) {
  const warnings: string[] = [];

  if (input.nearRuinCount > 0) {
    warnings.push("Similar states include near-ruin survival patterns.");
  }
  if (input.fragileMatches.some((record) => record.realizedReturn > 0 && record.outcomeClass === "barely_survived")) {
    warnings.push("Similar states were profitable but carried unacceptable drawdown or stress.");
  }
  if (input.averageSurvivalCost >= 35) {
    warnings.push(`Average survival cost is elevated at ${Math.round(input.averageSurvivalCost)}/100.`);
  }
  if (input.recoveryBurden >= 50) {
    warnings.push("Recovery burden is high after adverse moves.");
  }
  if (input.currentStateSimilarity >= 0.5) {
    warnings.push("Current state resembles fragile historical states.");
  }

  return unique(warnings);
}

function reasonsFor(input: {
  status: SurvivalMemoryStatus;
  recommendation: SurvivalMemoryRecommendation;
  exposureMultiplier: number;
  survivalConfidence: number;
  mainWarnings: string[];
}) {
  if (input.status === "empty") {
    return ["No survival memory records are available yet."];
  }

  const reasons = [
    `Survival memory status is ${input.status.replace(/_/g, " ")} with confidence ${Math.round(input.survivalConfidence)}/100.`,
  ];

  if (input.recommendation === "wait") {
    reasons.push("Wait because similar states had unacceptable survival cost.");
  } else if (input.recommendation === "act_with_reduced_size") {
    reasons.push(`Cap exposure to ${Math.round(input.exposureMultiplier * 100)}% of the normal limit before opportunity sizing expands it.`);
  }

  return unique([...reasons, ...input.mainWarnings]);
}

function missingEvidenceFor(recommendation: SurvivalMemoryRecommendation) {
  if (recommendation === "wait") return ["Survival memory clearance"];
  if (recommendation === "act_with_reduced_size") return ["Reduced-size survival review"];
  return [];
}

function unlockConditionsFor(recommendation: SurvivalMemoryRecommendation) {
  if (recommendation === "wait") {
    return ["Wait until similar states show survival cost below 35/100 and no near-ruin match."];
  }
  if (recommendation === "act_with_reduced_size") {
    return ["Raise survival confidence above 70/100 before normal sizing is restored."];
  }
  return [];
}

function invalidationConditionsFor(recommendation: SurvivalMemoryRecommendation) {
  const base = ["Invalidate if similar states repeat max adverse excursion above the survival boundary."];
  if (recommendation === "act") return [];
  if (recommendation === "wait") return [...base, "Invalidate if liquidity or tail pressure remains elevated in the current state."];
  return base;
}

function normalizeAction(action: unknown): SurvivalAction {
  const normalized = normalizeToken(action);
  if (normalized === "sell") return "sell";
  if (normalized === "hold") return "hold";
  if (normalized === "watch") return "watch";
  if (normalized === "reduce") return "reduce";
  if (normalized === "exit") return "exit";
  return "buy";
}

function scoreRecovery(recoveryTimeBars: unknown) {
  return clampScore(number(recoveryTimeBars) / 60 * 100);
}

function scoreBucket(value: number) {
  const score = normalizeScore(value);
  if (score < 20) return "very-low";
  if (score < 40) return "low";
  if (score < 60) return "mid";
  if (score < 80) return "high";
  return "extreme";
}

function normalizeMagnitude(value: unknown) {
  return normalizeScore(Math.abs(number(value)));
}

function normalizeScore(value: unknown) {
  const parsed = number(value);
  return clampScore(Math.abs(parsed) < 1 && parsed !== 0 ? parsed * 100 : parsed);
}

function clampScore(value: number) {
  /* c8 ignore next 1 */
  if (!Number.isFinite(value)) return 0;
  return Math.min(100, Math.max(0, value));
}

function clampRatio(value: number) {
  if (!Number.isFinite(value)) return 0;
  return Math.min(1, Math.max(0, value));
}

function average(values: number[]) {
  const clean = values.filter(Number.isFinite);
  if (!clean.length) return 0;
  return clean.reduce((sum, value) => sum + value, 0) / clean.length;
}

function ratio(count: number, total: number) {
  if (!Number.isFinite(count) || !Number.isFinite(total) || total <= 0) return 0;
  return clampRatio(count / total);
}

function number(value: unknown) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function normalizeToken(value: unknown) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, "-")
    .replace(/[^a-z0-9.-]+/g, "");
}

function timestampFor(value: unknown) {
  const parsed = Date.parse(String(value ?? ""));
  if (Number.isFinite(parsed)) return new Date(parsed).toISOString();
  return "1970-01-01T00:00:00.000Z";
}

function unique(values: string[]) {
  return Array.from(new Set(values.filter(Boolean)));
}

function roundScore(value: number) {
  return Math.round(clampScore(value) * 100) / 100;
}

/* c8 ignore next */
function roundRatio(value: number) {
  return Math.round(clampRatio(value) * 100) / 100;
}

/* c8 ignore next */
import { clamp, mean, stdev } from "../math/statistics";

export type RobustnessRegime =
  | "trending"
  | "volatile"
  | "low-volatility"
  | "panic"
  | "recovery"
  | "sideways"
  | "liquidity-compression"
  | "expansion";

export type RobustnessObservation = {
  id?: string;
  index?: number;
  timestamp?: number;
  actual: number;
  predicted?: number;
  confidence?: number;
  regime?: RobustnessRegime | string;
  features?: Record<string, number>;
  participated?: boolean;
};

export type RobustnessParameterVariant = {
  id: string;
  score: number;
  baselineScore?: number;
  benchmarkScore?: number;
  passed?: boolean;
};

export type RobustnessAdversarialScenario = {
  id: string;
  score: number;
  baselineScore?: number;
  severity?: number;
};

export type RobustnessEnsembleVote = {
  id: string;
  direction: number;
  confidence: number;
  weight?: number;
};

export type LeakageCheck = {
  id: string;
  trainEndIndex: number;
  validationStartIndex: number;
  normalizedWithFuture?: boolean;
  featureTimestampIndex?: number;
  labelTimestampIndex?: number;
};

export type SignalRobustnessInput = {
  observations: RobustnessObservation[];
  trainWindowSize?: number;
  validationWindowSize?: number;
  stepSize?: number;
  minimumSamples?: number;
  parameterVariants?: RobustnessParameterVariant[];
  adversarialScenarios?: RobustnessAdversarialScenario[];
  ensembleVotes?: RobustnessEnsembleVote[];
  leakageChecks?: LeakageCheck[];
  expectedForwardSamples?: number;
  observedForwardSamples?: number;
  dataQualityScore?: number;
  seed?: number;
};

export type SignalRobustnessResult = {
  robustnessScore: number;
  overfitRisk: number;
  generalizationConfidence: number;
  structuralReliability: number;
  adaptabilityScore: number;
  uncertaintyLevel: number;
  deploymentReadiness: number;
  safetyGate: "allow" | "reduce" | "block";
  reasons: string[];
  walkForward: {
    stabilityScore: number;
    consistencyScore: number;
    degradationPct: number;
    windows: Array<{
      trainStartIndex: number;
      trainEndIndex: number;
      validationStartIndex: number;
      validationEndIndex: number;
      trainMean: number;
      validationMean: number;
      degradationPct: number;
    }>;
  };
  regimes: {
    regimeRobustnessScore: number;
    regimeDependencyScore: number;
    adaptabilityScore: number;
    regimes: Array<{ regime: string; samples: number; meanOutcome: number; score: number }>;
  };
  calibration: {
    calibrationScore: number;
    calibrationError: number;
    confidenceDecay: number;
    reliabilityCurve: Array<{ bucket: string; samples: number; predictedConfidence: number; realizedRate: number }>;
  };
  parameterSensitivity: {
    stabilityScore: number;
    fragilityScore: number;
    gradient: number;
    heatmap: Array<{ id: string; score: number; degradationPct: number; passed: boolean }>;
  };
  adversarial: {
    robustnessScore: number;
    executionRealismScore: number;
    scenarios: Array<{ id: string; degradationPct: number; resilienceScore: number }>;
  };
  participation: {
    participationScore: number;
    opportunityDensity: number;
    executableConviction: number;
  };
  ensemble: {
    consensusScore: number;
    dominancePenalty: number;
    disagreementScore: number;
  };
  leakage: {
    passed: boolean;
    violations: string[];
  };
  featureTrust: {
    trustScore: number;
    entropy: number;
    features: Array<{ key: string; trust: number; weight: number }>;
  };
  realityGap: {
    realismScore: number;
    expectedDegradationPct: number;
  };
  statisticalIntegrity: {
    score: number;
    bootstrapStability: number;
    monteCarloStability: number;
    minimumSampleScore: number;
    dataQualityScore: number;
  };
};

type NormalizedObservation = Required<Pick<RobustnessObservation, "actual" | "confidence" | "participated">> &
  RobustnessObservation & {
    order: number;
    regime: string;
  };

export class SignalRobustnessEngine {
  evaluate(input: SignalRobustnessInput): SignalRobustnessResult {
    const observations = normalizeObservations(input.observations);
    const minimumSamples = Math.max(1, Math.round(input.minimumSamples ?? 30));
    const walkForward = evaluateRollingWalkForward(
      observations,
      Math.max(2, Math.round(input.trainWindowSize ?? Math.max(12, minimumSamples))),
      Math.max(1, Math.round(input.validationWindowSize ?? Math.max(4, Math.floor(minimumSamples / 3)))),
      Math.max(1, Math.round(input.stepSize ?? Math.max(1, Math.floor((input.validationWindowSize ?? minimumSamples / 3) / 2)))),
    );
    const regimes = evaluateRegimes(observations);
    const calibration = evaluateCalibration(observations, minimumSamples);
    const parameterSensitivity = evaluateParameterSensitivity(input.parameterVariants ?? []);
    const adversarial = evaluateAdversarial(input.adversarialScenarios ?? []);
    const participation = evaluateParticipation(observations);
    const ensemble = evaluateEnsemble(input.ensembleVotes ?? []);
    const leakage = evaluateLeakage(input.leakageChecks ?? []);
    const featureTrust = evaluateFeatureTrust(observations);
    const statisticalIntegrity = evaluateStatisticalIntegrity(
      observations,
      minimumSamples,
      clamp(input.dataQualityScore ?? 100),
      input.seed ?? 17,
    );
    const realityGap = estimateRealityGap(walkForward.degradationPct, adversarial.executionRealismScore, statisticalIntegrity.score);
    const observedForwardSamples = Math.max(0, Math.round(input.observedForwardSamples ?? observations.length));
    const expectedForwardSamples = Math.max(1, Math.round(input.expectedForwardSamples ?? minimumSamples));
    const forwardSampleScore = clamp((observedForwardSamples / expectedForwardSamples) * 100);
    const componentScores = [
      walkForward.stabilityScore,
      regimes.regimeRobustnessScore,
      calibration.calibrationScore,
      parameterSensitivity.stabilityScore,
      adversarial.robustnessScore,
      participation.participationScore,
      ensemble.consensusScore,
      leakage.passed ? 100 : 0,
      featureTrust.trustScore,
      realityGap.realismScore,
      statisticalIntegrity.score,
      forwardSampleScore,
    ];
    const robustnessScore = Math.round(weightedMean(componentScores, [1.1, 1, 1, 1.05, 0.9, 0.9, 0.85, 1.25, 0.8, 1, 1.1, 0.7]));
    const uncertaintyLevel = Math.round(clamp(100 - weightedMean(componentScores, [1, 1, 1.2, 1, 0.8, 0.8, 0.7, 1.4, 0.7, 1, 1.1, 0.7])));
    const structuralReliability = Math.round(mean([
      parameterSensitivity.stabilityScore,
      leakage.passed ? 100 : 0,
      statisticalIntegrity.score,
      realityGap.realismScore,
    ]));
    const adaptabilityScore = Math.round(mean([
      regimes.adaptabilityScore,
      walkForward.consistencyScore,
      adversarial.robustnessScore,
      featureTrust.trustScore,
    ]));
    const generalizationConfidence = Math.round(mean([
      robustnessScore,
      calibration.calibrationScore,
      structuralReliability,
      forwardSampleScore,
    ]));
    const overfitRisk = Math.round(clamp(
      100 - robustnessScore +
        parameterSensitivity.fragilityScore * 0.16 +
        regimes.regimeDependencyScore * 0.12 +
        Math.max(0, 55 - calibration.calibrationScore) * 0.2 +
        (leakage.passed ? 0 : 28),
    ));
    const deploymentReadiness = Math.round(clamp(mean([
      robustnessScore,
      generalizationConfidence,
      structuralReliability,
      adaptabilityScore,
      100 - overfitRisk,
      participation.participationScore,
    ])));
    const safetyGate = leakage.passed === false || overfitRisk > 60
      ? "block"
      : overfitRisk > 30 || deploymentReadiness < 62 || participation.participationScore < 35
        ? "reduce"
        : "allow";
    const reasons = buildReasons({
      overfitRisk,
      safetyGate,
      walkForward: walkForward.stabilityScore,
      regimes: regimes.regimeRobustnessScore,
      calibration: calibration.calibrationScore,
      parameters: parameterSensitivity.stabilityScore,
      adversarial: adversarial.robustnessScore,
      participation: participation.participationScore,
      leakage,
      statisticalIntegrity: statisticalIntegrity.score,
    });

    return {
      robustnessScore,
      overfitRisk,
      generalizationConfidence,
      structuralReliability,
      adaptabilityScore,
      uncertaintyLevel,
      deploymentReadiness,
      safetyGate,
      reasons,
      walkForward,
      regimes,
      calibration,
      parameterSensitivity,
      adversarial,
      participation,
      ensemble,
      leakage,
      featureTrust,
      realityGap,
      statisticalIntegrity,
    };
  }
}

function normalizeObservations(observations: RobustnessObservation[]): NormalizedObservation[] {
  return observations
    .map((item, order) => {
      const actual = finite(item.actual);
      return {
        ...item,
        order,
        actual,
        confidence: clamp(item.confidence ?? 50),
        participated: item.participated !== false,
        regime: String(item.regime ?? inferRegime(actual, item.features)),
      };
    })
    .filter((item) => Number.isFinite(item.actual))
    .sort((a, b) => (a.timestamp ?? a.index ?? a.order) - (b.timestamp ?? b.index ?? b.order));
}

function evaluateRollingWalkForward(
  observations: NormalizedObservation[],
  trainWindowSize: number,
  validationWindowSize: number,
  stepSize: number,
) {
  const windows: SignalRobustnessResult["walkForward"]["windows"] = [];
  for (
    let start = 0;
    start + trainWindowSize + validationWindowSize <= observations.length;
    start += stepSize
  ) {
    const train = observations.slice(start, start + trainWindowSize).map((item) => item.actual);
    const validation = observations
      .slice(start + trainWindowSize, start + trainWindowSize + validationWindowSize)
      .map((item) => item.actual);
    const trainMean = mean(train);
    const validationMean = mean(validation);
    windows.push({
      trainStartIndex: start,
      trainEndIndex: start + trainWindowSize - 1,
      validationStartIndex: start + trainWindowSize,
      validationEndIndex: start + trainWindowSize + validationWindowSize - 1,
      trainMean,
      validationMean,
      degradationPct: trainMean > 0 ? clamp(((trainMean - validationMean) / Math.max(0.0001, Math.abs(trainMean))) * 100, -100, 100) : validationMean < 0 ? 100 : 0,
    });
  }
  const validationMeans = windows.map((window) => window.validationMean);
  const positiveRatio = ratio(validationMeans, (value) => value > 0);
  const consistencyScore = clamp(positiveRatio * 100 - stdev(validationMeans) * 6);
  const degradationPct = windows.length ? Math.max(0, mean(windows.map((window) => window.degradationPct))) : 100;
  const stabilityScore = windows.length
    ? clamp(consistencyScore * 0.7 + (100 - degradationPct) * 0.3)
    : clamp((observations.length / Math.max(1, trainWindowSize + validationWindowSize)) * 55);

  return { stabilityScore, consistencyScore, degradationPct, windows };
}

function evaluateRegimes(observations: NormalizedObservation[]) {
  const buckets = new Map<string, number[]>();
  for (const item of observations) {
    const bucket = buckets.get(item.regime) ?? [];
    bucket.push(item.actual);
    buckets.set(item.regime, bucket);
  }
  const regimes = Array.from(buckets.entries()).map(([regime, values]) => ({
    regime,
    samples: values.length,
    meanOutcome: mean(values),
    score: clamp(50 + mean(values) * 8 + ratio(values, (value) => value > 0) * 35 - stdev(values) * 2),
  }));
  const scores = regimes.map((item) => item.score);
  const sampleCounts = regimes.map((item) => item.samples);
  const dominantShare = observations.length ? Math.max(0, ...sampleCounts) / observations.length : 1;
  const regimeDependencyScore = clamp(dominantShare * 100 + stdev(scores) * 0.6);
  const regimeRobustnessScore = clamp(mean(scores) - Math.max(0, dominantShare - 0.55) * 35);
  const adaptabilityScore = clamp(regimeRobustnessScore - Math.max(0, stdev(scores) - 18) * 0.8);

  return { regimeRobustnessScore, regimeDependencyScore, adaptabilityScore, regimes };
}

function evaluateCalibration(observations: NormalizedObservation[], minimumSamples: number) {
  const buckets = [0, 20, 40, 60, 80].map((start) => {
    const end = start + 20;
    const values = observations.filter((item) => item.confidence >= start && item.confidence < end + (end === 100 ? 1 : 0));
    const predictedConfidence = values.length ? mean(values.map((item) => item.confidence)) : start + 10;
    const realizedRate = values.length ? ratio(values.map((item) => item.actual), (value) => value > 0) * 100 : predictedConfidence;
    return {
      bucket: `${start}-${end}`,
      samples: values.length,
      predictedConfidence,
      realizedRate,
    };
  });
  const populated = buckets.filter((bucket) => bucket.samples > 0);
  const weightedError = populated.length
    ? populated.reduce((sum, bucket) => sum + Math.abs(bucket.predictedConfidence - bucket.realizedRate) * bucket.samples, 0) /
      Math.max(1, populated.reduce((sum, bucket) => sum + bucket.samples, 0))
    : 50;
  const samplePenalty = observations.length < minimumSamples ? (1 - observations.length / minimumSamples) * 25 : 0;
  const calibrationError = clamp(weightedError + samplePenalty);
  const confidenceDecay = clamp(calibrationError * 0.75 + samplePenalty);
  const calibrationScore = clamp(100 - calibrationError);

  return { calibrationScore, calibrationError, confidenceDecay, reliabilityCurve: buckets };
}

function evaluateParameterSensitivity(variants: RobustnessParameterVariant[]) {
  if (!variants.length) {
    return { stabilityScore: 35, fragilityScore: 65, gradient: 65, heatmap: [] };
  }
  const baseline = variants.find((variant) => variant.baselineScore != null)?.baselineScore ?? mean(variants.map((variant) => variant.score));
  const heatmap = variants.map((variant) => {
    const degradationPct = baseline > 0 ? clamp(((baseline - variant.score) / Math.max(0.0001, Math.abs(baseline))) * 100, -100, 100) : 0;
    return {
      id: variant.id,
      score: variant.score,
      degradationPct,
      passed: variant.passed !== false && variant.score >= Math.max(0, (variant.benchmarkScore ?? 0)),
    };
  });
  const passRate = ratio(heatmap, (item) => item.passed);
  const positiveDegradation = heatmap.map((item) => Math.max(0, item.degradationPct));
  const gradient = clamp(mean(positiveDegradation) + stdev(positiveDegradation));
  const fragilityScore = clamp((1 - passRate) * 100 + gradient * 0.55);
  const stabilityScore = clamp(passRate * 75 + (100 - gradient) * 0.25);

  return { stabilityScore, fragilityScore, gradient, heatmap };
}

function evaluateAdversarial(scenarios: RobustnessAdversarialScenario[]) {
  if (!scenarios.length) {
    return { robustnessScore: 50, executionRealismScore: 50, scenarios: [] };
  }
  const mapped = scenarios.map((scenario) => {
    const baseline = scenario.baselineScore ?? scenario.score;
    const degradationPct = baseline > 0 ? clamp(((baseline - scenario.score) / Math.max(0.0001, Math.abs(baseline))) * 100, -100, 100) : 0;
    return {
      id: scenario.id,
      degradationPct,
      resilienceScore: clamp(100 - Math.max(0, degradationPct) - (scenario.severity ?? 0) * 0.12),
    };
  });
  return {
    robustnessScore: mean(mapped.map((item) => item.resilienceScore)),
    executionRealismScore: clamp(mean(mapped.map((item) => item.resilienceScore)) - Math.max(0, ...mapped.map((item) => item.degradationPct)) * 0.15),
    scenarios: mapped,
  };
}

function evaluateParticipation(observations: NormalizedObservation[]) {
  const participated = observations.filter((item) => item.participated);
  const opportunityDensity = observations.length ? participated.length / observations.length : 0;
  const executableConviction = participated.length
    ? clamp(ratio(participated.map((item) => item.actual), (value) => value > 0) * 75 + mean(participated.map((item) => item.confidence)) * 0.25)
    : 0;
  const participationScore = clamp(opportunityDensity * 70 + executableConviction * opportunityDensity * 0.3);

  return { participationScore, opportunityDensity: opportunityDensity * 100, executableConviction };
}

function evaluateEnsemble(votes: RobustnessEnsembleVote[]) {
  if (!votes.length) {
    return { consensusScore: 50, dominancePenalty: 20, disagreementScore: 50 };
  }
  const totalWeight = votes.reduce((sum, vote) => sum + Math.max(0, vote.weight ?? 1), 0) || 1;
  const weightedDirection = votes.reduce((sum, vote) => sum + Math.sign(vote.direction) * clamp(vote.confidence) * Math.max(0, vote.weight ?? 1), 0) / totalWeight;
  const largestWeight = Math.max(...votes.map((vote) => Math.max(0, vote.weight ?? 1))) / totalWeight;
  const dominancePenalty = clamp(Math.max(0, largestWeight - 0.45) * 100);
  const disagreementScore = clamp(100 - stdev(votes.map((vote) => Math.sign(vote.direction) * clamp(vote.confidence))) * 0.9);
  const consensusScore = clamp(Math.abs(weightedDirection) - dominancePenalty * 0.35 + disagreementScore * 0.25);

  return { consensusScore, dominancePenalty, disagreementScore };
}

function evaluateLeakage(checks: LeakageCheck[]) {
  const violations = checks.flatMap((check) => {
    const issues: string[] = [];
    if (check.validationStartIndex <= check.trainEndIndex) issues.push(`${check.id}: validation overlaps training`);
    if (check.normalizedWithFuture === true) issues.push(`${check.id}: normalization used future data`);
    if (
      check.featureTimestampIndex != null &&
      check.labelTimestampIndex != null &&
      check.featureTimestampIndex >= check.labelTimestampIndex
    ) {
      issues.push(`${check.id}: feature timestamp is not earlier than label`);
    }
    return issues;
  });

  return { passed: violations.length === 0, violations };
}

function evaluateFeatureTrust(observations: NormalizedObservation[]) {
  const keys = Array.from(new Set(observations.flatMap((item) => Object.keys(item.features ?? {}))));
  if (!keys.length) {
    return { trustScore: 50, entropy: 100, features: [] };
  }
  const features = keys.map((key) => {
    const pairs = observations
      .map((item) => [item.features?.[key], item.actual] as const)
      .filter(([feature, actual]) => Number.isFinite(feature) && Number.isFinite(actual));
    const trust = pairs.length >= 3 ? clamp(50 + correlation(pairs.map(([feature]) => feature as number), pairs.map(([, actual]) => actual)) * 50) : 45;
    return { key, trust, weight: trust };
  });
  const total = features.reduce((sum, item) => sum + Math.max(0, item.weight), 0) || 1;
  const probabilities = features.map((item) => Math.max(0, item.weight) / total);
  const entropy = clamp(-probabilities.reduce((sum, value) => sum + (value > 0 ? value * Math.log2(value) : 0), 0) / Math.log2(Math.max(2, probabilities.length)) * 100);
  const trustScore = clamp(mean(features.map((item) => item.trust)) - Math.max(0, 35 - entropy) * 0.4);

  return { trustScore, entropy, features };
}

function evaluateStatisticalIntegrity(
  observations: NormalizedObservation[],
  minimumSamples: number,
  dataQualityScore: number,
  seed: number,
) {
  const values = observations.map((item) => item.actual);
  const minimumSampleScore = clamp((values.length / minimumSamples) * 100);
  const bootstrapStability = bootstrapPositiveMeanStability(values, seed);
  const monteCarloStability = monteCarloOrderStability(values, seed + 101);
  const score = clamp(mean([minimumSampleScore, bootstrapStability, monteCarloStability, dataQualityScore]));

  return { score, bootstrapStability, monteCarloStability, minimumSampleScore, dataQualityScore };
}

function estimateRealityGap(degradationPct: number, executionRealismScore: number, statisticalIntegrityScore: number) {
  const expectedDegradationPct = clamp(Math.max(0, degradationPct) * 0.45 + (100 - executionRealismScore) * 0.25 + (100 - statisticalIntegrityScore) * 0.18);
  return {
    realismScore: clamp(100 - expectedDegradationPct),
    expectedDegradationPct,
  };
}

function buildReasons(input: {
  overfitRisk: number;
  safetyGate: "allow" | "reduce" | "block";
  walkForward: number;
  regimes: number;
  calibration: number;
  parameters: number;
  adversarial: number;
  participation: number;
  leakage: { passed: boolean; violations: string[] };
  statisticalIntegrity: number;
}) {
  const reasons: string[] = [];
  if (input.overfitRisk > 30) reasons.push("Overfit risk is above the production threshold.");
  if (input.walkForward < 60) reasons.push("Rolling walk-forward validation is unstable.");
  if (input.regimes < 60) reasons.push("Performance is too dependent on a narrow regime set.");
  if (input.calibration < 60) reasons.push("Predicted confidence is poorly calibrated to realized outcomes.");
  if (input.parameters < 60) reasons.push("Nearby parameter variants are fragile.");
  if (input.adversarial < 60) reasons.push("Adversarial distortions create too much degradation.");
  if (input.participation < 35) reasons.push("Executable participation is too sparse.");
  if (!input.leakage.passed) reasons.push(...input.leakage.violations);
  if (input.statisticalIntegrity < 60) reasons.push("Statistical integrity is below the production floor.");
  if (input.safetyGate === "allow" && reasons.length === 0) reasons.push("Robustness diagnostics are within production tolerance.");
  return Array.from(new Set(reasons));
}

function inferRegime(actual: number, features: Record<string, number> | undefined): RobustnessRegime {
  const volatility = finite(features?.volatility ?? features?.risk ?? Math.abs(actual));
  const liquidity = finite(features?.liquidity ?? 70);
  if (actual < -6 || volatility > 78) return "panic";
  if (actual > 6 && volatility > 55) return "expansion";
  if (actual > 1.2 && volatility <= 55) return "trending";
  if (actual < 0 && volatility > 45) return "volatile";
  if (Math.abs(actual) < 0.8 && volatility < 25) return "low-volatility";
  if (liquidity < 35) return "liquidity-compression";
  if (actual > 0) return "recovery";
  return "sideways";
}

function bootstrapPositiveMeanStability(values: number[], seed: number) {
  if (!values.length) return 0;
  const generator = seeded(seed);
  let positive = 0;
  const rounds = 64;
  for (let round = 0; round < rounds; round += 1) {
    const sample = values.map(() => values[Math.floor(generator() * values.length)]);
    if (mean(sample) > 0) positive += 1;
  }
  return clamp((positive / rounds) * 100);
}

function monteCarloOrderStability(values: number[], seed: number) {
  if (!values.length) return 0;
  const generator = seeded(seed);
  let stable = 0;
  const rounds = 48;
  for (let round = 0; round < rounds; round += 1) {
    const shuffled = deterministicShuffle(values, generator);
    const curve = shuffled.reduce<number[]>((acc, value) => {
      const last = acc[acc.length - 1] ?? 0;
      acc.push(last + value);
      return acc;
    }, []);
    let peak = Number.NEGATIVE_INFINITY;
    let trough = 0;
    for (const value of curve) {
      peak = Math.max(peak, value);
      trough = Math.max(trough, peak - value);
    }
    if (curve[curve.length - 1] > 0 && trough < Math.max(12, Math.abs(curve[curve.length - 1]) * 0.65)) stable += 1;
  }
  return clamp((stable / rounds) * 100);
}

function deterministicShuffle(values: number[], generator: () => number) {
  const copy = values.slice();
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(generator() * (index + 1));
    const temp = copy[index];
    copy[index] = copy[swapIndex];
    copy[swapIndex] = temp;
  }
  return copy;
}

function seeded(seed: number) {
  let value = Math.floor(seed) || 1;
  return () => {
    value = (value * 1664525 + 1013904223) >>> 0;
    return value / 2 ** 32;
  };
}

function weightedMean(values: number[], weights: number[]) {
  /* c8 ignore next */
  const totalWeight = values.reduce((sum, _value, index) => sum + (weights[index] ?? 1), 0) || 1;
  /* c8 ignore next */
  return values.reduce((sum, value, index) => sum + clamp(value) * (weights[index] ?? 1), 0) / totalWeight;
}

function ratio<T>(values: T[], predicate: (value: T) => boolean) {
  return values.length ? values.filter(predicate).length / values.length : 0;
}

function finite(value: unknown, fallback = 0) {
  const numberValue = Number(value);
  return Number.isFinite(numberValue) ? numberValue : fallback;
}

/* c8 ignore next */
function correlation(left: number[], right: number[]) {
  const count = Math.min(left.length, right.length);
  /* c8 ignore next */
  if (count < 2) return 0;
  const leftValues = left.slice(0, count);
  const rightValues = right.slice(0, count);
  const leftMean = mean(leftValues);
  const rightMean = mean(rightValues);
  const numerator = leftValues.reduce((sum, value, index) => sum + (value - leftMean) * (rightValues[index] - rightMean), 0);
  const denominator = Math.sqrt(
    leftValues.reduce((sum, value) => sum + (value - leftMean) ** 2, 0) *
      rightValues.reduce((sum, value) => sum + (value - rightMean) ** 2, 0),
  );
  return denominator > 0 ? numerator / denominator : 0;
}

